/**
 * Hundred Steps to Life — Field Notes design reminder:
 * Course content should be practical, non-shaming, rooted in Islamic values,
 * and always follow Learn → Understand → Prove → Apply → Improve.
 */

export type CoursePhase = {
  id: number;
  title: string;
  shortTitle: string;
  range: string;
  color: "moss" | "clay" | "gold" | "sky" | "ink";
  island: string;
  landscape: string;
  landmark: string;
  memoryCue: string;
  routeCue: string;
};

export type QuizQuestion = {
  question: string;
  options: string[];
  answer: number;
  explanation: string;
  /** "method" questions are about how the course works and recur across days. */
  scope?: "lesson" | "method" | "review";
  /** For a review question, the day it originally belonged to. */
  fromDay?: number;
};

export type Lesson = {
  day: number;
  phase: CoursePhase;
  title: string;
  why: string;
  lesson: string;
  keyIdea: string;
  example: string;
  actionPrompt: string;
  actionHint: string;
  bonus: string;
  quiz: QuizQuestion[];
};

const phases: CoursePhase[] = [
  { id: 1, title: "Foundation", shortTitle: "Foundations", range: "Days 1–10", color: "moss", island: "Firstlight Cove", landscape: "sunrise shoreline", landmark: "wayfinding post", memoryCue: "gold horizon marker", routeCue: "arrive and choose a direction" },
  { id: 2, title: "Mindset & Deen", shortTitle: "Mindset", range: "Days 11–20", color: "gold", island: "Lantern Gardens", landscape: "quiet geometric garden", landmark: "path lantern", memoryCue: "a steady pool of light", routeCue: "move with intention" },
  { id: 3, title: "Discipline & Habits", shortTitle: "Discipline", range: "Days 21–30", color: "clay", island: "Training Ridge", landscape: "rocky uphill trail", landmark: "stone cairn", memoryCue: "carefully spaced markers", routeCue: "return to the climb" },
  { id: 4, title: "Deen & Worship", shortTitle: "Deen", range: "Days 31–40", color: "sky", island: "Sakina Point", landscape: "masjid at night", landmark: "lit dome and minaret", memoryCue: "a brass compass", routeCue: "look closely, then choose" },
  { id: 5, title: "Character & Relationships", shortTitle: "Character", range: "Days 41–50", color: "moss", island: "Bridgehaven", landscape: "warm coastal crossing", landmark: "broad bridge", memoryCue: "two shores meeting", routeCue: "build trust across the water" },
  { id: 6, title: "Health & Energy", shortTitle: "Health", range: "Days 51–60", color: "clay", island: "Wildwood Valley", landscape: "open forest valley", landmark: "old evergreen", memoryCue: "a flowing stream", routeCue: "protect energy for the path" },
  { id: 7, title: "Skills & Creativity", shortTitle: "Skills", range: "Days 61–70", color: "sky", island: "Maker’s Quay", landscape: "working harbour workshop", landmark: "pier workbench", memoryCue: "a crafted tool mark", routeCue: "make something useful" },
  { id: 8, title: "Money & Creating Value", shortTitle: "Value", range: "Days 71–80", color: "gold", island: "Value Harbour", landscape: "protected trade harbour", landmark: "signal tower", memoryCue: "a measured ledger line", routeCue: "create value responsibly" },
  { id: 9, title: "Leadership & Responsibility", shortTitle: "Leadership", range: "Days 81–90", color: "ink", island: "Common Ground", landscape: "connected civic hillside", landmark: "gathering tree", memoryCue: "a circle of meeting stones", routeCue: "take responsibility with others" },
  { id: 10, title: "Integration & Long-Term Life", shortTitle: "Integration", range: "Days 91–100", color: "moss", island: "The Summit", landscape: "wide highland peak", landmark: "summit beacon", memoryCue: "the distant gold light", routeCue: "bring the whole route together" },
];

type Topic = Omit<Lesson, "day" | "phase">;

const choice = (right: string, wrongA: string, wrongB: string, wrongC: string, explanation: string): QuizQuestion => ({
  question: "Which answer best captures today’s lesson?",
  options: [right, wrongA, wrongB, wrongC],
  answer: 0,
  explanation,
});

const standardQuiz = (right: string, wrongA: string, wrongB: string, wrongC: string, explanation: string): QuizQuestion[] => [
  choice(right, wrongA, wrongB, wrongC, explanation),
  {
    question: "What should happen after you understand a useful idea?",
    options: ["Apply a small version of it in real life", "Collect more quotes about it", "Wait until motivation appears", "Assume understanding is enough"],
    answer: 0,
    explanation: "The course is built around moving from understanding to a small, real action.",
  },
  {
    question: "How should you respond if you miss a step?",
    options: ["Notice what happened and return without drama", "Decide the whole effort has failed", "Double every task tomorrow", "Hide it and pretend it did not matter"],
    answer: 0,
    explanation: "Sustainable discipline includes honest recovery rather than shame or extremes.",
  },
];

const topics: Topic[][] = [
  [
    { title: "Start Small, Start Today", why: "Nothing in this course works until you have proved to yourself that you can begin.", lesson: "Most people do not fail at self-improvement because the plan was wrong. They fail because they never started, or because they started with something so large it collapsed within a week. Today asks for the opposite: one small action, done today, chosen because it is genuinely easy. The action itself barely matters. What matters is the evidence — that when you decide to do something, it actually gets done. Everything in the next hundred days is built on that.", keyIdea: "Begin with something small enough that there is no honest reason not to do it.", example: "Instead of building a full study timetable, you open the book and read one page. The page matters less than the fact that a decision turned into an action.", actionPrompt: "Choose one small action you can finish in under five minutes, do it today, and write down what it was.", actionHint: "Keep it small: one page, one wash-up, one message, one set of push-ups. Small is the point.", bonus: "Do a second small action tomorrow morning, before you look at your phone.", quiz: [{ question: "You have decided to start improving something in your life. What is the strongest first move?", options: ["Complete one small action today", "Write a detailed plan for the next hundred days", "Wait until the beginning of next month", "Read three books about discipline first"], answer: 0, explanation: "A plan you never start teaches you nothing. A finished action, however small, is real evidence." }, { question: "Why does the course open with something this small?", options: ["Because a completed small action proves your decisions turn into behaviour", "Because small actions are all that most people can manage", "Because the course gets easier as it goes on", "Because effort does not matter at the start"], answer: 0, explanation: "Day 1 is about establishing that you can start, not about the size of what you started." }, { question: "You planned a two-hour session and managed ten minutes. What is the honest reading of that?", options: ["You started, which is the part today is testing", "The session was a failure", "You should have planned four hours to be safe", "You are not suited to this kind of work"], answer: 0, explanation: "Ten minutes done beats two hours planned. Today measures starting, not volume." }, { question: "Which of these is a well-chosen Day 1 action?", options: ["Washing the dishes that are already in the sink", "Committing to wake at four every morning from now on", "Rewriting your entire daily routine tonight", "Promising to give up every bad habit at once"], answer: 0, explanation: "A good first action is small, specific, and finishable today. The other three are announcements, not actions." }, { question: "Someone tells you that actions this small are pointless. What is the honest reply?", options: ["Small actions are what the large ones are built out of", "They are right, but you have to start somewhere", "Size does not matter in anything", "Only people who lack discipline start small"], answer: 0, explanation: "A large consistent effort is a long series of small completed ones. There is no other route to it." }, { question: "When should today's action happen?", options: ["Today, in the first gap you get", "When you next feel motivated", "Once everything else on your list is finished", "Tomorrow morning, when you are fresh"], answer: 0, explanation: "Motivation is not scheduled. The first available gap is the one you can actually control." }, { question: "You finished your action in two minutes and it felt almost too easy. What does that tell you?", options: ["You chose it well", "You should have chosen something harder", "The day does not count", "You are avoiding real effort"], answer: 0, explanation: "An action that felt easy is an action that got done. That is exactly what Day 1 is for." }, { question: "What is Day 1 actually testing?", options: ["Whether a decision you make turns into something you do", "How much you can achieve in one day", "Whether you are naturally disciplined", "How well you can plan ahead"], answer: 0, explanation: "The whole course depends on the link between deciding and doing. Today tests that link at its smallest." }, { question: "What should you write down once the action is finished?", options: ["The action you actually completed", "The action you intended to complete", "A list of everything you plan to do this week", "How you felt about the course"], answer: 0, explanation: "Recording what was done, not what was planned, is what makes the record worth anything later." }, { question: "You reach the end of the day and have not done anything. What is the useful response?", options: ["Do one small action now and carry on", "Restart the course from the beginning next month", "Decide you are not someone who finishes things", "Do ten actions tomorrow to make up for it"], answer: 0, explanation: "Returning without drama is a skill the course will ask for repeatedly. It starts here." }] },
    { title: "Notice Your Day", why: "You cannot change a routine you have never actually looked at.", lesson: "Your day already has a shape. There are hours when you are sharp and hours when you are useless, moments you reach for your phone without ever deciding to, and stretches that vanish without leaving a memory. Almost all of it runs unobserved. Today you are only looking: no changes, no judgement, one honest observation about how your day genuinely runs. Noticing comes before fixing, and it is far easier.", keyIdea: "Observe your routine accurately before trying to change it.", example: "You notice you pick up your phone the moment you sit down to work. Nothing has changed yet, but you now know where the leak is.", actionPrompt: "Write down one honest thing you noticed today about how your day actually runs.", actionHint: "Look for a pattern rather than a failure: when your energy is best, what you do automatically, where time disappears.", bonus: "Note the exact time of day your attention was at its sharpest.", quiz: [{ question: "What is today asking you to do?", options: ["Observe one real pattern in your day without changing it", "Fix the worst part of your routine", "Design a better schedule", "Decide which of your habits are bad"], answer: 0, explanation: "Observation comes first. A change made before you have looked is a guess." }, { question: "Which of these counts as a useful observation?", options: ["You lose about an hour between getting home and starting anything", "You are lazy in the afternoons", "Your routine is a mess", "You need to try harder tomorrow"], answer: 0, explanation: "A useful observation is specific and factual. The others are verdicts, and verdicts cannot be acted on." }, { question: "You notice something about your day that you do not like. What should you do today?", options: ["Write it down and leave it there for now", "Fix it immediately", "Decide it is too late to change", "Keep it to yourself and forget it"], answer: 0, explanation: "Today is a measurement. Acting on a single observation before you understand it usually fixes the wrong thing." }, { question: "Why is noticing put before changing?", options: ["Because a change aimed at the wrong thing wastes the effort", "Because noticing is easier than changing", "Because the course wants to start slowly", "Because most habits cannot be changed"], answer: 0, explanation: "You get one honest attempt at a change before you lose interest. Aim it at the real pattern." }, { question: "Where is the most useful place to look for a pattern?", options: ["The parts of the day you cannot remember afterwards", "The parts you are already proud of", "The parts other people comment on", "The parts that are already scheduled"], answer: 0, explanation: "Unremembered time is unobserved time, which is where the largest patterns tend to hide." }, { question: "You realise you have three observations rather than one. What now?", options: ["Write them all down and pick the one that matters most", "Discard two of them at random", "Try to act on all three", "Start the day again tomorrow"], answer: 0, explanation: "More information is not a problem. Choosing which piece to act on is the actual skill." }, { question: "What makes an observation honest?", options: ["It describes what happened, not what you wish had happened", "It sounds serious", "It makes you feel bad about yourself", "It matches what you wrote yesterday"], answer: 0, explanation: "Honesty here means accuracy. Discomfort is not evidence that you have looked properly." }, { question: "What is the point of noticing when your attention is best?", options: ["So you can later put important work where your attention already is", "So you can feel better about your bad hours", "So you can work at that time every single day", "So you can prove you are a morning person"], answer: 0, explanation: "Scheduling with your real energy pattern is much cheaper than fighting it." }] },
    { title: "Clear One Space", why: "A cleared space costs almost nothing to make and quietly changes how you behave in it.", lesson: "Your surroundings make some behaviours easy and others irritating. A desk covered in things is a desk you avoid. A made bed is a bed you are less likely to lie on at three in the afternoon. Today is one small area — a desk, a shelf, a bag, a phone home screen — not the whole room. The aim is to feel the difference a cleared space makes, so that when you set up your environment properly later, you already know it works.", keyIdea: "A small change to a space changes the behaviour that happens in it.", example: "You clear the desk you study at. The next evening you sit down straight away instead of spending ten minutes moving things.", actionPrompt: "Clear and tidy one small area you use every day, then note how it feels to use it afterwards.", actionHint: "One area only: a desk, a single shelf, your bag, or the home screen of your phone.", bonus: "Keep that one area clear for the rest of the week.", quiz: [{ question: "You have twenty minutes and a messy room. What is today's task?", options: ["Clear one small area you use every day", "Clean the entire room properly", "Make a plan to clean it at the weekend", "Tidy whichever part is most visible to guests"], answer: 0, explanation: "One area, finished, teaches you more than a whole room half done." }, { question: "Why does a cleared desk make work easier?", options: ["It removes the small delays and decisions before starting", "It makes you a tidier person", "It proves you are disciplined", "It gives you more physical space to work in"], answer: 0, explanation: "Most of the cost of a cluttered space is the friction before you begin, not the space itself." }, { question: "Which of these is a legitimate small area for today?", options: ["The home screen of your phone", "Your entire bedroom", "The whole kitchen", "Every drawer in the house"], answer: 0, explanation: "A phone home screen is a space you use constantly, and clearing it is genuinely small." }, { question: "You clear the area and it is untidy again by the evening. What does that suggest?", options: ["Something about how the space is used puts things there", "The effort was wasted", "You are incapable of being tidy", "You should clear it twice a day from now on"], answer: 0, explanation: "A space that refills has a cause. Finding the cause is more useful than clearing it repeatedly." }, { question: "What is the point of noticing how the space feels afterwards?", options: ["It connects a small change to a real difference you can feel", "It makes the task more enjoyable", "It gives you something to write down", "It proves the lesson was correct"], answer: 0, explanation: "Feeling the difference is what makes you willing to do it again without being told." }, { question: "Which change would most help someone who never starts their reading?", options: ["Leaving the book open on the desk they sit at", "Buying a better bookshelf", "Setting three reminders on their phone", "Telling people they are going to read more"], answer: 0, explanation: "Reducing the distance between you and the action beats adding pressure to do it." }, { question: "How does this lesson relate to willpower?", options: ["It reduces how much willpower the situation needs in the first place", "It replaces willpower entirely", "It builds willpower through repeated effort", "It proves willpower is a myth"], answer: 0, explanation: "Arranging the space is a way of spending less willpower on the same result." }, { question: "What is the strongest reason to keep the area clear all week?", options: ["Repeating it is what turns it from a task into a default", "It looks better", "It gives you a longer streak", "Other people will notice"], answer: 0, explanation: "One clearance is an event. A week of it becomes the normal state of the space." }] },
    { title: "Do It Before You’re Asked", why: "Doing a useful thing without being told is the beginning of being someone people rely on.", lesson: "There is a difference between a person who helps when asked and a person who sees what needs doing and does it. The second is rarer, and it is built by practice rather than personality. Today, find one useful thing at home, in class or at work that nobody has asked you to do, and do it before anyone raises it. Do not announce it afterwards. The habit you are building is noticing, and noticing is quieter than it sounds.", keyIdea: "Seeing what needs doing, and doing it unprompted, is a habit you can practise.", example: "You take the bins out before anyone mentions them. Nobody comments, which is fine — the point was the noticing.", actionPrompt: "Do one useful thing today that nobody asked you to do, and do not tell anyone you did it.", actionHint: "Look for something ordinary: a chore, clearing up after other people, refilling something that has run out.", bonus: "Do it again this week for someone who will never know it was you.", quiz: [{ question: "What separates today's action from ordinary helpfulness?", options: ["Nobody asked you to do it", "It is harder than usual", "It is done for a stranger", "It takes a long time"], answer: 0, explanation: "Being asked removes the part being practised, which is noticing that something needs doing." }, { question: "Why does the lesson ask you not to announce it?", options: ["So the habit is about noticing rather than about being seen", "Because helping should be a secret", "Because people find it annoying", "Because it makes the action worth more later"], answer: 0, explanation: "Announcing it turns the practice into something you do for the response instead of the noticing." }, { question: "Which of these fits today best?", options: ["Refilling something you noticed had run out", "Doing a chore your parents reminded you about", "Offering to help if anyone needs it", "Promising to be more useful in future"], answer: 0, explanation: "Only the first is unprompted and completed. The rest are prompted, conditional, or a promise." }, { question: "You do something useful and nobody notices at all. What does that mean?", options: ["The practice worked exactly as intended", "It was a waste of effort", "You should have chosen something more visible", "You should mention it in passing"], answer: 0, explanation: "Being unnoticed is the normal outcome, and it does not reduce the value of the habit." }, { question: "What skill is actually being trained today?", options: ["Noticing what needs doing before it is raised", "Working quickly", "Being agreeable", "Doing more work than other people"], answer: 0, explanation: "The doing is easy. Seeing it in the first place is the part that takes practice." }, { question: "Someone else gets the credit for what you did. What is the useful response?", options: ["Let it go, since the point was the habit, not the credit", "Correct them straight away", "Stop doing unprompted work", "Mention it to someone else so the truth gets around"], answer: 0, explanation: "Chasing the credit converts the practice into something else entirely." }, { question: "How does this connect to being someone people rely on?", options: ["Reliability is built from small unprompted actions repeated over time", "It makes people owe you favours", "It shows people you are capable of big things", "It means you never have to be asked again"], answer: 0, explanation: "Trust accumulates from ordinary things done without being chased." }, { question: "What size should today's action be?", options: ["Small and ordinary", "Large enough that it clearly counts", "Large enough that people notice", "Whatever is left over at the end of the day"], answer: 0, explanation: "A small ordinary action is repeatable, which is what makes it a habit rather than a gesture." }] },
    { title: "Ten Minutes Without a Screen", why: "You cannot tell how much a habit has hold of you until you put it down for a moment.", lesson: "Ten minutes without a screen is not a hardship. What makes it worth doing is what happens in your head while it lasts: the reach for the phone that was never a decision, the discomfort of an unfilled minute, the thoughts that only arrive when nothing else is competing for the space. Today is not a case against screens. It is a short, honest measurement of how automatic the reaching has become.", keyIdea: "A short break from a habit shows you how automatic it has become.", example: "You sit for ten minutes without your phone and catch yourself reaching for it four times. That is something you could not have learned by thinking about it.", actionPrompt: "Spend ten minutes with no screen at all, and write down what you noticed about your own reaction.", actionHint: "Put the phone in another room rather than face-down beside you, and count the times you reach for it.", bonus: "Do the same ten minutes tomorrow and see whether the number changes.", quiz: [{ question: "What is the ten minutes actually measuring?", options: ["How automatic your reaching for a screen has become", "How long you can resist temptation", "Whether you are addicted to your phone", "How productive you are without distractions"], answer: 0, explanation: "Today is a measurement, not a test of endurance or a diagnosis." }, { question: "Where should the phone be during the ten minutes?", options: ["In another room", "Face-down next to you", "In your pocket, on silent", "In your hand, with the screen off"], answer: 0, explanation: "A phone within reach is still a decision you have to keep making. Distance removes the decision." }, { question: "You reach for your phone six times in ten minutes. What is the correct conclusion?", options: ["You have learned something specific and useful about the habit", "You have failed the exercise", "You need to stop using your phone entirely", "The exercise was too short to mean anything"], answer: 0, explanation: "The count is the result. A high number is information, not a verdict." }, { question: "Which reaction to the ten minutes is the most useful one to notice?", options: ["The discomfort of a minute with nothing in it", "How bored you were overall", "Whether you managed the full ten minutes", "How much you missed a particular app"], answer: 0, explanation: "The discomfort of empty time is the mechanism the habit runs on, which makes it the useful thing to see." }, { question: "What is this lesson not saying?", options: ["That screens are bad and should be avoided", "That habits can run without a decision", "That short measurements can be informative", "That noticing comes before changing"], answer: 0, explanation: "The lesson measures a habit rather than passing judgement on the technology." }, { question: "Why count the reaches rather than just noticing them?", options: ["A number can be compared tomorrow", "Counting keeps you occupied", "It makes the exercise harder", "It proves you were paying attention"], answer: 0, explanation: "A count turns a vague impression into something you can actually track." }, { question: "You do the ten minutes and notice nothing at all. What now?", options: ["Record that honestly and try again tomorrow", "Repeat it until something happens", "Conclude the exercise does not work for you", "Extend it to an hour"], answer: 0, explanation: "An honest null result is still a result, and the second attempt often differs from the first." }, { question: "What is the strongest reason to repeat this tomorrow?", options: ["A second number tells you whether the first one was typical", "Repetition makes it easier", "It builds up your tolerance", "One day is never enough for anything"], answer: 0, explanation: "A single measurement has no context. The second one is what turns it into information." }] },
    { title: "Name What You Want to Improve", why: "A vague wish to be better cannot be started; a named one can.", lesson: "Wanting to be more disciplined is not something you can begin on Monday. Praying Fajr on time is. Naming the thing turns a feeling into a target, and a target can be measured, broken down, and returned to after a bad week. Today, name one area — prayer, study, health, family, money, a skill — and write one honest sentence about why it matters to you. The reason carries as much weight as the target, because the reason is what you will need on the days you do not feel like it.", keyIdea: "Name one specific area and one honest reason. A vague goal has no first step.", example: "Get fit becomes walk for twenty minutes after Asr, because I am exhausted every evening and it is costing me my study time.", actionPrompt: "Write down one specific area you want to improve and one honest reason it matters to you.", actionHint: "Be specific enough that someone else could tell whether you had done it.", bonus: "Say the same sentence out loud to someone you trust.", quiz: [{ question: "Which of these can actually be started tomorrow?", options: ["Read two pages of Qur'an after Fajr", "Become a more spiritual person", "Be better with my time", "Stop wasting my life"], answer: 0, explanation: "Only the first names an action, a size and a time. The others are feelings about a direction." }, { question: "Why does the lesson ask for a reason as well as a target?", options: ["The reason is what you fall back on when the target stops being appealing", "It makes the goal sound more convincing", "It proves the goal is worthwhile", "It helps other people understand you"], answer: 0, explanation: "Targets survive on their reasons once the initial interest has gone." }, { question: "What makes a reason honest rather than impressive?", options: ["It is true even if nobody else would find it inspiring", "It sounds selfless", "It refers to a long-term ambition", "It would convince a stranger"], answer: 0, explanation: "A reason you invented for an audience will not hold you on a bad Tuesday." }, { question: "You want to improve five areas at once. What is the strongest move?", options: ["Name one and start there", "Name all five and work on them together", "Pick the hardest one", "Wait until you can give them all proper attention"], answer: 0, explanation: "One started area beats five named ones. The others are still there afterwards." }, { question: "Which target is specific enough to be checked?", options: ["Twenty minutes of walking after Asr", "More exercise", "Getting healthier this year", "Being less lazy about fitness"], answer: 0, explanation: "A specific target has an amount and a time, so anyone could tell whether it happened." }, { question: "What is the risk of a target that is too vague?", options: ["You can never tell whether you have done it, so you never do", "It is too easy to achieve", "Other people will not take it seriously", "It makes you overconfident"], answer: 0, explanation: "Vague targets fail quietly, because there is no moment at which they were missed." }, { question: "Why say the sentence out loud to someone?", options: ["Saying it out loud usually exposes whether it is specific", "It forces you to keep it", "It makes them responsible for checking on you", "It makes the goal official"], answer: 0, explanation: "Vagueness is much easier to hear than to read, which is why saying it works." }, { question: "Your named area turns out to be the wrong one after a week. What then?", options: ["Change it, since you now know something you did not know before", "Stick with it out of principle", "Start the course again", "Add a second area alongside it"], answer: 0, explanation: "The first choice is a starting hypothesis, and a week of real information is worth acting on." }] },
    { title: "Finish One Postponed Thing", why: "An unfinished small task costs more in the carrying than it ever does in the doing.", lesson: "There is something you have been meaning to do for days. A message you have not sent, a form, a phone call — a job that takes ten minutes and has already taken a week of low-level guilt. Postponed tasks do not sit still. They get heavier the longer they wait, and the weight has almost nothing to do with their size. Today you clear one. Not the biggest one: one you can genuinely finish today.", keyIdea: "Most of the cost of a postponed task is the postponing.", example: "The email you have avoided for six days takes four minutes to write. The relief is completely out of proportion to the effort.", actionPrompt: "Complete one small thing you have been putting off, and note how long it actually took.", actionHint: "Choose something you can finish today in under half an hour.", bonus: "Write down the second thing you have been postponing, and put a date on it.", quiz: [{ question: "Which task should you choose today?", options: ["A small one you have been postponing and can finish today", "The largest thing on your list", "The one you are most afraid of", "Whichever one is due first"], answer: 0, explanation: "The point is completion. A task you cannot finish today teaches you nothing about the cost of postponing." }, { question: "Why does the lesson ask you to note how long it actually took?", options: ["The real time is almost always shorter than the dread suggested", "So you can plan better next week", "To prove you were efficient", "To compare yourself with other people"], answer: 0, explanation: "Seeing the gap between the dread and the actual time is what makes you start faster next time." }, { question: "Where does most of a postponed task's weight come from?", options: ["Carrying it around unfinished", "The difficulty of the work", "The consequences of being late", "Other people's expectations"], answer: 0, explanation: "A ten-minute job carried for a week costs a week of attention and ten minutes of work." }, { question: "You finish the task and immediately think of three more. What is the useful response?", options: ["Write them down and choose one for tomorrow", "Do all three now while you have momentum", "Ignore them, since today is done", "Feel bad about how many there are"], answer: 0, explanation: "Capturing them stops them circling, and one per day is a pace that survives." }, { question: "A friend says they will do their postponed task when they have more time. What is the honest reply?", options: ["More time rarely arrives, and the task is usually shorter than it feels", "That is reasonable if they are busy", "They should do it when they feel ready", "They should give up on it entirely"], answer: 0, explanation: "Waiting for time is how a ten-minute task turns into a month-long weight." }, { question: "What makes today's task different from ordinary work?", options: ["It has been carried unfinished, so finishing it releases more than the time it took", "It is harder than normal work", "It is more important than normal work", "It has a deadline attached"], answer: 0, explanation: "The return on clearing a postponed task is disproportionate, because you get the carrying back too." }, { question: "You start the task and realise it will take three hours, not thirty minutes. What now?", options: ["Do a defined first part today and schedule the rest", "Abandon it and pick another", "Push through all three hours now", "Put it back on the list for another week"], answer: 0, explanation: "A large task still yields to a defined first piece. Putting it back is how it got heavy in the first place." }, { question: "What is the point of dating the second postponed thing?", options: ["An undated task has no moment at which it is late", "It makes you accountable to someone", "It makes the task feel more serious", "It stops you forgetting it"], answer: 0, explanation: "A date is what converts an intention into something that can actually be missed or met." }] },
    { title: "How You Talk to Yourself", why: "How you speak to yourself after a mistake decides how quickly you get back to work.", lesson: "Everyone gets things wrong. What varies is the ten minutes afterwards. Some people run a commentary — typical, I always do this, I never finish anything — which is not accountability. It is noise, and it makes the next attempt harder rather than more careful. Useful self-talk is specific and short: what went wrong, what to do differently, then back to it. Today you are only listening to your own commentary. You are not fixing it yet.", keyIdea: "Notice your self-talk after a mistake. Specific beats harsh.", example: "You forget something important. Instead of I am useless, you note I did not write it down — which is a fixable problem rather than a verdict on your character.", actionPrompt: "The next time something goes wrong today, write down exactly what you said to yourself.", actionHint: "Write the words as they came, before you tidy them up into something more reasonable.", bonus: "Rewrite one of those sentences as a specific, fixable observation.", quiz: [{ question: "Which of these is accountability rather than noise?", options: ["I did not write it down, so I will keep a list", "I always mess things up", "I am hopeless at this", "Nothing ever goes right for me"], answer: 0, explanation: "Accountability names a cause you can change. The rest are verdicts, and verdicts have no next step." }, { question: "Why does harsh self-talk make the next attempt harder?", options: ["It produces no information, only reluctance to try again", "It lowers your standards", "It makes you overconfident", "It makes other people less willing to help"], answer: 0, explanation: "Harshness feels like rigour, but it leaves you with nothing specific to do differently." }, { question: "What are you asked to do today?", options: ["Record your self-talk exactly as it happened", "Replace your self-talk with something positive", "Stop criticising yourself entirely", "Explain why the mistake was not your fault"], answer: 0, explanation: "Today is observation. Changing the commentary before you have heard it accurately rarely lasts." }, { question: "Why write the words down before tidying them?", options: ["The tidied version is not what you actually said to yourself", "It is faster", "It makes for a better record", "It stops you forgetting the mistake"], answer: 0, explanation: "Editing on the way to the page is how the real commentary escapes being noticed." }, { question: "Someone tells you that being hard on yourself is what keeps standards high. What is the accurate reply?", options: ["Specific correction keeps standards high; general contempt just slows the return", "They are right, and comfort makes people lazy", "Standards do not matter much", "Being hard on yourself works for some people"], answer: 0, explanation: "The useful part is the specificity, not the severity." }, { question: "What is the difference between I am useless and I did not prepare?", options: ["The second names something you can change tomorrow", "The second is kinder", "The second is less honest", "There is no real difference"], answer: 0, explanation: "One is a fixed statement about you; the other is a description of a repeatable behaviour." }, { question: "How long should the honest response to a mistake take?", options: ["Short: what happened, what to change, then back to work", "As long as it takes to feel bad enough", "Until you have apologised to everyone involved", "Until you are certain it will never happen again"], answer: 0, explanation: "Extending it does not add rigour. It only adds weight." }, { question: "You notice your commentary is much harsher than anything you would say to a friend. What does that tell you?", options: ["You are applying a standard you do not actually believe is fair", "You have higher standards for yourself", "You are being appropriately honest", "Your friends are easier to forgive"], answer: 0, explanation: "A standard you would never apply to anyone else is worth examining rather than obeying." }] },
    { title: "One Simple Help", why: "Being useful to someone else is one of the fastest ways out of your own circling thoughts.", lesson: "This is not a large act of service. It is one simple thing for one person: carrying something, explaining something, covering a small job, sitting with someone having a bad day. Help this size is easy to arrange and does two things at once. It is genuinely good for the other person, and it reliably pulls you out of your own head. Our tradition does not treat the small consistent good as insignificant, and there is a reason for that.", keyIdea: "One small, real act of help, done today.", example: "You spend five minutes explaining something to a classmate who missed it. It costs you almost nothing and changes their week.", actionPrompt: "Help one person with one simple thing today.", actionHint: "Keep it small and real. Do not turn it into a project.", bonus: "Do it for someone who is in no position to return the favour.", quiz: [{ question: "What size of help does today ask for?", options: ["One simple thing for one person", "Something significant enough to matter", "As much as you can fit into the day", "Whatever the person asks for"], answer: 0, explanation: "Small and completed today. Scale is not what is being practised." }, { question: "Why does helping someone else affect your own state?", options: ["It moves your attention out of your own circling thoughts", "It makes you feel superior", "It earns you favours later", "It distracts you from your problems permanently"], answer: 0, explanation: "The shift in attention is the mechanism, and it is reliable even when the help is small." }, { question: "Which of these fits today?", options: ["Explaining something to someone who missed it", "Planning a large charity project", "Promising to help someone next week", "Telling someone you are always available"], answer: 0, explanation: "Only the first is small, real and finished today." }, { question: "Why help someone who cannot return the favour?", options: ["It keeps the act about them rather than about the exchange", "It is more impressive", "It builds a better reputation", "It is the only kind of help that counts"], answer: 0, explanation: "Removing the possibility of return is what tests whether the help was for them." }, { question: "You offer help and it is turned down. What is the useful response?", options: ["Accept it without pressing, and find something else", "Insist, since you were trying to help", "Decide they are ungrateful", "Stop offering help to people"], answer: 0, explanation: "Help that has to be pushed on someone stops being help." }, { question: "What is the risk of turning this into something larger?", options: ["A project needs planning, and the day passes without anyone being helped", "It might cost too much money", "People will expect more from you", "It becomes about you"], answer: 0, explanation: "The reason for keeping it small is that small things actually get done today." }, { question: "Someone thanks you far more than the help was worth. What does that suggest?", options: ["The value of small help is often invisible from your side", "They are being polite", "You should have done less", "You misjudged how hard it was"], answer: 0, explanation: "The cost to you and the value to them are frequently very different numbers." }, { question: "How does this connect to the rest of the course?", options: ["Small consistent good is the same principle applied outward", "It is a break from the harder days", "It replaces the need for personal discipline", "It is only about being liked"], answer: 0, explanation: "The course is built on small repeated actions. This is one aimed at someone else." }] },
    { title: "Ten Days In", why: "A short honest review turns ten scattered days into something you can build on.", lesson: "Ten days is enough to show a pattern. Look back: which days did you actually complete, which did you skip, and what did the completed ones have in common — time of day, size of task, how tired you were? Then choose one thing worth keeping. Not five. One habit from these ten days that you want to carry forward. Reviewing is not judging. You are gathering information, not issuing a verdict.", keyIdea: "Review the ten days, and choose one habit worth keeping.", example: "You notice every day you completed was done before midday, and every day you skipped was left until the evening. That is a scheduling fact, not a character flaw.", actionPrompt: "Review your first ten days and write down one habit you want to keep.", actionHint: "Look for what the completed days had in common, rather than counting how many you missed.", bonus: "Write down one thing from the ten days that clearly did not work, and stop doing it.", quiz: [{ question: "What are you looking for when you review the ten days?", options: ["What the completed days had in common", "How many days you missed", "Whether you deserve to continue", "Which lesson was the most interesting"], answer: 0, explanation: "The pattern behind the days that worked is the part you can reuse. The count is not." }, { question: "You completed six days out of ten. What is the useful reading?", options: ["Six worked, and it is worth knowing why those six did", "You have failed the first section", "You should repeat the ten days", "You need to be stricter with yourself"], answer: 0, explanation: "Six completed days contain a pattern. Treating it as a score throws that information away." }, { question: "How many habits should you carry forward?", options: ["One", "All the ones that went well", "Three or four", "As many as you can manage"], answer: 0, explanation: "One kept habit survives. A list of five is a plan you will quietly abandon." }, { question: "You notice you completed every day before midday and skipped every evening one. What kind of finding is that?", options: ["A scheduling fact you can act on", "Evidence that you lack discipline", "A coincidence", "A reason to stop doing evening tasks forever"], answer: 0, explanation: "Timing findings are among the most actionable, and they say nothing about character." }, { question: "What is the difference between reviewing and judging?", options: ["Reviewing produces a next step; judging produces a verdict", "Reviewing is more positive", "Judging is more honest", "There is no real difference"], answer: 0, explanation: "A verdict ends the process. A review points at what to do differently." }, { question: "Why is it worth naming something that did not work?", options: ["Stopping something is as useful as starting something", "It balances out the positive finding", "It proves you are being honest", "It gives you something to improve next time"], answer: 0, explanation: "Removing a thing that reliably fails frees the effort for something that does not." }, { question: "You cannot see any pattern at all in the ten days. What is the strongest move?", options: ["Record that, and keep a rough note of conditions over the next ten", "Invent a pattern so you have something", "Assume the days were random", "Start the ten days again"], answer: 0, explanation: "No pattern yet is a reason to gather better information, not to force a conclusion." }, { question: "What makes this review worth doing at day ten rather than day fifty?", options: ["A correction is far cheaper now than after another forty days", "Ten is easier to remember", "The first ten days are the most important", "It marks the end of the island"], answer: 0, explanation: "Reviews are most valuable early, while there is still a long way to apply what you find." }] },
  ],
  [
    { title: "One Thing at a Time", why: "Attention split between three things is not three times the work; it is usually none of it.", lesson: "Switching between tasks feels productive and is not. Every switch costs you the minutes it takes to get back into the thing you left, so half an hour of switching can produce almost nothing at all. Today you practise the opposite: one task, chosen in advance, with the obvious interruptions removed, until it reaches a natural stopping point. Fifteen minutes is enough. You are training the return, not endurance.", keyIdea: "Choose one thing and stay with it until a natural stopping point.", example: "You answer messages after finishing the paragraph rather than in the middle of it, and the paragraph takes half as long.", actionPrompt: "Work on one task for fifteen unbroken minutes with your phone in another room.", actionHint: "Choose the task before you start, so you are not deciding while the clock is running.", bonus: "Extend it to twenty-five minutes and note where your attention first slipped.", quiz: [{ question: "You are working and a message arrives that could wait an hour. What is the strongest move?", options: ["Leave it until the task reaches a stopping point", "Reply now, since it will only take a moment", "Check who it is from and decide then", "Stop the task and deal with everything waiting"], answer: 0, explanation: "The reply is short; the cost is getting back into the task afterwards." }, { question: "Why is switching between tasks so expensive?", options: ["Each return costs the minutes it takes to rebuild what you were holding", "It makes you tired", "It is a sign of poor discipline", "It means you never finish anything"], answer: 0, explanation: "The cost is in the re-entry, which is why several switches can consume an entire session." }, { question: "When should you choose today's task?", options: ["Before the fifteen minutes start", "In the first minute, once you are settled", "Whenever something obvious presents itself", "Whenever you feel most motivated"], answer: 0, explanation: "Choosing while the clock runs is itself a form of switching." }, { question: "Fifteen minutes in, you remember something unrelated and important. What is the strongest move?", options: ["Write it down in one line and carry on", "Deal with it immediately so you do not forget", "Stop the session and restart later", "Try to hold it in your head until the end"], answer: 0, explanation: "Capturing it costs seconds and stops it competing for the rest of the session." }, { question: "What is the phone in another room actually for?", options: ["It removes the decision rather than testing your resistance", "It proves you can go without it", "It stops other people contacting you", "It makes the session feel more serious"], answer: 0, explanation: "A phone within reach is a decision you have to keep making. Distance makes it one decision." }, { question: "You manage eleven minutes rather than fifteen. What is the honest reading?", options: ["Eleven unbroken minutes is a real result to build from", "The session did not count", "You should try thirty tomorrow to compensate", "You are not capable of sustained focus"], answer: 0, explanation: "Unbroken time is what is being trained, and eleven minutes of it is genuine progress." }, { question: "A friend says they work better with music, messages and three tabs open. What is the accurate response?", options: ["Some background is harmless, but switching tasks is not the same as background noise", "They are wrong about how they work", "Everyone is different, so there is nothing to say", "They should try working in silence for a week"], answer: 0, explanation: "Background input and task-switching are different things, and only the second carries the re-entry cost." }, { question: "What does a natural stopping point mean here?", options: ["A point where the work is at a resumable place", "The moment you get bored", "Exactly fifteen minutes", "When the task is completely finished"], answer: 0, explanation: "Stopping somewhere resumable protects the next session as well as this one." }] },
    { title: "Your Surroundings Decide", why: "Most of what you do in a room was made easy or hard by the room before you walked in.", lesson: "Willpower gets the credit for behaviour that was largely decided by layout. If the phone is on the desk, you will check it. If the Qur'an sits on the shelf you pass every morning, you will open it more often. This is not weakness; it is how attention works. Today you change one thing in your environment so that a good action becomes easier or a bad one becomes slightly annoying. One change, in a place you actually spend time.", keyIdea: "Change the environment and the behaviour usually follows.", example: "You leave your trainers by the door. The walk you keep skipping becomes the path of least resistance.", actionPrompt: "Make one change to your surroundings that makes a good action easier or a harmful one harder.", actionHint: "Moving an object is usually enough: charge the phone in another room, leave the book open on the desk.", bonus: "Make a second change that adds friction to the habit you most want to reduce.", quiz: [{ question: "You keep scrolling in bed at night. Which change is most likely to work?", options: ["Charge the phone in another room overnight", "Promise yourself you will stop", "Set a reminder to put it down", "Use a screen-time app you can override"], answer: 0, explanation: "Removing the phone from the room removes the decision. The others leave it within reach." }, { question: "What does today's lesson say about willpower?", options: ["Arranging the environment means the situation needs less of it", "Willpower is not real", "Willpower can be trained by resisting temptation daily", "Willpower matters more than environment"], answer: 0, explanation: "The environment sets how much willpower a moment costs, which is why arranging it is worth doing first." }, { question: "Which is a stronger design for someone who wants to read more?", options: ["The book left open on the desk they sit at every evening", "A daily reminder on their phone", "A reading target written on a wall chart", "Telling friends they are going to read more"], answer: 0, explanation: "Reducing the distance between you and the action beats adding a prompt to do it." }, { question: "How many changes does today ask for?", options: ["One, in a place you actually spend time", "As many as you can think of", "Three, so that one of them works", "One in every room"], answer: 0, explanation: "One change you will notice tomorrow is worth more than a reorganisation you abandon." }, { question: "What is the point of making a bad habit slightly annoying rather than impossible?", options: ["A small amount of friction is often enough, and it survives being lived with", "Impossible restrictions are unfair to yourself", "It leaves the option open for when you need it", "Annoyance builds discipline"], answer: 0, explanation: "Friction that you can actually live with keeps working, while extreme restrictions get dismantled." }, { question: "You change your environment and the behaviour does not change at all. What now?", options: ["The change was probably not on the actual path of least resistance", "The lesson does not apply to you", "You need more willpower after all", "Change everything else in the room"], answer: 0, explanation: "When friction does not work, it is usually aimed at the wrong point in the sequence." }, { question: "A friend blames themselves for always being distracted at their desk. What is the useful thing to point out?", options: ["The desk may be doing more of the work than their character is", "They should try harder", "They should work somewhere else permanently", "Distraction is unavoidable now"], answer: 0, explanation: "Attributing to character what was arranged by layout leads to the wrong fix." }, { question: "Which of these best captures the idea?", options: ["Design the situation so the good action is the easy one", "Remove all temptation from your life", "Rely on your surroundings instead of your intentions", "Keep your space tidy at all times"], answer: 0, explanation: "The aim is to make the action you want the default in that space." }] },
    { title: "Small Habits, Repeated", why: "A habit is not a big decision; it is a small action that stopped requiring one.", lesson: "Anything done daily eventually stops needing motivation. The usual mistake is choosing a first habit too large to survive a bad day: an hour of exercise, thirty pages of reading. Choose the version that survives your worst day instead — two minutes, one page, one set. On good days you will do more, and that is fine. The purpose of the small version is that it does not break, and not breaking is what builds the habit.", keyIdea: "Set the habit at a size that survives your worst day.", example: "Read one page survives illness, travel and exam week. Read thirty pages does not, and the chain dies in the first difficult week.", actionPrompt: "Choose one habit, set it at a size you could manage on your worst day, and do it today.", actionHint: "If you are not slightly embarrassed by how small it is, it is probably still too big.", bonus: "Write down where in your existing day the habit will sit, attached to something you already do.", quiz: [{ question: "You want to start reading daily. Which version is most likely to last a year?", options: ["One page every day", "Thirty pages every day", "An hour every weekend", "As much as you can manage each day"], answer: 0, explanation: "The small version survives the bad weeks, and surviving is what turns it into a habit." }, { question: "Why does the size of a new habit matter more than its ambition?", options: ["A habit that breaks on a bad day never becomes automatic", "Small habits are easier to enjoy", "Ambition is unhelpful", "Big habits take too long to see results"], answer: 0, explanation: "Automaticity comes from repetition, and repetition requires surviving the difficult days." }, { question: "You do the minimum version and feel it was not enough. What is the accurate reading?", options: ["The minimum protects the chain; doing more is a bonus, not the requirement", "You should raise the minimum", "The day does not count properly", "You are not taking it seriously"], answer: 0, explanation: "The minimum exists precisely for the days when more is not available." }, { question: "What does attaching a habit to something you already do achieve?", options: ["It gives the habit a reliable moment instead of depending on remembering", "It makes the habit shorter", "It combines two habits into one", "It makes the habit feel less like work"], answer: 0, explanation: "An existing routine is a cue that already fires every day without your effort." }, { question: "Which is the better place to put ten minutes of Qur'an?", options: ["Straight after Fajr, every day", "Whenever you have a free moment", "Before bed, if you are not too tired", "At a different time each day depending on your schedule"], answer: 0, explanation: "A fixed attachment point removes the daily decision about when it happens." }, { question: "You miss the habit on a day when everything went wrong. What is the strongest response?", options: ["Do the smallest possible version, even now", "Skip it and start again tomorrow", "Do double tomorrow", "Accept the chain is broken"], answer: 0, explanation: "A tiny version keeps the pattern intact, which matters more than the content of that day." }, { question: "What is wrong with as much as you can manage each day as a habit definition?", options: ["It has no floor, so on a bad day it quietly becomes nothing", "It is too demanding", "It cannot be measured at all", "It varies too much between people"], answer: 0, explanation: "A habit without a defined minimum has no point at which it was actually missed." }, { question: "A friend says starting small is not serious enough. What is the accurate reply?", options: ["The small version is what is still running in six months", "They are right, and small habits do little", "Seriousness is about effort, not results", "It depends entirely on the person"], answer: 0, explanation: "The comparison is not small against large, but small against abandoned." }] },
    { title: "Where Your Time Actually Goes", why: "Almost everyone is wrong about how they spend their time, and usually in the same direction.", lesson: "Ask someone how long they spend on their phone and the guess is normally about half the real figure. The gap is not dishonesty — unrecorded time genuinely does not register. Today you record it, roughly, in blocks, not to the minute: sleep, prayer, study, travel, screens, and the stretches you cannot account for. You are not doing this to feel bad. You are getting an accurate figure, because you cannot budget with a number you invented.", keyIdea: "Record your time roughly for one day. Estimates are unreliable.", example: "You expected to spend an hour on your phone and the actual figure says three. Three is the number you now have to plan around.", actionPrompt: "Track today's hours in rough blocks and write down where the time actually went.", actionHint: "Half-hour blocks are accurate enough. Include the gaps you cannot account for.", bonus: "Compare the real figure with what you would have guessed this morning.", quiz: [{ question: "Why does the lesson ask you to record time rather than estimate it?", options: ["Unrecorded time genuinely does not register, so estimates run low", "Recording is more disciplined", "Estimates are dishonest", "Recording makes you use time better automatically"], answer: 0, explanation: "The gap between estimate and record is a memory effect, not a character one." }, { question: "Your tracking shows two hours you cannot account for. What should you write?", options: ["Two hours, unaccounted for", "Nothing, since you do not know what happened", "Two hours of rest, to be generous", "An estimate based on a typical day"], answer: 0, explanation: "The unaccounted block is often the most informative entry on the page." }, { question: "How precise does the tracking need to be?", options: ["Rough blocks of about half an hour", "To the nearest minute", "To the nearest hour", "As precise as you can manage all day"], answer: 0, explanation: "Precision that makes you abandon the exercise is worse than a rough figure you actually finish." }, { question: "The real figure is much worse than you expected. What is the useful response?", options: ["Treat it as the number you now plan around", "Decide you have wasted the year", "Track again tomorrow in case today was unusual", "Set a strict limit immediately"], answer: 0, explanation: "An accurate number is the point of the exercise. What you do with it comes after." }, { question: "Which is the strongest reason to know where your time goes?", options: ["You cannot reallocate time you did not know you had", "It makes you feel more organised", "It lets you compare yourself with other people", "It proves how busy you are"], answer: 0, explanation: "Most people find hours they did not know were available, which is the practical payoff." }, { question: "You realise while tracking that you are behaving differently because you are tracking. What does that mean?", options: ["It is a known effect; note it and record honestly anyway", "The results are worthless", "You should track secretly instead", "You should track for a week to average it out"], answer: 0, explanation: "Being observed changes behaviour a little. The record is still far better than an estimate." }, { question: "Which entry would tell you the most about a difficult evening?", options: ["The gap between finishing dinner and starting anything", "The time spent asleep", "The time spent travelling", "The time spent in prayer"], answer: 0, explanation: "Transition gaps are where most unnoticed time goes, and they are usually the easiest to reclaim." }, { question: "What should you do with the figure tomorrow?", options: ["Use it to place one important thing where the time actually exists", "Cut every activity down proportionally", "Repeat the exercise until the numbers improve", "Set a target for each category"], answer: 0, explanation: "One accurate placement is a better use of the finding than a full redesign of the day." }] },
    { title: "A Promise You Can Keep", why: "Self-trust is built by keeping small promises and destroyed by making large ones.", lesson: "Every commitment you make to yourself and break teaches you quietly that your own word does not carry much weight. Repeat it enough and you stop believing your own plans. The repair is not a bigger promise made more sincerely; it is a smaller promise, kept. Today, make one commitment small enough that failing it would be embarrassing, and keep it. The intention is what gives an action its weight in our tradition — but an intention you never act on teaches you nothing.", keyIdea: "Make one commitment small enough to keep, and then keep it.", example: "I will pray Maghrib on time today is keepable. I will never miss a prayer again is a wish, and breaking it costs you self-trust.", actionPrompt: "Make one small, specific commitment for today and complete it.", actionHint: "Specific enough to be checked: what, when, and how much.", bonus: "Make the same commitment for tomorrow, and keep it twice.", quiz: [{ question: "Which commitment is most likely to build self-trust?", options: ["Ten minutes of revision after Maghrib today", "Two hours of revision every day from now on", "Never wasting time again", "Being more disciplined this month"], answer: 0, explanation: "Only the first is small, specific and checkable today. The rest are announcements." }, { question: "What does breaking a promise to yourself actually cost?", options: ["A little of your belief that your own plans mean anything", "Nothing, since nobody else knows", "The time you would have spent", "Other people's trust in you"], answer: 0, explanation: "The cost is internal and cumulative, which is why it is easy to miss until plans stop convincing you." }, { question: "You have broken several commitments to yourself recently. What is the strongest repair?", options: ["Make a much smaller commitment and keep it", "Make a serious commitment and mean it this time", "Stop making commitments for a while", "Commit publicly so you cannot back out"], answer: 0, explanation: "Self-trust is rebuilt by evidence, and small kept promises are the cheapest evidence available." }, { question: "What makes a commitment checkable?", options: ["It states what, when, and how much", "It is written down", "Someone else knows about it", "It is important to you"], answer: 0, explanation: "Without those three, there is no moment at which it was either kept or missed." }, { question: "You keep today's commitment easily and feel it was too small. What is the accurate reading?", options: ["It worked, and you can raise it slightly tomorrow", "It did not count", "You should have committed to something harder", "Small commitments do not build anything"], answer: 0, explanation: "A kept commitment is the result. Adjusting the size afterwards is the normal next step." }, { question: "Someone commits to praying every prayer on time for a year, starting today. What is the risk?", options: ["One missed prayer feels like the whole commitment has collapsed", "It is too ambitious to attempt", "Nobody could manage it", "It puts pressure on other people"], answer: 0, explanation: "All-or-nothing commitments have no recovery path, so a single miss ends them." }, { question: "How does intention relate to today's lesson?", options: ["Intention gives an action its weight, and the action is what carries it into the world", "Intention is enough on its own", "Intention matters less than results", "Intention only counts if the action is large"], answer: 0, explanation: "The two work together: the intention gives the act meaning, and the act makes the intention real." }, { question: "What should you do if you realise at 10pm that you will not manage today's commitment?", options: ["Do the smallest honest version of it now", "Note it as missed and move on", "Do double tomorrow", "Decide it was the wrong commitment"], answer: 0, explanation: "A reduced version still keeps the promise intact, which is what the day is protecting." }] },
    { title: "When You Do Not Feel Like It", why: "Waiting until you feel like it is how most plans quietly die.", lesson: "Resistance is not a signal that the task is wrong. It usually arrives in the moment just before starting and disappears a few minutes in, which is why the reliable move is to shrink the entry rather than argue with the feeling. Open the book. Put the shoes on. Write one line. You are not negotiating with the feeling and you are not overpowering it — you are getting past the doorway, which is where it lives.", keyIdea: "Resistance is strongest at the doorway. Shrink the entry and step through it.", example: "You cannot face an hour of revision, so you commit to five minutes. Forty minutes later you are still going, which is the usual outcome.", actionPrompt: "Take one task you are resisting and start it with a two-minute version.", actionHint: "Choose the smallest possible first move: open the file, lay out the kit, write the title.", bonus: "Notice how long the resistance actually lasted once you had begun, and write the number down.", quiz: [{ question: "You do not feel like doing an important task. What is the strongest move?", options: ["Start a two-minute version of it now", "Wait until you feel more motivated", "Do something easier and come back to it", "Decide whether the task is really necessary"], answer: 0, explanation: "Resistance is usually about starting, not about the task. A tiny entry gets you past it." }, { question: "When is resistance normally at its strongest?", options: ["In the moment just before you start", "Halfway through the task", "When the task becomes difficult", "After you have finished"], answer: 0, explanation: "That is why the entry, rather than the whole task, is the part worth designing." }, { question: "What does the lesson say resistance means about a task?", options: ["Usually nothing about the task itself", "That the task is too hard for now", "That you have chosen the wrong task", "That you need more rest first"], answer: 0, explanation: "Resistance is generally about the transition into work, not a verdict on the work." }, { question: "Which of these is a well-sized entry into an hour of revision?", options: ["Open the book and read one paragraph", "Commit to a full hour and see how it goes", "Set a timer for thirty minutes", "Promise yourself a reward at the end"], answer: 0, explanation: "The entry should be small enough that refusing it would be absurd." }, { question: "You start the two-minute version and stop after exactly two minutes. What is the honest reading?", options: ["You got past the doorway, which was today's task", "The technique failed", "You were not really trying", "You should have committed to longer"], answer: 0, explanation: "Some days two minutes is all that happens, and that still keeps the pattern alive." }, { question: "A friend says they will start once they feel ready. What is the accurate reply?", options: ["The feeling usually arrives after starting, not before", "They should wait until they are ready", "They need a better reason to start", "Readiness cannot be predicted"], answer: 0, explanation: "Waiting for readiness inverts the actual order in which motivation and action occur." }, { question: "Why write down how long the resistance lasted?", options: ["The number is usually small, and knowing it makes the next start easier", "It keeps a record of your effort", "It shows how disciplined you were", "It helps you plan tomorrow's schedule"], answer: 0, explanation: "Evidence that the feeling passes quickly is what makes you willing to test it again." }, { question: "What is the difference between shrinking the entry and lowering your standards?", options: ["The entry is only the first move; the standard for the finished work is unchanged", "There is no difference", "Shrinking the entry means accepting less", "Lowering standards is more honest"], answer: 0, explanation: "You are changing how the work starts, not what counts as done." }] },
    { title: "What You Can Actually Control", why: "Effort spent on what you cannot control is effort taken from what you can.", lesson: "Blaming circumstances is comfortable because it is often partly true. The teacher was unclear, the house was loud, the day was badly arranged. None of that is a lie, and none of it changes what happens next. The useful split is simple: what here was outside my control, and what part was mine? Own your part fully and put the rest down. This is not about carrying blame for everything. It is about finding the piece you can actually move.", keyIdea: "Separate what was outside your control from your part, and act on your part.", example: "The lesson was badly explained, and you also did not ask a single question. Only the second half is available for you to fix.", actionPrompt: "Take one thing that went badly recently and write down which part was genuinely yours.", actionHint: "Write two short lists: outside my control, and mine. Then act only on the second.", bonus: "Do one concrete thing today about the part that was yours.", quiz: [{ question: "You did badly in a test after a week of disruption at home. What is the most useful response?", options: ["Accept the disruption was real and identify the part that was still yours", "Conclude the result was entirely out of your hands", "Take full blame for everything that happened", "Decide tests are not a fair measure"], answer: 0, explanation: "Both things are true at once. Only your part comes with a next step attached." }, { question: "What is the risk of a purely external explanation?", options: ["It is often accurate and still leaves you with nothing to do", "It is dishonest", "It makes other people defensive", "It stops you from resting"], answer: 0, explanation: "An explanation that removes all your agency also removes every available improvement." }, { question: "What is the risk of taking full blame for everything?", options: ["You spend effort on things you could never have changed", "It makes you look weak", "It is a form of pride", "It is unfair to other people"], answer: 0, explanation: "Over-owning is as impractical as under-owning, because it misdirects the effort." }, { question: "Which of these belongs on the list of things you controlled?", options: ["Whether you asked a question when you did not understand", "How clearly the teacher explained it", "How noisy the house was", "How difficult the paper turned out to be"], answer: 0, explanation: "Your own actions in the situation are the part available to change next time." }, { question: "A friend explains a bad result entirely by other people's decisions. What is the useful question?", options: ["What part of it was yours, even if it was small", "Why do you always blame other people", "Was any of that really true", "What will you do about those people"], answer: 0, explanation: "A specific question about their part is more useful than a challenge to their account." }, { question: "You identify your part and it is genuinely small. What now?", options: ["Act on it anyway, because it is the piece that is available", "Conclude the exercise did not apply", "Look harder until you find a larger fault", "Focus on the external factors instead"], answer: 0, explanation: "A small controllable piece is worth more than a large uncontrollable one." }, { question: "How does this differ from making excuses?", options: ["An excuse ends the conversation; this identifies a next action", "It is more polite", "It admits fault rather than avoiding it", "There is no real difference"], answer: 0, explanation: "The test is whether the account produces something to do." }, { question: "What should you do with the list of things outside your control?", options: ["Put it down and stop spending effort on it", "Keep working on it in the background", "Show it to the people responsible", "Use it to explain the result to others"], answer: 0, explanation: "The whole purpose of naming them is to release the effort they were consuming." }] },
    { title: "After the Mistake", why: "The response to a mistake matters more than the mistake.", lesson: "There are three common responses to getting something wrong: hide it, spiral about it, or fix it. The first two feel cost-free and both make the next mistake more likely, because neither produces information. The useful response has three short parts — say what happened plainly, repair what can be repaired, and change the one thing that caused it. Then it is finished. Carrying it further is not humility. It is just weight.", keyIdea: "Name it, repair it, change one thing. Then let it be finished.", example: "You forgot to pass on a message. You say so immediately, pass it on late, and start writing things down. Three steps, ten minutes, over.", actionPrompt: "Take one recent mistake and complete all three steps: name it, repair what you can, change one thing.", actionHint: "The repair can be small. The change should be a system, not a promise to try harder.", bonus: "Tell the person affected, plainly, without a long explanation attached.", quiz: [{ question: "You forget to do something you promised a friend. What is the strongest sequence?", options: ["Tell them, do it late, and change what caused you to forget", "Do it quietly and hope they did not notice", "Apologise at length and explain why it happened", "Promise to be more careful in future"], answer: 0, explanation: "Naming, repairing and changing is the full response. Two out of three leaves it unfinished." }, { question: "Why does hiding a mistake make the next one more likely?", options: ["Nothing about the cause gets changed", "It makes you feel guilty", "People find out eventually", "It becomes a habit"], answer: 0, explanation: "Concealment leaves the mechanism that produced the mistake completely intact." }, { question: "What is wrong with spending a long time feeling bad about it?", options: ["It produces no information and delays the repair", "It shows you care too much", "Other people find it uncomfortable", "It is a form of self-indulgence"], answer: 0, explanation: "Extended discomfort is not a substitute for the three steps, and it postpones them." }, { question: "Which counts as changing one thing?", options: ["Starting to write commitments down as you make them", "Deciding to be more careful", "Apologising more sincerely", "Reminding yourself how bad it felt"], answer: 0, explanation: "A system persists without your attention. A resolution does not." }, { question: "How long should the whole response take?", options: ["Short, and then it is finished", "As long as it takes to feel you have made up for it", "Until the other person has forgiven you", "Until you are sure it cannot happen again"], answer: 0, explanation: "The three steps are quick by design. Extending them adds weight rather than rigour." }, { question: "The mistake cannot be repaired at all. What do the remaining steps look like?", options: ["Name it plainly and change the thing that caused it", "There is nothing useful left to do", "Apologise repeatedly instead", "Carry it as a reminder"], answer: 0, explanation: "When repair is unavailable, naming and changing still complete the response." }, { question: "A long explanation attached to an apology usually does what?", options: ["Shifts the focus onto your reasons rather than their situation", "Helps the other person understand", "Makes the apology more sincere", "Prevents a repeat of the mistake"], answer: 0, explanation: "Explanation has its place, but attached to an apology it usually reads as defence." }, { question: "Which of these is the clearest sign the response worked?", options: ["Something about how you operate is now different", "You feel better about it", "The other person said it was fine", "You have promised it will not recur"], answer: 0, explanation: "A changed system is the only part of the response that affects the future." }] },
    { title: "Show Up Again", why: "Consistency is what turns effort into results; intensity on its own rarely does.", lesson: "One heroic session is worth less than the same total spread across a week, because the second builds a habit and the first builds a memory. Consistency also has a specific enemy: the missed day that becomes two. The rule that protects it is simple — never miss twice. One missed day is an accident. Two is the beginning of a new pattern, and the second day is the one that actually matters.", keyIdea: "Never miss twice. The second missed day is the one that changes the pattern.", example: "You skip your reading on Tuesday because you were out late. On Wednesday you read one page, and the chain holds.", actionPrompt: "Do the same small habit today that you did yesterday, and write down the rule: never miss twice.", actionHint: "If you missed yesterday, do the smallest possible version today rather than the full one.", bonus: "Write down what your minimum version will be for the next time life gets in the way.", quiz: [{ question: "You missed your habit yesterday for the first time in three weeks. What is the strongest move today?", options: ["Do the smallest version of it today", "Do double today to make up for it", "Restart the count from zero next week", "Accept that the streak is over"], answer: 0, explanation: "Today is the day that decides whether one miss becomes a pattern. Size matters less than presence." }, { question: "Why is the second missed day more significant than the first?", options: ["One miss is an accident; two starts a new pattern", "It doubles the lost effort", "It is harder to recover from physically", "It shows a lack of commitment"], answer: 0, explanation: "The pattern, not the total, is what consistency is protecting." }, { question: "Which produces more over three months?", options: ["Twenty minutes most days", "Four hours once a fortnight", "Two intense weeks followed by a break", "As much as you feel like doing each day"], answer: 0, explanation: "Regularity compounds and builds automaticity. Intensity in bursts does neither." }, { question: "You are ill and cannot do your normal session. What does never miss twice suggest?", options: ["Do a token version, or accept one miss and return tomorrow", "Push through regardless of illness", "Skip the rest of the week and restart", "Do double when you recover"], answer: 0, explanation: "The rule protects the return, and it never asks you to work through genuine illness." }, { question: "What is the purpose of deciding your minimum version in advance?", options: ["On a bad day you follow a decision instead of making one", "It sets a lower standard", "It makes the habit easier overall", "It gives you permission to do less"], answer: 0, explanation: "Decisions made in advance are far more reliable than ones made while everything is going wrong." }, { question: "You have kept a habit for forty days and miss one. What is the accurate reading?", options: ["Forty days of evidence still stands", "The streak is worthless now", "You have to start counting again from one", "You were never really consistent"], answer: 0, explanation: "The value was in the forty days of practice, and a single gap does not remove them." }, { question: "A friend only trains when they feel motivated. What is the useful thing to point out?", options: ["The days they do not feel like it are where the difference is made", "Motivation is unreliable for everyone", "They should find a training partner", "They should set harder goals"], answer: 0, explanation: "The uninspired days are the ones consistency exists to cover." }, { question: "Which best captures today's lesson?", options: ["Return quickly, and never let one gap become two", "Never miss a day under any circumstances", "Intensity matters more than frequency", "Streaks are the point of the course"], answer: 0, explanation: "The rule is about returning, not about a perfect record." }] },
    { title: "Do It Anyway", why: "Discipline is doing the important thing at the time you said, especially when you would rather not.", lesson: "Motivation is a feeling, and feelings do not run to a schedule. Discipline is what lets an important task happen on a normal, uninspired Tuesday. It is not harshness with yourself and it is not endurance for its own sake — it is care, applied to things you have already said matter. Today: one task that genuinely matters, done at a time you decide in advance, whether or not you feel like it when the time arrives.", keyIdea: "Decide the time in advance, and let the time decide, not the mood.", example: "You set 7pm for revision. At 7pm you do not want to. You start anyway, and by ten past the question of wanting to has stopped being relevant.", actionPrompt: "Choose one important task, name the exact time you will do it, and do it at that time.", actionHint: "Set the time before the day gets going, and tell someone if that helps you hold to it.", bonus: "Do the same task at the same time tomorrow.", quiz: [{ question: "You set 7pm for an important task. At 7pm you do not feel like it. What is the strongest move?", options: ["Start it anyway, at the smallest scale if necessary", "Move it to later when you feel better", "Do a different, easier task instead", "Decide whether the task is genuinely important"], answer: 0, explanation: "The point of setting the time in advance is that the decision was already made by a clearer version of you." }, { question: "Why decide the time before the day begins?", options: ["A decision made in advance does not have to survive your mood later", "It makes the day look organised", "It leaves less time to change your mind", "It commits you publicly"], answer: 0, explanation: "You are moving the decision to a moment when you can think clearly about it." }, { question: "What does the lesson say discipline actually is?", options: ["Care applied to things you have already said matter", "Being hard on yourself", "Working until you are exhausted", "Ignoring how you feel"], answer: 0, explanation: "Discipline in this course protects what you value; it is not severity for its own sake." }, { question: "You keep moving the same task later all day and it never happens. What is the underlying problem?", options: ["The time was never fixed, so the mood decided every time", "The task is too difficult", "You lack willpower", "The day was too busy"], answer: 0, explanation: "A floating task is decided repeatedly, and each decision is made in whatever state you happen to be in." }, { question: "Which is the stronger commitment?", options: ["Revision at 7pm today", "Revision this evening", "Revision at some point today", "As much revision as I can fit in"], answer: 0, explanation: "Only the first names a moment at which it either happened or did not." }, { question: "At 7pm something genuinely urgent comes up. What is the strongest response?", options: ["Handle it, then name a new specific time today", "Cancel the task for the day", "Do it tomorrow at the same time", "Ignore the urgent thing"], answer: 0, explanation: "Rescheduling to another specific time keeps the commitment. Leaving it unscheduled ends it." }, { question: "You start at 7pm and it goes badly. Does the day count?", options: ["Yes, because the commitment was about starting at the named time", "No, because the work was poor", "Only if you finish the task", "Only if you worked for long enough"], answer: 0, explanation: "Today is training the link between a named time and an actual start." }, { question: "How does this differ from waiting for motivation?", options: ["The time triggers the action instead of the feeling doing it", "It requires more effort", "It works only for people who are naturally disciplined", "It removes the need to care about the task"], answer: 0, explanation: "You are changing what starts the action, not how much you care about it." }] },
  ],
  [
    { title: "Remove the Distraction", why: "Resisting a distraction all day is far harder than removing it once.", lesson: "Every time you resist something it costs you a little. Do that forty times in an afternoon and there is nothing left for the work. The cheaper move is to take the distraction out of the situation entirely: the phone in another room, notifications off, the tab closed, the door shut. This is not weakness. Making a temptation inconvenient is the strategy that people who look effortlessly disciplined are usually running.", keyIdea: "Remove the distraction once instead of resisting it forty times.", example: "You put your phone in a drawer in another room for an hour. You do not resist it once, because it is not there to resist.", actionPrompt: "Identify your single biggest distraction, remove it completely, and complete something important without it.", actionHint: "Removal rather than restraint: another room, logged out, notifications off, the app gone for the evening.", bonus: "Do it for a second session and note the difference in how much you finished.", quiz: [{ question: "You have three hours of important work and your phone keeps pulling you away. What is the strongest move?", options: ["Put it in another room for the session", "Turn it face-down and resist checking it", "Check it every thirty minutes as a compromise", "Use willpower and see how long you last"], answer: 0, explanation: "Removing it is one decision. Resisting it is a decision you have to keep making all afternoon." }, { question: "Why is repeated resistance expensive?", options: ["Each act of resistance uses capacity the work needed", "It is emotionally upsetting", "It makes you resent the work", "It takes physical time"], answer: 0, explanation: "Resistance draws on the same limited capacity as the task itself." }, { question: "Which is genuine removal rather than restraint?", options: ["Logging out and leaving the device in another room", "Keeping the app open but promising not to look", "Setting a timer that you can dismiss", "Putting the phone on silent beside you"], answer: 0, explanation: "Removal means the option is not available in the moment, not merely discouraged." }, { question: "A friend says removing distractions is a sign of weak willpower. What is the accurate reply?", options: ["People who look disciplined are usually just arranging fewer temptations", "They are right, but it still works", "Willpower cannot be trained anyway", "Everyone has weak willpower"], answer: 0, explanation: "Consistent performers tend to design situations rather than out-fight them." }, { question: "You remove the phone and find yourself distracted by something else entirely. What now?", options: ["Identify the new one and remove that too", "Conclude removal does not work", "Bring the phone back, since it made no difference", "Accept that focus is impossible for you"], answer: 0, explanation: "Distraction relocating is normal; each removal narrows the field." }, { question: "What is the strongest reason to remove one distraction completely rather than several partially?", options: ["A partially removed distraction still requires a decision every time", "One is easier to remember", "Several removals are too disruptive", "The biggest one is the only one that matters"], answer: 0, explanation: "Half-measures preserve exactly the thing that was costing you: the repeated decision." }, { question: "You cannot remove the distraction because you need the device for the work. What is the strongest move?", options: ["Remove the specific sources: log out, block, close, notifications off", "Give up and work with it", "Work somewhere else entirely", "Do the work on paper instead"], answer: 0, explanation: "When the device is required, the removal moves down a level to the specific applications and alerts." }, { question: "What should you compare at the end of a removed-distraction session?", options: ["How much you finished against a normal session", "How long you lasted", "How often you thought about the distraction", "How difficult it felt"], answer: 0, explanation: "Output is the measure that tells you whether the arrangement is worth repeating." }] },
    { title: "One Task, Properly", why: "Work of any depth needs an unbroken stretch, and unbroken stretches have to be arranged.", lesson: "Some tasks only start producing after fifteen or twenty minutes, once you finally have the whole problem in your head at the same time. Switch away and that state empties, and it has to be rebuilt from nothing. Deep work is simply protecting a block long enough to reach that point: forty-five minutes, one task, everything else waiting. It will feel harder than a scattered hour, and it will produce more than three of them.", keyIdea: "Protect one unbroken block long enough to get the whole problem into your head.", example: "Forty-five minutes on one essay with the phone away produces more than two hours of writing done between message replies.", actionPrompt: "Do one meaningful task for forty-five minutes without switching to anything else.", actionHint: "Decide in advance what you will do if you get stuck, so being stuck does not become a reason to switch.", bonus: "Write down where in the block your focus was strongest, and schedule tomorrow's block there.", quiz: [{ question: "Twenty minutes into a hard problem it starts to make sense, and a message arrives. What is the strongest move?", options: ["Ignore it and stay with the problem", "Reply quickly and return", "Take it as a natural break point", "Note the message and check it in five minutes"], answer: 0, explanation: "You have just reached the state the block exists to produce. Leaving it empties it." }, { question: "Why does switching away cost more than the time it takes?", options: ["The mental state you built has to be rebuilt from nothing", "It breaks your rhythm", "It makes you feel guilty", "It signals to others that you are available"], answer: 0, explanation: "The rebuild is the hidden cost, and it is much longer than the interruption itself." }, { question: "You get stuck fifteen minutes into the block. What is the strongest response?", options: ["Use the approach you decided in advance and stay in the block", "Switch to another task and come back", "End the session early", "Look for help online straight away"], answer: 0, explanation: "Being stuck is a normal part of depth. Deciding beforehand stops it becoming an exit." }, { question: "Which produces more on a difficult task?", options: ["Forty-five uninterrupted minutes", "Two hours interrupted every few minutes", "Three fifteen-minute sessions across the day", "An hour with music, messages and email open"], answer: 0, explanation: "Only the first reliably reaches the state where hard problems become tractable." }, { question: "What should you decide before the block starts?", options: ["The task, and what you will do if you get stuck", "How long you will work for only", "What your reward will be at the end", "Which distractions you will allow"], answer: 0, explanation: "Both decisions remove the two most common reasons a block collapses." }, { question: "You finish the block and feel more tired than after a scattered hour. What does that suggest?", options: ["You were doing the harder kind of work", "You are not suited to long sessions", "The task was too difficult", "You need shorter blocks"], answer: 0, explanation: "Sustained attention is genuinely more demanding, which is also why it produces more." }, { question: "Where should tomorrow's block go?", options: ["At the time your focus was strongest today", "At the same time regardless of how it went", "Whenever you have a gap", "Later, so you are more warmed up"], answer: 0, explanation: "Placing demanding work where your attention actually is costs nothing and returns a lot." }, { question: "A colleague says they can work well with constant interruptions. What is the accurate response?", options: ["Shallow tasks tolerate interruption; work with depth does not", "They are probably right", "Nobody can work with interruptions", "It depends on how disciplined they are"], answer: 0, explanation: "The distinction is about the kind of work, not the person's discipline." }] },
    { title: "Wait for the Better Thing", why: "Most useful outcomes sit on the other side of something you did not want to do first.", lesson: "The choice is rarely between good and bad. It is between something small and immediate and something larger and later, and the immediate one always argues more convincingly because it is here now. Delaying is a skill, and two things make it easier: keeping the delay short and specific, and knowing exactly what you are waiting for. Not now, after Maghrib is workable. Never again is not.", keyIdea: "Trade a small immediate thing for a specific larger one, at a specific time.", example: "You want to watch something now. You finish the work first and watch it after Isha. You still get it — the order changed, not the outcome.", actionPrompt: "Today, choose the useful action over an immediately tempting one, and write down both.", actionHint: "Give the tempting thing a time later in the day rather than banning it.", bonus: "Do it a second time today with something harder to delay.", quiz: [{ question: "You want to watch something now and have work due tomorrow. What is the strongest move?", options: ["Finish the work and watch it afterwards, at a named time", "Watch it now and work later", "Give it up entirely for the week", "Do half of each"], answer: 0, explanation: "The order changes, not the outcome, and naming the later time is what makes the delay hold." }, { question: "Why does not now, after Maghrib work better than never again?", options: ["A specific short delay is something you can actually keep", "It is a smaller sacrifice", "It sounds more reasonable", "It leaves room to change your mind"], answer: 0, explanation: "Indefinite bans have no endpoint, so they get abandoned rather than kept." }, { question: "Why is the immediate option always more persuasive?", options: ["It is present, and the alternative is only imagined", "It is usually more enjoyable", "People are naturally impatient", "It requires no effort"], answer: 0, explanation: "Presence, not quality, is what gives the immediate option its advantage." }, { question: "You delay something and then give in an hour later. What is the useful reading?", options: ["The delay was too vague or too long; make the next one shorter and specific", "You have no self-control", "Delaying does not work for you", "You should have banned it outright"], answer: 0, explanation: "A failed delay is usually a design problem, and the fix is a shorter, more specific one." }, { question: "Which of these is a well-formed trade?", options: ["Revision until 8pm, then the match", "Revision until I feel finished, then maybe the match", "No entertainment at all this week", "The match now and revision if there is time"], answer: 0, explanation: "The first has a defined end for the work and a defined start for the reward." }, { question: "A friend says delaying enjoyment makes life miserable. What is the accurate reply?", options: ["The point is the order, not the removal", "They should enjoy things now while they can", "They are right, and this only works for some people", "Enjoyment is not important during study"], answer: 0, explanation: "Nothing is being removed. What changes is which one happens first." }, { question: "What makes a delay easier to hold?", options: ["Knowing exactly what you are waiting for and when it arrives", "Being strict with yourself", "Not thinking about it at all", "Making the wait as long as possible"], answer: 0, explanation: "Specificity about the reward and the time removes most of the negotiation." }, { question: "You delay something and the later time arrives. What should happen?", options: ["Take it, as agreed", "Delay it again to build discipline", "Skip it, since you managed without", "Reduce it to half"], answer: 0, explanation: "Keeping the second half of the trade is what makes the next delay believable." }] },
    { title: "The Task You Have Been Avoiding", why: "The task you are avoiding is usually the one with the most attached to it.", lesson: "Avoidance is rarely about the work itself. It is about a conversation you do not want to have, an outcome you do not want to find out, or a job whose first step has never actually been defined. The last of these is the most common and the easiest to fix: an undefined task cannot be started, so it gets postponed indefinitely and feels like laziness. Define the first concrete step, small enough to do today, and take it. The rest usually follows.", keyIdea: "An avoided task is usually an undefined one. Name the first concrete step and take it.", example: "Sort out my results is unstartable. Email the tutor to ask about the deadline takes four minutes and unblocks the whole thing.", actionPrompt: "Take the thing you have avoided longest, write down its first concrete step, and complete that step today.", actionHint: "If the first step still feels too big, it is not the first step. Break it down again.", bonus: "Write down the step after that one, and give it a date.", quiz: [{ question: "You have avoided a task for two weeks. What is the strongest first move?", options: ["Define the smallest concrete first step and do it today", "Block out a whole afternoon for it", "Work out why you have been avoiding it", "Wait until the deadline forces you"], answer: 0, explanation: "The definition is usually the missing piece, and a defined small step is immediately doable." }, { question: "Why do undefined tasks get postponed indefinitely?", options: ["There is nothing specific to start, so starting never happens", "They are usually unimportant", "People are naturally lazy", "They have no deadline"], answer: 0, explanation: "You cannot begin an instruction that does not name an action." }, { question: "Which is a properly concrete first step?", options: ["Email the tutor to ask about the deadline", "Sort out my results", "Get on top of my coursework", "Deal with the university situation"], answer: 0, explanation: "Only the first names an action you could start in the next five minutes." }, { question: "Your first step still feels too big to start. What does that tell you?", options: ["It is not the first step; break it down further", "You need more motivation", "The task is beyond you", "You should ask someone else to do it"], answer: 0, explanation: "Resistance to a step is usually a sign that it is still several steps." }, { question: "You realise you are avoiding a task because of a conversation attached to it. What now?", options: ["Make the conversation itself the defined first step", "Do the rest of the task and leave that part", "Wait until the conversation becomes unavoidable", "Ask someone else to have it for you"], answer: 0, explanation: "When the conversation is the blockage, it is the task, and defining it as such unblocks the rest." }, { question: "You complete the first step and the task still feels large. What is the strongest response?", options: ["Define the next step and date it", "Push on until it is finished today", "Return it to the list and revisit next week", "Reassess whether the task is necessary"], answer: 0, explanation: "A dated next step keeps the momentum without requiring the whole task in one sitting." }, { question: "A friend says they will start when they have a clear day for it. What is the accurate reply?", options: ["A clear day rarely arrives, and the first step usually needs minutes not hours", "That is sensible for a large task", "They should force themselves to start now", "They should reduce the size of the task instead"], answer: 0, explanation: "Waiting for a clear stretch is one of the most common ways a task stays undone for months." }, { question: "What is the difference between avoidance and prioritisation?", options: ["A prioritised task has a named later time; an avoided one does not", "Prioritising feels better", "Avoidance is always about fear", "There is no meaningful difference"], answer: 0, explanation: "The presence of a specific time is what separates a deliberate delay from avoidance." }] },
    { title: "Pause Before You React", why: "Almost everything you regret saying was said in the first ten seconds.", lesson: "Anger, embarrassment and irritation arrive faster than judgement does. The gap between them is a few seconds long, and the entire skill is putting something into that gap: a breath, an unsent message, a walk to another room. This is not suppression — the feeling is allowed, and it is often justified. What you are protecting is the response, because the response is the part other people remember and the part you have to live with.", keyIdea: "Put a few seconds between the feeling and the response.", example: "You get a message that annoys you. You write the reply, do not send it, and read it again after Maghrib. You send a much shorter one.", actionPrompt: "The next time you are annoyed today, pause before responding, and write down what you did with the pause.", actionHint: "Physically leave, or draft the reply without sending it. Both work better than trying to feel calm.", bonus: "Go back to something you reacted to badly last week and repair it.", quiz: [{ question: "A message annoys you and you have already written an angry reply. What is the strongest move?", options: ["Do not send it, and read it again in an hour", "Send it, since it is honest", "Delete it and say nothing ever", "Soften a few words and send it now"], answer: 0, explanation: "The delay costs an hour and reliably changes what you would have sent." }, { question: "What is the pause actually protecting?", options: ["The response, which is the part that lasts", "Your feelings", "The other person's feelings", "Your reputation"], answer: 0, explanation: "The feeling passes. The response is what remains in the relationship and in your memory." }, { question: "Is the lesson asking you to suppress the feeling?", options: ["No, only to delay the response", "Yes, anger should be avoided", "Yes, feelings should not affect your behaviour", "Only when the feeling is unjustified"], answer: 0, explanation: "The feeling is allowed and often justified. It is the immediate response that needs the gap." }, { question: "Which is the more reliable pause?", options: ["Physically leaving the room", "Telling yourself to calm down", "Counting to ten while re-reading the message", "Explaining to yourself why they are wrong"], answer: 0, explanation: "Changing your physical situation works better than trying to argue yourself out of the feeling." }, { question: "You pause and afterwards still think the response was warranted. What now?", options: ["Say it, in the shorter and clearer form the pause produced", "Say nothing at all", "Say it exactly as you first intended", "Wait another day"], answer: 0, explanation: "The pause is not there to prevent you responding. It is there to improve what you say." }, { question: "Someone embarrasses you in front of others. What does today suggest?", options: ["Respond after the few seconds, not inside them", "Respond immediately so you are not seen as weak", "Ignore it entirely and never mention it", "Match what they did"], answer: 0, explanation: "The first few seconds are where the responses you regret are made, in public more than anywhere." }, { question: "What makes drafting an unsent reply effective?", options: ["You get the discharge of writing it without the cost of sending it", "It wastes time until you calm down", "It helps you organise your argument", "It reminds you what you wanted to say"], answer: 0, explanation: "The writing satisfies the urge; the not-sending protects the relationship." }, { question: "You reacted badly last week and it is still sitting between you and someone. What is the strongest move?", options: ["Go back and repair it plainly", "Leave it, since time will smooth it over", "Wait for them to raise it", "Explain in detail why you reacted that way"], answer: 0, explanation: "A plain repair works long after the moment, and waiting rarely improves it." }] },
    { title: "Past the Uncomfortable Part", why: "Most real tasks have a stretch in the middle where stopping feels reasonable, and it usually is not.", lesson: "There is a point in almost any genuine effort where it stops being interesting and starts being work: boredom, difficulty, the sense that this is taking longer than it should. That is not a signal to stop. It is the ordinary middle, and getting through it is most of what separates people who finish from people who start a great many things. Today, pick something with a middle and go through it rather than around it. This is about sustained effort, not harm — stop for genuine pain, illness or safety.", keyIdea: "The uncomfortable middle is a normal stage, not a verdict on the task.", example: "Thirty minutes into revision the material gets hard and you want to switch subjects. You stay with the hard part, and that is the part that actually gets learned.", actionPrompt: "Complete one task that requires sustained effort, and keep going through the point where you wanted to stop.", actionHint: "Decide the finishing line before you start, so enough is not decided by how you feel at minute thirty.", bonus: "Write down what you told yourself at the moment you wanted to stop.", quiz: [{ question: "Thirty minutes into a hard task it stops being interesting. What does that most likely mean?", options: ["You have reached the ordinary middle", "The task was the wrong choice", "You need a break", "You have done enough for today"], answer: 0, explanation: "The middle arrives in almost every real task, and it is not a signal about the task's value." }, { question: "Why decide the finishing line before starting?", options: ["Otherwise enough gets decided by how you feel at the hardest point", "It makes the task shorter", "It helps you plan the rest of the day", "It stops you overworking"], answer: 0, explanation: "The definition of done should not be set by the version of you that most wants to stop." }, { question: "Which is the correct reason to stop today?", options: ["Genuine pain, illness or safety", "Boredom", "The task taking longer than expected", "Losing interest"], answer: 0, explanation: "The lesson is about sustained effort, and it draws a firm line at harm." }, { question: "You get through the uncomfortable stretch and the work improves. What is the useful thing to notice?", options: ["The difficulty was a stage, not a ceiling", "You should always push through everything", "The task was easier than you thought", "You had more energy than you realised"], answer: 0, explanation: "Experiencing the stage passing is what makes you willing to stay next time." }, { question: "What usually happens when you switch tasks at the uncomfortable point?", options: ["You get the relief and arrive at the same point in the new task later", "You make better use of your time", "You come back to it refreshed", "You lose nothing, since the work is the same"], answer: 0, explanation: "Switching at the middle tends to produce a collection of tasks all abandoned at the same stage." }, { question: "A friend never finishes anything they start. What is most likely happening?", options: ["They stop at the uncomfortable middle each time", "They choose the wrong things", "They are not interested enough", "They take on too much at once"], answer: 0, explanation: "The pattern of many starts and few finishes usually has a single consistent stopping point." }, { question: "Why write down what you told yourself at the moment you wanted to stop?", options: ["The same sentence tends to appear every time, and naming it weakens it", "It records your effort", "It helps you avoid that task next time", "It proves you got through it"], answer: 0, explanation: "The stopping thought is usually a repeated line, and recognising it is most of the defence." }, { question: "What is the difference between this and simply working longer?", options: ["It is about crossing a specific stage, not about total hours", "There is no difference", "Working longer is more effective", "This is only about difficult tasks"], answer: 0, explanation: "The lesson targets a particular moment, not an increase in volume." }] },
    { title: "See It and Fix It", why: "Waiting to be told is comfortable, and it is also how problems quietly become someone's opinion of you.", lesson: "Most problems are visible to several people and owned by none. Someone notices the thing that keeps going wrong, thinks somebody should sort that out, and moves on. Initiative is being the one who does not move on. It carries a real risk — you might get it wrong, or do work nobody asked for — and it is still worth it, because solving what you see is one of the few habits that reliably changes how people treat you.", keyIdea: "Notice a problem and solve it without waiting to be asked.", example: "The shared drive is a mess and everyone complains about it. You spend twenty minutes organising it and say nothing.", actionPrompt: "Find one problem nobody has assigned to you, and solve it today.", actionHint: "Small and real beats large and hypothetical. Check first whether fixing it affects other people.", bonus: "Solve a second one that nobody will ever notice has been solved.", quiz: [{ question: "You notice a recurring problem that is not your responsibility. What is the strongest move?", options: ["Fix it, checking first whether the fix affects others", "Mention it to whoever is responsible", "Wait to see if anyone else deals with it", "Note it in case it is raised later"], answer: 0, explanation: "Fixing it is the practice. The check exists so the fix does not create a new problem." }, { question: "Why do visible problems often go unsolved?", options: ["They are owned by nobody in particular", "They are too difficult", "Nobody notices them", "Fixing them is not rewarded"], answer: 0, explanation: "Diffused ownership, not difficulty or invisibility, is the usual reason." }, { question: "What is the genuine risk of taking initiative?", options: ["You might get it wrong or do work nobody wanted", "People will resent you", "You will be given more work", "You will look like you are showing off"], answer: 0, explanation: "The lesson names the risk honestly and still recommends the habit." }, { question: "Why check before fixing something that affects other people?", options: ["A fix that surprises people can cost more than the problem did", "To get permission", "To share the credit", "To avoid doing the work yourself"], answer: 0, explanation: "Checking is not asking permission; it is making sure the fix is actually an improvement." }, { question: "Which of these is initiative rather than complaint?", options: ["Spending twenty minutes organising the shared drive", "Pointing out how disorganised the drive is", "Suggesting someone should organise the drive", "Asking who is responsible for the drive"], answer: 0, explanation: "Only the first changes the situation." }, { question: "Nobody notices what you fixed. What does that mean?", options: ["Nothing about its value; the habit is the point", "The problem was not worth fixing", "You should have told someone", "You chose something too small"], answer: 0, explanation: "Most solved problems are invisible precisely because they are no longer happening." }, { question: "You fix something and someone is annoyed that you did. What is the useful response?", options: ["Find out what you disrupted, and check with them next time", "Stop taking initiative", "Explain that you were only helping", "Point out that nobody else was doing it"], answer: 0, explanation: "Their annoyance is information about a constraint you could not see." }, { question: "How does initiative connect to responsibility?", options: ["Both are about acting before you are required to", "Initiative is optional and responsibility is not", "They are unrelated", "Initiative is about work and responsibility is about people"], answer: 0, explanation: "Both replace being told with noticing, which is why they tend to develop together." }] },
    { title: "Own It Completely", why: "Real responsibility means the outcome is yours, including the parts that were not your fault.", lesson: "There is a difference between doing your bit and owning an outcome. Doing your bit ends when your task is finished, whether or not the thing actually worked. Owning it means following through until it is done: you chase the missing piece, you notice the gap nobody covered, and you do not use that was not my job as an ending. Take one meaningful responsibility today and own it that way, the whole way through.", keyIdea: "Own the outcome, not just your task. Follow through to the end.", example: "You were asked to book the room. Nobody told the group the time changed, so you tell them — because your job was the meeting happening, not the booking.", actionPrompt: "Take full ownership of one meaningful responsibility today and carry it through to a finished outcome.", actionHint: "Ask what actually done looks like from the other side, and work to that.", bonus: "Tell the person depending on it that it is done, without being asked.", quiz: [{ question: "You booked the room as asked, and nobody told the group the time changed. What does ownership require?", options: ["Tell the group, because the outcome was the meeting happening", "Nothing, since you did your task", "Tell whoever was supposed to inform them", "Wait and see whether people turn up"], answer: 0, explanation: "Owning the outcome means covering the gap even when the gap was not yours to begin with." }, { question: "What is the difference between doing your bit and owning an outcome?", options: ["Doing your bit ends with your task; ownership ends with the result", "Ownership means more work", "Doing your bit is for junior people", "There is no practical difference"], answer: 0, explanation: "The two end at different points, and only one of them guarantees the thing worked." }, { question: "Someone else drops their part and the whole thing is at risk. You have finished yours. What now?", options: ["Cover what you can and flag the rest early", "Leave it, since your part is done", "Do their entire job for them without saying anything", "Wait for someone to notice"], answer: 0, explanation: "Covering plus flagging protects the outcome without silently absorbing someone else's role." }, { question: "What is the strongest way to check whether something is actually finished?", options: ["Ask what done looks like from the other person's side", "Check your own task list", "Ask whether anyone has complained", "See whether the deadline has passed"], answer: 0, explanation: "The person depending on it defines completion far more accurately than your own checklist." }, { question: "Why is that was not my job a weak ending?", options: ["It may be true and it still leaves the outcome broken", "It sounds defensive", "It annoys other people", "It is usually inaccurate"], answer: 0, explanation: "Accuracy is not the issue. The problem is that the sentence produces nothing." }, { question: "You take full ownership and it still fails for reasons outside your control. What is the honest response?", options: ["Report it plainly, with what you did and what was outside your reach", "Take the blame for all of it", "Explain that it was never really your responsibility", "Avoid mentioning it"], answer: 0, explanation: "Ownership includes an accurate account of what happened, not accepting blame for everything." }, { question: "What does telling someone it is done, unasked, actually achieve?", options: ["It removes the need for them to chase, which is part of the outcome", "It makes you look good", "It creates a record", "It reminds them you did the work"], answer: 0, explanation: "The chasing is a cost you can remove, and removing it is part of owning the result." }, { question: "How does this build on taking responsibility for your own part?", options: ["It extends the same habit from your actions to the whole result", "It replaces it", "It is a different skill entirely", "It applies only to group work"], answer: 0, explanation: "It is the same principle scaled up from your part to the outcome it belongs to." }] },
    { title: "The Five-Day Commitment", why: "Anything you can only do once is a mood; anything you can hold for five days is a beginning.", lesson: "A single hard day proves very little. Five consecutive days of something modest proves considerably more, because it has to survive a bad night's sleep, an unexpected afternoon and a day when you simply do not care. Choose the commitment now and choose it carefully: small enough to survive all five days, real enough that keeping it costs you something. Write it down, along with the minimum version you will do on the worst day.", keyIdea: "Choose one commitment you can hold for five consecutive days, including the bad ones.", example: "Twenty minutes of Qur'an after Fajr for five days, with a minimum of five minutes on a day that falls apart.", actionPrompt: "Choose a five-day commitment, write down its minimum version, and complete day one today.", actionHint: "If you would be confident of doing it on your worst day this month, it is the right size.", bonus: "Tell one person what the commitment is, so it exists somewhere outside your own head.", quiz: [{ question: "Which five-day commitment is best designed?", options: ["Twenty minutes of study after Maghrib, minimum five minutes", "Three hours of study every day", "Study as much as possible for five days", "No entertainment at all for five days"], answer: 0, explanation: "It is specific, modest, and carries a defined minimum for the day that falls apart." }, { question: "Why does the commitment need a minimum version?", options: ["Because one of the five days will go wrong, and the minimum keeps the run alive", "To make it easier", "To give you an escape route", "Because five days is a long time"], answer: 0, explanation: "Planning for the bad day in advance is what makes five consecutive days achievable." }, { question: "What does five days prove that one day does not?", options: ["That it survives conditions you did not choose", "That you are disciplined", "That the habit is permanent", "That you enjoy it"], answer: 0, explanation: "The value of five days is the variety of conditions it has to pass through." }, { question: "Day three goes badly and you only manage the minimum. What is the honest reading?", options: ["The commitment held, which is what the minimum is for", "You failed day three", "You should extend to six days to compensate", "The commitment was too ambitious"], answer: 0, explanation: "The minimum is part of the commitment, not a failure of it." }, { question: "You miss day four completely. What is the strongest response?", options: ["Do the minimum on day five and record the miss honestly", "Start the five days again from scratch", "Abandon the commitment", "Do double on day five"], answer: 0, explanation: "Returning immediately protects everything the first three days built." }, { question: "Why tell someone else what the commitment is?", options: ["It exists outside your own head, where it is harder to quietly revise", "They will check up on you", "It makes it more impressive", "It creates consequences for failing"], answer: 0, explanation: "Commitments held only internally are easy to renegotiate without noticing." }, { question: "How should you judge whether the size is right?", options: ["Whether you would back yourself to do it on your worst day this month", "Whether it feels challenging", "Whether it is more than you did last week", "Whether other people would find it difficult"], answer: 0, explanation: "The worst-day test is the one that predicts whether the run survives." }, { question: "What is the risk of choosing something too demanding?", options: ["It collapses on the first difficult day and teaches you nothing", "It takes too much time", "Other commitments suffer", "You will be too tired for day five"], answer: 0, explanation: "An over-sized commitment fails early, and the failure is the only thing it demonstrates." }] },
    { title: "Pick Your Weak Point", why: "The weakness you already know about is the one you have been carefully working around.", lesson: "You know what it is. The thing you avoid, the pattern you keep repeating, the situation you always handle badly. You have probably built a small set of workarounds so that it never has to be faced directly. Today you design a challenge that goes at it: specific, completable, and uncomfortable in the right way. Not a punishment, not extreme, not dangerous. Something that would count as evidence that this is no longer true of you.", keyIdea: "Design a specific challenge aimed at a weakness you already know you have.", example: "You avoid speaking in group settings, so the challenge is to ask one question out loud in every class this week.", actionPrompt: "Name one real weakness, design a specific challenge that addresses it, and begin it today.", actionHint: "Specific, completable and safe. If you cannot say when it is finished, it is not a challenge yet.", bonus: "Ask someone who knows you well whether you picked the right weakness.", quiz: [{ question: "You avoid speaking up in groups. Which challenge is best designed?", options: ["Ask one question out loud in every class this week", "Speak more in groups from now on", "Give a presentation to a large audience next month", "Stop being shy"], answer: 0, explanation: "It is specific, repeated, completable, and it can be judged as done or not done." }, { question: "What makes a challenge different from a punishment?", options: ["It produces evidence rather than discomfort for its own sake", "It is easier", "It is chosen rather than imposed", "It has a reward at the end"], answer: 0, explanation: "The purpose is evidence that something has changed, not suffering." }, { question: "Which of these disqualifies a challenge?", options: ["It cannot be safely completed", "It makes you uncomfortable", "It takes several days", "Other people will notice it"], answer: 0, explanation: "Discomfort is expected. Anything unsafe or extreme is out of scope for this course." }, { question: "Why does the lesson say you already know what the weakness is?", options: ["Most people have been working around it for years", "Because it is obvious to others", "Because it was covered earlier in the course", "Because everyone has the same weaknesses"], answer: 0, explanation: "The workarounds are usually well established, which is precisely why it never gets addressed." }, { question: "You cannot say when your challenge is finished. What does that mean?", options: ["It is not a challenge yet; give it a definite endpoint", "It is a long-term challenge", "It is too ambitious", "It is fine as long as you keep trying"], answer: 0, explanation: "Without an endpoint there is no moment at which the evidence exists." }, { question: "Why ask someone who knows you well whether you picked the right weakness?", options: ["The one you chose may be the one you are most comfortable admitting", "They will hold you to it", "It makes the challenge public", "They can help you complete it"], answer: 0, explanation: "The weakness you volunteer is often not the one doing the most damage." }, { question: "Your challenge turns out to be far too easy after two days. What is the strongest move?", options: ["Raise it once, and keep the endpoint definite", "Finish it as designed and choose another next month", "Abandon it and design a harder one from scratch", "Add three more challenges alongside it"], answer: 0, explanation: "One adjustment keeps the structure while restoring the difficulty." }, { question: "What would count as evidence that the weakness is no longer true of you?", options: ["Doing the thing repeatedly in real situations", "Feeling less afraid of it", "Knowing why you struggle with it", "Being willing to attempt it"], answer: 0, explanation: "Repeated action in real conditions is the only evidence that settles it." }] },
  ],
  [
    { title: "Salah Holds the Day", why: "Five fixed points in a day will do more for your discipline than any system you could design.", lesson: "You have spent thirty days learning to start, to notice, to keep a small promise and to return after a slip. Salah is where all of that stops being self-improvement and becomes worship. It is also, plainly, the strongest structure available to you: five appointments you did not choose, spread across the day, that break it into sections and pull you out of whatever you were lost in. The work now is not to pray more. It is to pray on time — to move when the adhan goes rather than when you have finished what you were doing.", keyIdea: "Pray at the start of the window rather than the end of it. On time is the whole discipline.", example: "You are mid-task when Asr comes in. You mark your place, pray, and come back. The task takes ten minutes longer and the day has a spine.", actionPrompt: "Pray every fard prayer today at the beginning of its window, and note the one that was hardest to move for.", actionHint: "The hard one is usually the prayer that lands inside something you enjoy. Name it in advance.", bonus: "Pray one prayer in congregation, or with someone in your house.", quiz: [{ question: "You are halfway through work you are enjoying and the adhan for Asr goes. What is the strongest move?", options: ["Mark your place, pray, and come back to it", "Finish the section first, then pray", "Pray at the end of the window when you are free", "Combine it with Maghrib later"], answer: 0, explanation: "Praying at the start of the window is the actual discipline. The work is still there afterwards." }, { question: "You have prayed all five today but three were rushed in the last ten minutes of their window. How should you read that?", options: ["The prayers counted, and the timing is the thing to work on next", "It was a wasted day", "Timing does not matter as long as they are prayed", "You should add extra nafl to compensate"], answer: 0, explanation: "They are valid and they are also not where you want to stay. Improvement here is about the clock, not the count." }, { question: "You are out with friends and Maghrib is nearly over. What does today ask of you?", options: ["Excuse yourself and pray", "Wait until you get home and pray then", "Skip it, since the situation made it difficult", "Ask them all to pray with you or not pray at all"], answer: 0, explanation: "Leaving for a few minutes is a small social cost. Losing the prayer is not a small thing." }, { question: "You have missed Fajr three days running. What is the useful response?", options: ["Change what happens the night before", "Promise yourself you will try harder", "Accept that you are not a morning person", "Set six alarms tomorrow"], answer: 0, explanation: "Fajr is usually decided by the previous evening. Attack the cause, not the moment." }, { question: "Which of these is the clearest sign salah is holding your day rather than fitting into it?", options: ["Your other commitments arrange themselves around the prayer times", "You never miss a prayer", "You pray for longer than you used to", "You feel calmer afterwards"], answer: 0, explanation: "When the fixed points shape the schedule instead of the schedule shaping them, the structure is doing its work." }, { question: "You realise mid-afternoon that you missed Dhuhr entirely. What should you do?", options: ["Pray it now, then carry on with the day", "Wait and pray it with Asr", "Skip it and be more careful tomorrow", "Treat the day as lost"], answer: 0, explanation: "Make it up as soon as you notice. Delay and despair both cost more than the mistake did." }, { question: "What is the difference between praying five times and praying on time?", options: ["One is the requirement met; the other is the requirement met without negotiation", "Nothing meaningful", "Only the second one counts", "The second is for people at a higher level"], answer: 0, explanation: "Both are prayers. Only one of them removes the daily argument about when." }, { question: "Your concentration in salah is poor and you are thinking about other things. What is the strongest response?", options: ["Keep praying, and bring your attention back each time you notice it wander", "Stop until you can focus properly", "Pray faster so there is less time to drift", "Only pray when you feel spiritually ready"], answer: 0, explanation: "Returning your attention is the practice. Waiting for a clear mind means waiting forever." }] },
    { title: "Qur’an, Every Day", why: "A small amount of Qur’an every day builds something that a long session once a month never will.", lesson: "Most people who want a relationship with the Qur’an approach it like a project: a big plan, a schedule, a target, and nothing three weeks later. The alternative is unglamorous and it works. A fixed small amount, at a fixed time, every day — half a page, a page, whatever survives your worst day. Read it, and read the meaning of what you read, because reciting words you do not understand is a beginning and not a destination. The point is not volume. It is that the Book becomes something you are in the middle of rather than something you mean to get to.", keyIdea: "A fixed daily portion you never miss beats a large portion you abandon.", example: "You read half a page after Fajr each morning with the translation beside it. In a year you have been through more than you would have managed in four ambitious weekends.", actionPrompt: "Read your chosen daily portion today, with the meaning, and write down one line that stayed with you.", actionHint: "Attach it to a prayer so it has a fixed moment: after Fajr, after Maghrib. Set the size at what you could do while ill.", bonus: "Read the same passage again tomorrow and see what you notice the second time.", quiz: [{ question: "You have twenty minutes free today and no plan for the Qur’an. What is the strongest move?", options: ["Read your fixed small portion and stop", "Read as much as you can in the twenty minutes", "Save it and do an hour at the weekend", "Read only if you can concentrate fully"], answer: 0, explanation: "The fixed portion is what survives. A large session today makes tomorrow feel like a failure by comparison." }, { question: "You can recite fluently but you do not understand most of what you read. What should change?", options: ["Add the meaning alongside the recitation", "Nothing, recitation is sufficient", "Stop reciting until you have learned Arabic", "Read faster so you cover more"], answer: 0, explanation: "Recitation has value and understanding is what changes how you act. Both, together, from today." }, { question: "You miss your portion for four days during exams. What is the useful response?", options: ["Read the smallest version today and continue", "Read four portions today to catch up", "Restart the habit next month when life is calmer", "Accept that you cannot keep it during busy periods"], answer: 0, explanation: "The return is the habit. Catching up and postponing both tend to end the practice." }, { question: "Which daily portion is best designed?", options: ["Half a page after Fajr, every day", "Three pages when you have time", "One juz a week, however you fit it", "As much as you feel like each day"], answer: 0, explanation: "Small, fixed and attached to an existing moment is the shape that survives a bad month." }, { question: "You read a passage and it clearly speaks to something you are doing wrong. What is the strongest response?", options: ["Change one specific thing about how you act", "Note how powerful the passage is and move on", "Feel bad about it for a while", "Read more to find something reassuring"], answer: 0, explanation: "The Book is not for admiring. A single concrete change is the honest response." }, { question: "A friend says they will start reading properly once they have more free time. What is the accurate reply?", options: ["A page a day starting now beats a plan that starts later", "That is sensible given how busy they are", "They should wait until they can give it real attention", "They should set a large target to motivate themselves"], answer: 0, explanation: "Free time does not arrive. The small daily version is available in any week." }, { question: "You have read your portion but rushed it and took nothing in. What now?", options: ["Re-read a few lines slowly, with the meaning", "The portion is done, so move on", "Read double tomorrow", "Start the whole portion again from the beginning"], answer: 0, explanation: "A short slow re-read recovers the point of the exercise without turning it into a punishment." }, { question: "What is the strongest reason to keep the same time each day?", options: ["It removes the daily decision about when", "It makes the reading feel more serious", "It means you read more overall", "It is easier to record"], answer: 0, explanation: "A fixed attachment point is what turns an intention into something that simply happens." }] },
    { title: "Dhikr and Dua", why: "Dhikr fills the gaps in your day, and dua is where you stop pretending you have everything handled.", lesson: "Your day is full of small empty spaces: walking, waiting, queueing, lying awake. They currently get filled with a screen. Dhikr is what fits there instead — short, repeatable, requiring nothing, available anywhere. Dua is different work. It is asking, in your own words, for what you actually want, which forces you to admit what that is. Most people find the second harder, because a real dua is specific and specificity is uncomfortable. Ask anyway, and ask for ordinary things as well as large ones.", keyIdea: "Fill the gaps with dhikr. Make dua specific enough to be uncomfortable.", example: "On the walk home you say SubhanAllah instead of opening your phone, and after Isha you ask for the one thing you have been too embarrassed to name.", actionPrompt: "Use dhikr in three gaps today, and make one specific dua in your own language.", actionHint: "Pick the gaps in advance: the walk, the queue, the ten minutes before sleep.", bonus: "Make dua for someone else, by name, without telling them.", quiz: [{ question: "You are waiting fifteen minutes for a bus and reach for your phone. What does today suggest?", options: ["Use the gap for dhikr instead", "Use the phone, since the gap is short", "Read Qur’an on your phone instead", "Plan the rest of your day"], answer: 0, explanation: "The empty gaps are exactly what dhikr is shaped for, and they are currently going to the screen." }, { question: "Which dua is doing the real work?", options: ["Naming the specific thing you want and asking for it", "A general request for goodness in this life and the next", "A memorised dua recited quickly", "Asking only for things you think are appropriate to ask for"], answer: 0, explanation: "General duas are good and specific ones force you to be honest about what you actually want." }, { question: "You have asked for the same thing for months and nothing has changed. What is the strongest response?", options: ["Keep asking, and keep taking the action it requires", "Stop asking, since it clearly is not going to happen", "Ask for something more realistic instead", "Assume you are asking incorrectly"], answer: 0, explanation: "Persistence in dua is not a failed strategy, and it was never meant to replace the effort." }, { question: "What makes dhikr different from most other good habits?", options: ["It needs no time, place, equipment or preparation", "It is easier than praying", "It works even without attention", "It replaces the need for dua"], answer: 0, explanation: "The absence of any requirement is precisely why it fits where nothing else does." }, { question: "You feel nothing while making dhikr. Should you continue?", options: ["Yes — the practice is the repetition, and attention grows into it", "No, wait until it feels meaningful", "Only if you can concentrate fully", "Switch to something you feel more strongly about"], answer: 0, explanation: "Waiting to feel something before you begin is how the habit never starts." }, { question: "Someone tells you their situation is beyond help. What is a useful thing to say?", options: ["That asking is still available, and it is not a last resort", "That they should be patient", "That everything happens for a reason", "That they should stop dwelling on it"], answer: 0, explanation: "Dua is not what you do when the options run out. Pointing at it gently is more useful than a slogan." }, { question: "You want to build dhikr into a day that is already full. Where does it fit best?", options: ["The transitions between things you already do", "A new block set aside for it", "Late at night when everything is finished", "Whenever you remember"], answer: 0, explanation: "Transitions are already dead time. Nothing has to be moved to use them." }, { question: "What does making dua for someone else, unnamed to them, actually train?", options: ["Wanting good for people with nothing coming back to you", "Your ability to remember names", "Your reputation as a thoughtful person", "The habit of praying longer"], answer: 0, explanation: "Removing the possibility of credit is what makes it a test of the intention." }] },
    { title: "Sabr Under Pressure", why: "Sabr is not waiting quietly for something to pass; it is holding your conduct steady while it does not.", lesson: "The English word patience makes sabr sound passive, and it is not. It has three faces: holding to what is right when it is hard, holding back from what is wrong when it is easy, and holding steady when something painful happens that you did not choose. All three are about conduct under load, not about feelings. You are allowed to find it difficult. You are allowed to be sad. What sabr asks is that the difficulty does not get to decide how you behave.", keyIdea: "Sabr governs your conduct under pressure. It does not require you to feel calm.", example: "You get news that ruins a plan you worked months for. You are genuinely upset, and you do not take it out on the people around you. That is sabr, not the absence of the upset.", actionPrompt: "Take one thing currently going badly and hold your conduct steady in it for a full day.", actionHint: "Decide in advance what steady looks like: what you will not say, and what you will still do.", bonus: "Say Alhamdulillah out loud at the moment it is hardest to mean.", quiz: [{ question: "Something you worked months for falls through and you are angry about it. What does sabr require?", options: ["That your conduct stays steady, even though the feeling is real", "That you stop feeling angry", "That you pretend it does not matter", "That you accept it without ever mentioning it"], answer: 0, explanation: "Sabr governs behaviour under pressure. It never demanded that you feel nothing." }, { question: "Which of these is also sabr, though people rarely call it that?", options: ["Holding back from something wrong that is easily available", "Waiting quietly for a difficulty to end", "Accepting bad treatment without response", "Never complaining to anyone"], answer: 0, explanation: "Restraint from the easy wrong is one of its three faces, alongside holding to the right and bearing the painful." }, { question: "You are being treated unfairly at work and it has gone on for weeks. What does sabr not mean here?", options: ["That you must never raise it or seek to change it", "That you keep your conduct honest while it continues", "That you can be upset about it", "That you keep doing your own work properly"], answer: 0, explanation: "Sabr is not passivity. Addressing a wrong through the right channels is entirely consistent with it." }, { question: "You have kept steady for three days and then snapped at someone. What is the honest response?", options: ["Repair it, and continue — three days held is not erased", "Conclude you have no sabr", "Start counting again from zero", "Explain that you were under pressure"], answer: 0, explanation: "The slip is real and so are the three days. Repair and continue is the whole method." }, { question: "A friend says they will be patient by simply not thinking about the problem. What is the accurate reply?", options: ["Not thinking about it is avoidance, which is a different thing", "That is a good approach", "They should think about it constantly instead", "Patience means nothing can be done"], answer: 0, explanation: "Sabr holds conduct steady while the thing is faced, not while it is ignored." }, { question: "Which situation is testing the second face of sabr — restraint?", options: ["Nobody would ever know if you took the easier dishonest route", "You are ill and cannot do what you planned", "You are waiting for exam results", "A project you care about is delayed"], answer: 0, explanation: "Restraint is tested precisely when the wrong thing is available and unobserved." }, { question: "What is the most useful thing to decide before a difficult day, rather than during it?", options: ["What you will not say, and what you will still do", "How long the difficulty will last", "Who is responsible for it", "How you expect to feel"], answer: 0, explanation: "Conduct decided in advance survives pressure. Conduct decided under pressure usually does not." }, { question: "You are bearing something difficult well, and nobody notices. What does that mean?", options: ["Nothing about its value", "You should mention it so people understand", "You are doing it wrong if it goes unrecognised", "It would count for more if it were seen"], answer: 0, explanation: "Sabr was never an audience-facing quality." }] },
    { title: "Shukr Changes What You See", why: "Gratitude is not a mood you summon; it is a direction you point your attention, and it changes what you notice.", lesson: "Your attention has a default setting, and for most people it is the gap — what is missing, what went wrong, what other people have. Shukr is the deliberate correction. Not pretending things are fine, and not talking yourself out of a real problem, but naming specifically what is actually there. Specific is the operative word: thanking Allah for everything is easy to say and does very little, while naming three particular things from today is uncomfortable at first and changes what you see tomorrow. Gratitude that never reaches your behaviour is only a feeling; the fuller version shows up as using well what you were given.", keyIdea: "Name specific blessings, not general ones — and let it change how you use them.", example: "Instead of a vague sense that you are lucky, you write down that your back did not hurt today, that your mother called, and that you had work to do at all.", actionPrompt: "Write down three specific things from today and thank Allah for them by name.", actionHint: "Specific means today, not in general. If it could have been written last year, it is too vague.", bonus: "Thank a person today for something they did that they probably think you did not notice.", quiz: [{ question: "Which is doing the work of shukr?", options: ["Naming three specific things from today", "Thanking Allah for everything in general", "Feeling generally fortunate", "Reminding yourself others have less"], answer: 0, explanation: "Specificity is what makes gratitude change what you notice. General thanks costs nothing and moves nothing." }, { question: "You are having a genuinely bad week. What does shukr ask?", options: ["Name what is still there, without pretending the week is fine", "Decide the week is not actually bad", "Wait until things improve to be grateful", "Compare yourself with people who have it worse"], answer: 0, explanation: "It is a correction to attention, not a denial of the difficulty." }, { question: "What is the fuller form of gratitude for something you were given?", options: ["Using it well", "Saying thank you more often", "Feeling strongly about it", "Telling others how fortunate you are"], answer: 0, explanation: "Gratitude that reaches behaviour is a different order of thing from gratitude that stays a feeling." }, { question: "Comparing yourself with people who have less makes you feel briefly grateful. What is the problem?", options: ["It depends on someone else's hardship, so it fades and teaches nothing", "Nothing, it is an effective method", "It is too difficult to keep up", "It only works if the comparison is accurate"], answer: 0, explanation: "Gratitude built on comparison is unstable and quietly unkind. Naming what is actually there does not need anyone else." }, { question: "Which of these is a well-formed entry?", options: ["My back did not hurt today", "I am grateful for my health", "I have a lot to be thankful for", "Things could be worse"], answer: 0, explanation: "Only the first is specific enough to be true of today rather than of any day." }, { question: "You have done this for a week and it feels mechanical. What is the strongest response?", options: ["Keep going, and make the entries more specific", "Stop until it feels genuine again", "Write more entries each day", "Accept that it does not work for you"], answer: 0, explanation: "Mechanical usually means vague. Sharper entries restore the effect faster than stopping does." }, { question: "Someone gives you something and you feel awkward about it. What does today suggest?", options: ["Thank them plainly and use it", "Refuse it to avoid the obligation", "Give them something back immediately", "Accept it and say nothing"], answer: 0, explanation: "Receiving well is part of the practice, and using it is part of thanking for it." }, { question: "What is the connection between shukr and how you spend your day?", options: ["What you notice as a blessing you tend to protect and use", "There is no practical connection", "Gratitude reduces ambition", "Grateful people work less"], answer: 0, explanation: "Attention drives behaviour. What you name as given, you handle differently." }] },
    { title: "Tie It, Then Trust", why: "Tawakkul is not the absence of effort; it is effort placed properly, with the outcome left where it belongs.", lesson: "There is a well-known narration in which a man asks whether he should leave his camel untied and trust Allah, and is told to tie it and then trust. That is the whole principle in one image. Tawakkul is not a substitute for preparation, and preparation is not a substitute for tawakkul. You do the work — properly, to the standard you are capable of — and then you release the result, because the result was never yours to control. Two failures are common: skipping the rope and calling it faith, and gripping the outcome so hard that a delay feels like a verdict.", keyIdea: "Do the work properly, then release the outcome. Both halves are required.", example: "You prepare thoroughly for the interview, and on the morning you stop rehearsing what you cannot influence and hand the result over.", actionPrompt: "Take something you are anxious about, do the one piece of preparation that is genuinely yours, and then stop.", actionHint: "Write down what is your work and what is not. Do the first list. Leave the second.", bonus: "Notice the moment you start rehearsing an outcome you cannot affect, and stop there.", quiz: [{ question: "You have an important exam tomorrow. What does tawakkul actually ask of you?", options: ["Prepare properly, then stop rehearsing the result", "Trust and stop worrying about preparation", "Prepare until the last possible minute", "Assume the outcome is already fixed so effort is irrelevant"], answer: 0, explanation: "Tie the camel, then trust. Both halves, in that order." }, { question: "A friend says they did not revise because it is all decreed anyway. What is the accurate reply?", options: ["The decree includes the effort they were meant to make", "They are right, so the result is out of their hands", "They should have revised for appearance", "Effort only matters for worldly things"], answer: 0, explanation: "Leaving the rope off and calling it trust inverts the principle." }, { question: "You prepared thoroughly and it still went badly. What does tawakkul say?", options: ["The work was yours and the outcome was not", "You did not prepare well enough", "Your trust was insufficient", "The effort was wasted"], answer: 0, explanation: "You are answerable for the effort. The result belongs elsewhere, and a bad one is not a verdict on your trust." }, { question: "Which is the clearest sign you are gripping an outcome too hard?", options: ["You keep rehearsing scenarios you cannot influence", "You prepared carefully", "You care about the result", "You asked for it in dua"], answer: 0, explanation: "Caring and preparing are fine. Repeatedly replaying what you cannot affect is the tell." }, { question: "You have done everything you can and the answer is a week away. What is the strongest use of that week?", options: ["Get on with the next piece of work", "Keep checking for news", "Prepare a backup for every possible outcome", "Try not to think about it at all"], answer: 0, explanation: "Releasing the result frees the week for something useful. That is the practical payoff." }, { question: "How does tawakkul relate to planning ahead?", options: ["It requires it — planning is part of the effort you owe", "It replaces the need for it", "It makes planning a sign of weak faith", "They are unrelated"], answer: 0, explanation: "The rope is the plan. Trust sits on top of it, not instead of it." }, { question: "You are unsure whether something is your responsibility or outside your control. What helps?", options: ["Write two lists, act on the first, and leave the second", "Assume it is all your responsibility", "Assume none of it is", "Wait until it becomes obvious"], answer: 0, explanation: "The split is the practical form of the principle, and writing it down makes it decidable." }, { question: "What is the honest relationship between dua and effort here?", options: ["You ask for what you want and work for it at the same time", "Dua is for when effort fails", "Effort makes dua unnecessary", "Dua is a substitute for preparation"], answer: 0, explanation: "They run together. Neither one is the fallback position for the other." }] },
    { title: "Master the Nafs", why: "Anger and desire both promise that acting now is the only option, and both are lying about that.", lesson: "The nafs wants what it wants immediately, and its main tactic is urgency: this cannot wait, you deserve this, they need to hear this now. Anger and desire look like opposites and run the same play. The defence is the same too, and it is unglamorous — put distance between the impulse and the act. Change your physical position. Delay by a fixed, short amount. Remove the thing from reach rather than negotiating with it in your head. This is not about becoming someone who never feels these things. It is about no longer being governed by the first thirty seconds.", keyIdea: "Anger and desire both run on urgency. Break the urgency and you break the grip.", example: "You are furious and about to send the message. You stand up, walk to another room, and by the time you sit down you are writing something much shorter.", actionPrompt: "The next time anger or desire arrives today, change your physical position before you do anything else.", actionHint: "Physical first: stand, walk, leave the room, put the phone down. Reasoning with it rarely works in the moment.", bonus: "Identify the situation that reliably catches you, and change it before it comes round again.", quiz: [{ question: "You are furious and have already typed the reply. What is the strongest move?", options: ["Stand up and leave the room without sending it", "Send it while the point is sharp", "Reason yourself out of the anger first", "Delete it and never raise the matter"], answer: 0, explanation: "Physical distance breaks the urgency faster than argument does, and the matter can still be raised later." }, { question: "What do anger and desire have in common as the nafs uses them?", options: ["Both insist that acting immediately is the only option", "Both feel unpleasant", "Both are always wrong", "Both come from other people"], answer: 0, explanation: "Urgency is the shared mechanism, which is why the same defence works on both." }, { question: "Something you should not be looking at is one tap away and you keep resisting it. What is the stronger strategy?", options: ["Remove it so there is nothing to resist", "Keep resisting and build willpower", "Allow yourself a limited amount", "Only resist when you feel strong"], answer: 0, explanation: "Repeated resistance drains you. Removing the access is one decision instead of forty." }, { question: "Is the goal to stop feeling anger altogether?", options: ["No — the goal is to stop the first thirty seconds deciding what you do", "Yes, anger is always wrong", "Yes, if your faith is strong enough", "No, and there is nothing to work on"], answer: 0, explanation: "The feeling is human. Its authority over your behaviour is what is being reduced." }, { question: "You keep falling into the same thing at the same time of night. What does today suggest?", options: ["Change the situation before that hour comes round", "Try harder at that hour", "Stay up later so you are too tired", "Accept it as a weakness you have"], answer: 0, explanation: "A reliable trigger is an opportunity: it can be dismantled in advance rather than fought in the moment." }, { question: "You held back today and nobody knows you did. What is the accurate reading?", options: ["That is exactly the kind that counts", "It counts for less because it was unseen", "You should tell someone so it is recognised", "It only matters if it was difficult"], answer: 0, explanation: "Restraint that nobody witnesses is the clearest evidence of who you are when unobserved." }, { question: "You gave in after two weeks of holding steady. What now?", options: ["Return immediately, and look at what changed that day", "Conclude the two weeks meant nothing", "Punish yourself so it does not recur", "Lower your standard so it is easier to keep"], answer: 0, explanation: "The return matters more than the slip, and the conditions that produced it are the useful information." }, { question: "Which delay is best designed?", options: ["A short fixed one — ten minutes, or until after Maghrib", "An open-ended one, until you feel ready", "A permanent ban", "No delay, but a promise to be careful"], answer: 0, explanation: "Short and specific is keepable. Open-ended and permanent both tend to collapse." }] },
    { title: "The Door That Stays Open", why: "The point of tawbah is not that you never fall; it is that the way back is never closed.", lesson: "Two things stop people returning after a real mistake, and both are forms of pride. The first is minimising it, so nothing has to change. The second is despair — deciding you have gone too far, which sounds like humility and is actually a claim about the size of your sin against the size of His mercy. Tawbah is neither. It is straightforward: admit it plainly, stop doing it, feel the weight of it honestly, intend not to return, and where a person was wronged, put it right with them. Then get up. Carrying it further is not part of the process.", keyIdea: "Admit it, stop, mean it, and put right what involved someone else. Then get up.", example: "You did something you are ashamed of, you stop, you make the specific repair to the person affected, and you do not spend the next month telling yourself you are worthless.", actionPrompt: "Take one thing you have been avoiding facing, make tawbah for it properly, and make any repair that involves another person.", actionHint: "If someone else was harmed, the repair to them is part of it, not an optional extra.", bonus: "Change one practical thing that made it easy, so the next time is harder.", quiz: [{ question: "You have done something you are genuinely ashamed of. What is the strongest response?", options: ["Admit it, stop, intend not to return, and repair what involved others", "Decide you have gone too far to come back", "Tell yourself it was not that serious", "Carry the guilt as a permanent reminder"], answer: 0, explanation: "Minimising and despairing are both ways of not doing the actual work." }, { question: "Your mistake harmed another person. What does tawbah require that it otherwise would not?", options: ["Putting it right with them directly", "Nothing additional", "Telling others what you did", "Avoiding that person from now on"], answer: 0, explanation: "Where a right of a person is involved, the repair to them is part of the return, not an optional extra." }, { question: "Someone says they have sinned too much to be forgiven. What is the accurate reply?", options: ["That is a claim about the limits of mercy, and it is not theirs to make", "They should feel the weight of it", "They should start again from a clean slate elsewhere", "They are probably right to be worried"], answer: 0, explanation: "Despair dressed as humility is still despair, and it keeps people away from the door." }, { question: "You made tawbah last month and fell into the same thing again. What now?", options: ["Make it again, and change something practical this time", "Conclude your tawbah was insincere", "Stop making tawbah until you are sure you can hold", "Accept it as part of who you are"], answer: 0, explanation: "Repetition is not disqualifying. Changing the conditions is what makes the next attempt different." }, { question: "What is the difference between remorse and dwelling?", options: ["Remorse produces a change; dwelling produces weight", "Dwelling shows you are more sincere", "There is no difference", "Remorse is for small things, dwelling for large ones"], answer: 0, explanation: "Extended self-punishment is not a higher form of repentance. It just postpones the getting up." }, { question: "Which is part of tawbah and which is not?", options: ["Stopping the action is part of it; telling everyone is not", "Both are required", "Neither is required", "Telling everyone is required, stopping is optional"], answer: 0, explanation: "Publicising a private sin is not a component of the return, and can cause fresh harm." }, { question: "You want to make it harder to repeat. What is the strongest kind of change?", options: ["A change to the situation, not a promise about your intentions", "A stronger resolution", "A punishment you set for yourself", "A reminder note"], answer: 0, explanation: "The situation is what will still be there next month. Resolutions tend not to be." }, { question: "What does the phrase the door stays open actually mean in practice?", options: ["You can return today, whatever happened yesterday", "You will eventually be forgiven automatically", "Sin does not really matter", "There is no urgency about returning"], answer: 0, explanation: "It removes the excuse for staying away, without removing the seriousness of what happened." }] },
    { title: "Akhlaq Is the Proof", why: "How you treat people is not a separate subject from your Deen; it is where the rest of it becomes visible.", lesson: "It is possible to be scrupulous about prayer and fasting and be unbearable to live with. The two are not in different departments. Character is where worship shows up in the world: your tone when you are tired, whether you keep your word when it costs you, how you speak about people who are not in the room, whether the people closest to you find you easy or exhausting. That last one is the honest test, because family sees the unperformed version. Good akhlaq is not softness; it is honesty, restraint, keeping promises, and being safe to be around.", keyIdea: "Your character with people is where your worship becomes visible. Family is the honest test.", example: "You are courteous at the masjid and short with your mother an hour later. The second one is the more accurate reading.", actionPrompt: "Notice how you speak to the people in your own house today, and correct one thing about it.", actionHint: "Tone, not content. Most of it is how things are said, and it is usually worst when you are tired.", bonus: "Apologise to someone at home for something small you have never acknowledged.", quiz: [{ question: "Someone prays regularly and is consistently harsh with their family. What is the accurate reading?", options: ["The character is where the worship is meant to be showing, and it is not", "The prayers make up for it", "The two are unrelated areas of life", "Family are easier to be harsh with, so it does not count"], answer: 0, explanation: "Worship and conduct are not separate departments. The gap between them is the thing to work on." }, { question: "Which is the more honest test of your character?", options: ["How you are with your family when you are tired", "How you are with strangers", "How you are at the masjid", "How you are when things are going well"], answer: 0, explanation: "The unperformed version is the real one, and family sees it." }, { question: "A group is speaking about someone who is not present. What is the strongest move?", options: ["Change the subject, or say something that ends it", "Stay silent and listen", "Join in mildly so as not to seem superior", "Defend the person at length"], answer: 0, explanation: "Silence keeps it running. Ending it quietly costs little and is the point." }, { question: "Keeping your word turns out to cost you more than expected. What does good akhlaq require?", options: ["Keep it, or tell them early and repair it", "Keep it silently regardless of the cost", "Quietly drop it, since circumstances changed", "Explain afterwards why it was not possible"], answer: 0, explanation: "Early honesty is part of keeping your word. Silence until it is too late is not." }, { question: "Is good character the same as being agreeable?", options: ["No — honesty and refusing wrong are part of it", "Yes, it means never causing discomfort", "Yes, it means agreeing to keep peace", "No, it means being blunt at all times"], answer: 0, explanation: "Softness that will not say a true thing is not akhlaq. Neither is bluntness without care." }, { question: "You were short with someone this morning because you were tired. What is the strongest response?", options: ["Go back and put it right, without a long explanation", "Explain that you were tired", "Let it go, since it was minor", "Be extra pleasant for the rest of the day"], answer: 0, explanation: "A plain repair works. Tiredness is a reason and it is not a defence." }, { question: "Which change is most likely to improve how people experience you?", options: ["Your tone when you are under pressure", "The advice you give", "How much you help with large things", "How often you attend gatherings"], answer: 0, explanation: "Tone under pressure is what people actually remember about being around you." }, { question: "Someone is difficult and does not deserve good treatment from you. What does today suggest?", options: ["Your conduct is yours regardless of what they deserve", "Match how they treat you", "Avoid them completely", "Be pleasant only while others are watching"], answer: 0, explanation: "Character that is conditional on the other person is not character; it is a reaction." }] },
    { title: "Closer Than Yesterday", why: "The aim of these ten days is not a stricter routine; it is a relationship that keeps going when the routine slips.", lesson: "You have covered salah, Qur’an, dhikr and dua, sabr, shukr, tawakkul, the nafs, tawbah and akhlaq. Held separately they are nine practices. Held together they are one relationship, and a relationship is measured differently from a checklist: not by the perfect week, but by how quickly you come back after a bad one, and by whether you turn to Him in ordinary moments rather than only in emergencies. Today, pick the one of the nine that is weakest and build the small permanent version of it. Not the impressive version. The one that will still be running in a year.", keyIdea: "Choose the weakest of the nine and build the version of it that survives a bad month.", example: "You know your Fajr is the weak point, so instead of a plan to overhaul your whole worship you move your phone charger out of the bedroom.", actionPrompt: "Name the weakest of the nine practices, and set the smallest permanent version of it starting today.", actionHint: "Smallest permanent version: what you could still do in your worst week this year.", bonus: "Write one line about what you want your relationship with Allah to look like in a year, and keep it somewhere you will see it.", quiz: [{ question: "Which of the nine should you build on today?", options: ["The weakest one, at its smallest permanent size", "The one you already do best", "All nine at once", "The one that sounds most impressive"], answer: 0, explanation: "The weakest link carries the most return, and the small permanent version is what will still exist in a year." }, { question: "Your worship was strong for three weeks and has fallen off badly. How should you read that?", options: ["As normal, and as a signal to return today rather than to start over", "As proof it was never sincere", "As a reason to wait for Ramadan and restart", "As evidence you should aim lower permanently"], answer: 0, explanation: "A relationship is measured by the speed of return, not by an unbroken record." }, { question: "What distinguishes a relationship from a checklist here?", options: ["You turn to Him in ordinary moments, not only in emergencies", "It requires more time each day", "It has no specific practices attached", "It cannot be measured at all"], answer: 0, explanation: "The ordinary moments are the difference. Emergency-only contact is a pattern most people recognise." }, { question: "You are choosing between an ambitious plan and a small permanent one. What does today say?", options: ["Small and permanent", "Ambitious, because the aim is high", "Ambitious now, small later if it fails", "Neither — wait until life is calmer"], answer: 0, explanation: "The ambitious version has a predictable ending. The small one is still running when it matters." }, { question: "Which is the strongest indicator that these ten days actually landed?", options: ["You return quickly after a bad week", "You never miss anything", "You can explain all nine practices", "You feel more spiritual"], answer: 0, explanation: "The return is the measurable behaviour, and it is the one the whole course has been training." }, { question: "A friend wants to overhaul their entire worship starting Monday. What is the useful thing to say?", options: ["Pick one weak point and make it permanent", "Support the plan as it stands", "Tell them it will not work", "Suggest they wait until they are more consistent"], answer: 0, explanation: "Redirecting to one durable change is more useful than either cheering on or dismissing the overhaul." }, { question: "Days 31 to 40 sit on the thirty days before them. What did those provide?", options: ["The habits that carry a practice through an ordinary week", "Nothing that applies here", "A test that had to be passed first", "Motivation to be more religious"], answer: 0, explanation: "Attention, consistency and returning after a slip are exactly what a regular practice runs on." }, { question: "What is the honest measure of progress in this section?", options: ["Whether something small is still running in a month", "How much you did this week", "How you felt during it", "How much you know about each practice"], answer: 0, explanation: "Durability is the measure. Volume and feeling both fluctuate; a small practice still running is evidence." }] },
  ],
  [
    { title: "Understanding People", why: "Most misunderstandings come from assuming someone works the way you do.", lesson: "People arrive at the same moment carrying different experiences, values and pressures. Someone who goes quiet may be thinking, tired, worried, or simply not a talker — and you cannot tell which from the outside. The useful habit is to hold your first explanation loosely and check it. One interaction is a very small sample, and people are rarely at their most typical the first time you meet them.", keyIdea: "Your first explanation of someone's behaviour is a guess. Check it before you rely on it.", example: "A classmate who never replies to messages might be rude, or might have their notifications off. The behaviour is identical; the explanations are not.", actionPrompt: "Have a conversation where you try to understand the other person's view instead of comparing it to yours.", actionHint: "Notice the moment you want to say “but I think…” and ask a question instead.", bonus: "Ask someone why they see something differently from you, and let the answer stand without arguing.", quiz: [{ question: "Someone you know walks past you without saying hello. What is the strongest first thought?", options: ["There are several possible reasons, and you do not know which yet", "They are ignoring you deliberately", "They have decided they do not like you", "You must have done something wrong"], answer: 0, explanation: "The behaviour has many explanations. Picking the worst one and acting on it is how misunderstandings start." }, { question: "A friend gives an opinion that seems obviously wrong to you. What is the strongest response?", options: ["Ask what led them to think that", "Explain why they are mistaken", "Agree to avoid the discussion", "Assume they have not thought about it"], answer: 0, explanation: "The reasoning behind an opinion is usually more informative than the opinion itself." }, { question: "You met someone once and found them unfriendly. What is the most reasonable conclusion?", options: ["One interaction is a very small sample", "They are an unfriendly person", "They dislike you specifically", "You should avoid them from now on"], answer: 0, explanation: "People are rarely at their most typical in a first meeting. One data point is not a pattern." }, { question: "Someone reacts far more strongly to something than you expected. What is most likely?", options: ["It connects to something in their experience that you cannot see", "They are overreacting", "They are trying to cause a scene", "They misunderstood you on purpose"], answer: 0, explanation: "A reaction that seems disproportionate usually has a history attached that is invisible from outside." }, { question: "You do not understand why someone said what they said. What should you do?", options: ["Ask them what they meant", "Work it out yourself later", "Assume the least generous meaning", "Ask a mutual friend what they think"], answer: 0, explanation: "Asking directly is faster and more accurate than guessing or asking around." }, { question: "Two friends describe the same argument completely differently. What does this tell you?", options: ["Both can be honest and still remember it differently", "One of them is lying", "Neither account is worth listening to", "The truth is exactly halfway between"], answer: 0, explanation: "Different vantage points produce genuinely different accounts without anyone being dishonest." }, { question: "You notice you are about to say “but I would have…”. What is the more useful move?", options: ["Ask a question about their situation instead", "Say it, since your view is relevant", "Say nothing at all", "Change the subject"], answer: 0, explanation: "Comparing their situation to yours ends the explanation. A question continues it." }, { question: "What actually helps you understand someone better?", options: ["Asking questions and holding your first impression loosely", "Watching them closely without asking anything", "Deciding early what kind of person they are", "Assuming they think like you"], answer: 0, explanation: "Understanding comes from asking and revising, not from observing and concluding." }] },
    { title: "Listening Properly", why: "Most people are so used to being half-heard that full attention is genuinely noticeable.", lesson: "Listening is not waiting quietly for your turn. It means letting someone finish, not drafting your reply while they talk, and asking a follow-up that proves you heard. It also means reading what they need: some people want advice, and some want to be heard. Guessing wrong is the most common way a supportive conversation goes flat. If you are unsure, ask — “do you want ideas, or do you just want to talk it out?” is a question almost nobody minds.", keyIdea: "Listening means letting them finish, then asking something that proves you heard.", example: "Remembering that someone had an exam last week and asking how it went does more than any amount of advice.", actionPrompt: "Have a conversation where your only goal is to understand the other person as well as possible.", actionHint: "Do not plan your reply while they are still speaking.", bonus: "Go three questions deep on one topic without turning the conversation back to yourself.", quiz: [{ question: "Your friend is telling you about something frustrating. What is the strongest first response?", options: ["Listen and ask a genuine follow-up question", "Immediately tell them what they did wrong", "Change the subject", "Start telling a similar story about yourself"], answer: 0, explanation: "Being heard comes first. Advice, redirection and comparison all skip that step." }, { question: "You are not sure whether someone wants advice or just wants to talk. What should you do?", options: ["Ask which one they want", "Give advice, since it is more useful", "Say nothing and let them continue", "Guess based on how upset they seem"], answer: 0, explanation: "Asking takes five seconds and removes the most common way these conversations go wrong." }, { question: "You notice you are planning your reply while they are still talking. What should you do?", options: ["Stop planning and listen to the rest", "Keep planning so your reply is good", "Interrupt before you forget your point", "Nod more to look attentive"], answer: 0, explanation: "You cannot draft and listen at once. The end of their sentence matters more than your reply." }, { question: "A friend mentions something important in passing. What is the strongest thing to do?", options: ["Remember it and ask about it next time", "Comment on it immediately and move on", "Write it down in front of them", "Assume they will bring it up again if it matters"], answer: 0, explanation: "Remembering and returning to it later is one of the clearest signals that you were actually listening." }, { question: "Someone is telling a long story and you already know the point. What should you do?", options: ["Let them finish", "Finish the sentence for them", "Tell them you already know", "Check your phone until they are done"], answer: 0, explanation: "Interrupting to save time costs more than the time it saves." }, { question: "What proves to someone that you were listening?", options: ["A follow-up question that could only come from having heard them", "Saying “I'm listening”", "Constant eye contact", "Repeating their words back"], answer: 0, explanation: "A specific follow-up is evidence. Declarations and mechanics are not." }, { question: "You disagree with something a friend is saying while they explain it. What is the strongest move?", options: ["Hear the whole thing, then respond", "Interrupt to correct them early", "Stop listening, since you already disagree", "Agree to keep the peace"], answer: 0, explanation: "Responding to half an argument usually means responding to the wrong argument." }, { question: "A friend shares a problem and you have a good solution. What should come first?", options: ["Understanding the problem properly and letting them feel heard", "The solution, immediately", "A story about when it happened to you", "Telling them it is not that serious"], answer: 0, explanation: "Advice before someone feels heard usually lands as dismissal, however good the advice is." }] },
    { title: "Starting Friendships", why: "Most friendships that never happened were only ever one conversation short.", lesson: "Friendships usually start with something ordinary: a question about the situation you are both in. You do not need an opening line, and you certainly do not need techniques for making people like you — those are transparent and they do not work. What works is being approachable, asking things you actually want to know, and accepting that friendship takes several interactions. Almost nobody becomes a friend in one conversation, which means an unremarkable first chat is not a failure.", keyIdea: "Friendships come from repeated ordinary conversations, not from one impressive one.", example: "“How are you finding this?” to someone in the same class works every time and takes no preparation.", actionPrompt: "Start a genuine conversation with someone you do not normally talk to.", actionHint: "Ask about the thing you are both currently doing. It is always available.", bonus: "Speak to the same person again a few days later and remember something they told you.", quiz: [{ question: "You have spoken to someone a few times and want to become better friends. What is a useful next step?", options: ["Have another genuine conversation and suggest doing something together", "Tell them everything about yourself immediately", "Wait for them to do everything", "Try to impress them constantly"], answer: 0, explanation: "Friendship needs someone to suggest the next thing. Waiting is how most of them quietly end." }, { question: "Your first conversation with someone was pleasant but unremarkable. What does that mean?", options: ["It was normal — friendships take several interactions", "You are not compatible", "You should have been more interesting", "You should not speak to them again"], answer: 0, explanation: "Almost nobody becomes a friend in one conversation. Unremarkable is the usual starting point." }, { question: "You want to start a conversation with someone you do not know. What is the easiest opening?", options: ["A question about the situation you are both in", "A prepared interesting fact", "A compliment about their appearance", "Waiting until they speak first"], answer: 0, explanation: "The shared situation is always available and never sounds rehearsed." }, { question: "Someone gives short answers when you try to talk to them. What is the strongest reading?", options: ["They may be busy or shy — try again another time", "They do not want to be friends with you", "You are bad at conversation", "You should keep talking to fill the silence"], answer: 0, explanation: "Short answers have many causes. One attempt is not enough information to conclude anything." }, { question: "Which approach actually builds friendships?", options: ["Being genuinely interested in people", "Learning techniques to make people like you", "Agreeing with everything they say", "Being the most entertaining person present"], answer: 0, explanation: "Genuine interest is both easier and more effective. Techniques are visible and they do not hold." }, { question: "You are at an event and want to meet people. What is the most useful goal?", options: ["Have one or two real conversations", "Speak to everybody there", "Be the most memorable person in the room", "Wait to be introduced"], answer: 0, explanation: "One or two real conversations is achievable and useful. The rest is either exhausting or passive." }, { question: "You notice someone standing on their own. What is the strongest move?", options: ["Go over and include them", "Assume they prefer to be alone", "Wait for someone else to do it", "Mention to others that they are alone"], answer: 0, explanation: "Including someone is one of the cheapest and most remembered things you can do." }, { question: "What makes someone approachable?", options: ["Open posture, a warm face, and not being buried in a phone", "Being the loudest person in the group", "Waiting quietly to be spoken to", "Having interesting things to say"], answer: 0, explanation: "Approachability is mostly physical and happens before anyone speaks." }] },
    { title: "Becoming Trustworthy", why: "Trust is the thing people quietly decide about you, and it is decided by evidence.", lesson: "Nobody trusts you because you say you are trustworthy. They trust you because you did what you said you would, several times, including when it was inconvenient. That is the whole mechanism. It also means trust is damaged by small things — a forgotten favour, a repeated “I'll do it tomorrow” — more often than by dramatic betrayals. Two things protect it: telling people early when you cannot do something, and never repeating what was told to you privately.", keyIdea: "Trust is built through repeated evidence, and lost through small repeated failures.", example: "Someone who always replies to messages within a day is trusted with more than someone who is brilliant but unpredictable.", actionPrompt: "Identify one promise or responsibility you owe someone, and actually do it today.", actionHint: "Pick the one you have been putting off. That is the one that is costing you.", bonus: "Tell someone early about a commitment you now cannot keep, instead of letting the deadline arrive.", quiz: [{ question: "You told a friend you would do something, but now you realise you cannot. What should you do?", options: ["Tell them honestly as soon as possible", "Ignore it and hope they forget", "Pretend you forgot", "Blame someone else"], answer: 0, explanation: "Early honesty costs far less than a missed commitment nobody was warned about." }, { question: "A friend tells you something private. Later, someone asks about it. What should you do?", options: ["Say it is not yours to share", "Share it with one person you trust", "Share it if they would never find out", "Share a vague version of it"], answer: 0, explanation: "A confidence is not conditional on whether breaking it would be discovered." }, { question: "You made a mistake that nobody has noticed yet. What is the strongest move?", options: ["Tell them and fix it", "Say nothing, since no harm was done", "Wait to see if anyone notices", "Fix it quietly and never mention it"], answer: 0, explanation: "Being the person who reports their own mistakes is worth more than never appearing to make one." }, { question: "Which damages trust most over time?", options: ["Repeatedly not doing small things you said you would", "One large mistake you admitted to", "Being unavailable sometimes", "Disagreeing with someone openly"], answer: 0, explanation: "Trust erodes through small repeated failures far more often than through single dramatic ones." }, { question: "How do people actually decide whether to trust you?", options: ["By whether your actions have matched your words, repeatedly", "By how sincere you seem", "By what you say about yourself", "By how long they have known you"], answer: 0, explanation: "Trust is a conclusion drawn from evidence. Sincerity and time alone do not produce it." }, { question: "You are asked to do something you are not sure you can manage. What is the strongest response?", options: ["Say what you can realistically commit to", "Agree and hope it works out", "Agree, then quietly not do it", "Refuse everything to be safe"], answer: 0, explanation: "An accurate smaller promise builds more trust than an ambitious one you may not keep." }, { question: "A friend keeps saying they will do things and then not doing them. What is happening?", options: ["They are spending trust faster than they are building it", "They are just forgetful and it does not matter", "They are being deliberately dishonest", "Nothing — intentions are what count"], answer: 0, explanation: "Intentions do not register. Only the pattern of follow-through does." }, { question: "You did what you promised, but nobody noticed. What is true?", options: ["It still counts — trust accumulates whether or not it is remarked on", "It was wasted effort", "You should point it out", "It only counts if someone was watching"], answer: 0, explanation: "Reliability accumulates quietly. That is exactly why it is dependable." }] },
    { title: "Being a Good Friend", why: "People remember who showed up far longer than they remember who was entertaining.", lesson: "Being a good friend is mostly unglamorous. It is checking in without being asked, being genuinely pleased when something goes well for them, turning up when it is inconvenient, and telling the truth in a way that does not wound. It also means giving space when someone needs it rather than treating quiet as rejection. And it has to run both ways: a friendship where one person does all the reaching eventually stops being a friendship.", keyIdea: "Show up, be honest without being cruel, and let it run in both directions.", example: "Messaging “how did it go?” the day after something mattered to them costs nothing and is remembered.", actionPrompt: "Do one thoughtful thing for a friend today without expecting anything back.", actionHint: "Small and specific beats grand and vague.", bonus: "Congratulate someone properly on something that went well for them, with no comparison to yourself.", quiz: [{ question: "Something good happens to your friend, and it is something you also wanted. What is the strongest response?", options: ["Be genuinely pleased for them and say so", "Congratulate them briefly and change the subject", "Point out how close you came", "Say nothing about it"], answer: 0, explanation: "Celebrating someone properly, especially when it stings a little, is one of the clearest marks of a real friend." }, { question: "A friend has gone quiet and is not replying much. What is the strongest response?", options: ["Let them know you are there, then give them space", "Message repeatedly until they answer", "Assume the friendship is over", "Confront them about ignoring you"], answer: 0, explanation: "Availability without pressure respects that people sometimes need room." }, { question: "You need to tell a friend something they will not want to hear. How should you do it?", options: ["Honestly and kindly, in private", "Bluntly, so it definitely lands", "Hint at it and hope they work it out", "Not at all, to protect the friendship"], answer: 0, explanation: "Honesty and kindness are compatible. Bluntness and avoidance are both easier and both worse." }, { question: "You notice you are always the one starting conversations in a friendship. What is worth doing?", options: ["Say something about it honestly, and see what changes", "Stop reaching out and see if they notice", "Carry on and say nothing", "End the friendship"], answer: 0, explanation: "Friendship needs to run both ways. Naming it gives it a chance to; testing them silently does not." }, { question: "A friend is going through something difficult. What is usually most useful?", options: ["Checking in regularly without needing them to perform being fine", "Giving them advice each time you speak", "Waiting until they ask for help", "Telling them it could be worse"], answer: 0, explanation: "Steady, undemanding contact is what people remember from difficult periods." }, { question: "What is the most useful kind of compliment to give a friend?", options: ["One about their character or effort", "One about their appearance", "One about what they own", "An exaggerated one, so it feels bigger"], answer: 0, explanation: "Character and effort are things people chose, which is why those compliments land differently." }, { question: "Your friend cancels plans at short notice for the second time. What is the strongest first response?", options: ["Ask if everything is alright before deciding anything", "Assume they do not value your time", "Cancel on them next time to make the point", "Say nothing and quietly withdraw"], answer: 0, explanation: "Two cancellations may be a pattern or may be a hard month. Asking finds out; assuming does not." }, { question: "What does being a good friend mostly consist of?", options: ["Ordinary, repeated, slightly inconvenient turning up", "Being fun to be around", "Always having good advice", "Being available at every moment"], answer: 0, explanation: "Friendship is built from unremarkable reliability, not from being impressive or infinitely available." }] },
    { title: "Empathy", why: "Understanding what someone might be carrying changes how you respond to them.", lesson: "Empathy is the attempt to understand someone's experience from where they are standing, not from where you are. It is not agreeing with them, and it is not deciding you already know how they feel. Two people can live through the same event and come out of it differently, which is why asking beats assuming. The most practical version is a single habit: before responding, ask yourself what this person might be dealing with that you cannot see — then ask a question rather than filling in the answer yourself.", keyIdea: "Empathy is asking rather than assuming, and it does not require agreeing.", example: "Someone snapping at you may have had a bad morning that has nothing to do with you. Asking is the only way to find out.", actionPrompt: "In one conversation, ask yourself what this person might be experiencing that you cannot see — then ask a respectful question instead of assuming.", actionHint: "“Are you alright?” with room to answer is usually enough.", bonus: "Ask someone how they experienced something you were both present for, and notice the differences.", quiz: [{ question: "A friend seems unusually quiet. What is a good first response?", options: ["Ask if they are okay and give them room to answer", "Assume you know exactly what is wrong", "Make fun of them to lighten the mood", "Immediately tell them how to fix their life"], answer: 0, explanation: "Asking with room to answer respects that you do not yet know what is happening." }, { question: "Someone is upset about something you would not find upsetting. What is the strongest response?", options: ["Take their reaction seriously and ask about it", "Tell them it is not worth being upset about", "Explain why you would handle it differently", "Agree that it is terrible even though you do not think so"], answer: 0, explanation: "Two people can experience the same thing differently. Dismissing and pretending are both failures." }, { question: "Does empathy require agreeing with someone?", options: ["No — you can understand a view without sharing it", "Yes, otherwise it is not real empathy", "Only when they are upset", "Only with close friends"], answer: 0, explanation: "Understanding and agreement are separate. Conflating them makes honest disagreement impossible." }, { question: "Someone snaps at you unexpectedly. What is the most useful first assumption?", options: ["Something may be going on that has nothing to do with you", "They have a problem with you", "They are a rude person", "You should snap back"], answer: 0, explanation: "Most out-of-character sharpness is about their day, not about you." }, { question: "A friend tells you they are struggling. What is the most empathetic response?", options: ["Ask what it has been like for them", "Tell them about someone who had it worse", "List things they could try", "Tell them they will be fine"], answer: 0, explanation: "Asking what it has been like invites their actual experience. The others replace it with yours." }, { question: "You and a friend went through the same event and remember it differently. What does that mean?", options: ["Different positions produce genuinely different experiences", "One of you is remembering it wrong", "One of you is being dishonest", "The event was unclear"], answer: 0, explanation: "Two honest people can experience one event in two ways. That is the point empathy exists for." }, { question: "What is the practical version of empathy in a conversation?", options: ["Asking what you cannot see instead of filling it in yourself", "Feeling what the other person feels", "Agreeing with whatever they say", "Sharing a similar experience of your own"], answer: 0, explanation: "Empathy is a question habit before it is a feeling." }, { question: "Someone tells you they found something hard that you found easy. What should you avoid saying?", options: ["“It is not that difficult”", "“What part was hardest?”", "“How did you get through it?”", "“That sounds frustrating”"], answer: 0, explanation: "Measuring someone's difficulty against your own ends the conversation and teaches them not to tell you things." }] },
    { title: "Halal Boundaries and Respect", why: "Knowing where your limits are, and respecting other people's, is what makes you safe to be around.", lesson: "Boundaries are not walls and they are not rejection. They are the lines that let a relationship stay healthy — what you will do, what you will not, what you are comfortable with, and what you are not. Two skills sit here. The first is saying no clearly and without drama, so people know where they stand. The second is accepting someone else's no the first time you hear it, which is the one most people are worse at. As a Muslim you also have limits that are already set for you, particularly around how men and women interact, and holding those calmly is far easier than trying to explain them mid-situation. Decide them in advance and they stop being awkward.", keyIdea: "Say no clearly, accept a no the first time, and decide your halal limits before you are in the moment.", example: "A group plan drifts somewhere you should not be. You say you will catch them afterwards, without a speech about why, and nobody has to be embarrassed.", actionPrompt: "Say a clear no to one thing today, or accept someone's no without pushing back.", actionHint: "No explanation is required. A clear short answer is more respectful than a long justification.", bonus: "Decide in advance what you will say next time a plan drifts somewhere you should not go.", quiz: [{ question: "A group plan moves somewhere you know you should not be. What is the strongest response?", options: ["Say you will catch them afterwards, without a speech", "Go along and stay quiet", "Explain in detail why it is wrong", "Make an excuse about being busy"], answer: 0, explanation: "A short clear answer keeps your limit and everyone's dignity. A lecture and a lie both cost more." }, { question: "You ask someone for something and they say no. What should happen next?", options: ["You accept it the first time", "You ask again in case they change their mind", "You ask why until you understand", "You accept it but mention it later"], answer: 0, explanation: "Accepting a no the first time is the harder half of this skill and the one people notice." }, { question: "When is the easiest time to decide where your halal limits are?", options: ["Before you are in the situation", "In the moment, based on how it feels", "Afterwards, when you can reflect", "When someone asks you directly"], answer: 0, explanation: "Decided in advance, a limit is simply held. Decided mid-situation, it becomes a negotiation." }, { question: "Someone respects your boundary but seems put out by it. What is the accurate reading?", options: ["They accepted it, which is what matters", "You should have explained more", "You were too harsh", "You should relax the boundary next time"], answer: 0, explanation: "A boundary that is kept is working, even when the other person would have preferred otherwise." }, { question: "Which is a clear no?", options: ["I am not going to do that", "I do not think I can, probably, sorry", "Maybe, let me see how I feel", "I would, but it is complicated"], answer: 0, explanation: "Clarity is the kindness here. Vagueness leaves people guessing and invites another ask." }, { question: "A friend keeps pushing past a limit you have stated twice. What now?", options: ["Say it once more plainly, and step back if it continues", "Give in to keep the friendship", "Cut them off without saying anything", "Assume they have not understood"], answer: 0, explanation: "One clear restatement, then distance. Repeated pushing is information about the friendship." }, { question: "How should you respond when someone tells you their own limit?", options: ["Take it at face value and adjust", "Ask them to justify it", "Test whether they really mean it", "Tell them you think it is unnecessary"], answer: 0, explanation: "You want your own limits taken at face value. The standard runs both ways." }, { question: "What makes boundaries different from rejecting someone?", options: ["They describe what you will do, not what you think of them", "There is no difference", "They are permanent", "They only apply to people you dislike"], answer: 0, explanation: "A limit is about the behaviour and the situation, which is why it can be held without hostility." }] },
    { title: "When You Disagree", why: "Disagreement handled badly ends friendships that had nothing actually wrong with them.", lesson: "Disagreeing is normal and survivable. What damages a relationship is not the disagreement but the way it is conducted: interrupting, attacking the person rather than the point, bringing up unrelated history, or telling other people instead of them. The useful sequence is simple — listen fully, say your view without insult, ask why they see it differently, and be willing to say “you're right” when they are. Sometimes the correct move is to pause and return to it later, which is not the same as avoiding it.", keyIdea: "Argue with the point, never the person, and be willing to be the one who was wrong.", example: "“I see it differently, and I want to understand why you don't” keeps a disagreement solvable. “You always do this” does not.", actionPrompt: "Think of a recent disagreement and rewrite what you said in a calmer, more respectful way.", actionHint: "Take out every sentence that describes the person rather than the problem.", bonus: "Apologise properly for one thing — name it, skip the excuse, and say what you will do differently.", quiz: [{ question: "You and a friend disagree strongly. What should you try first?", options: ["Listen to their reasoning and explain yours calmly", "Attack their character", "Tell other people they are wrong", "End the friendship immediately"], answer: 0, explanation: "Understanding their reasoning first is what makes the disagreement solvable rather than personal." }, { question: "Halfway through an argument you realise you are wrong. What is the strongest move?", options: ["Say so", "Keep arguing so you do not look foolish", "Change the subject", "Concede quietly without saying anything"], answer: 0, explanation: "Admitting it plainly costs a moment and buys a great deal of trust." }, { question: "Which of these turns a disagreement into a fight?", options: ["Describing the person instead of the problem", "Explaining why you see it differently", "Asking what they mean", "Saying you need to think about it"], answer: 0, explanation: "“You always…” and “you're the kind of person who…” move the argument from solvable to personal." }, { question: "An argument is getting heated and neither of you is listening. What is the strongest move?", options: ["Suggest returning to it later, and actually return to it", "Push on until it is resolved", "Walk away and never mention it again", "Let them win to end it"], answer: 0, explanation: "A pause is not avoidance, as long as you come back. Pushing on and abandoning are both worse." }, { question: "You need to apologise properly. What does that include?", options: ["Naming what you did, no excuses, and what you will do differently", "Saying “sorry if you were offended”", "Explaining why it was not really your fault", "Doing something nice instead of mentioning it"], answer: 0, explanation: "Naming the act and changing it is the apology. Everything else is managing your own discomfort." }, { question: "A friend says something in an argument that genuinely hurt. What is the strongest response?", options: ["Tell them it hurt, calmly, once", "Say something equally hurtful back", "Pretend it did not affect you", "Bring it up in every future argument"], answer: 0, explanation: "Naming it calmly gives them a chance to repair it. The alternatives either escalate or store it up." }, { question: "You disagree with a friend in front of other people. What is usually best?", options: ["Keep it brief, and continue privately if it matters", "Settle it fully there and then", "Ask the others who is right", "Drop it permanently"], answer: 0, explanation: "An audience makes both people defend positions rather than examine them." }, { question: "What does a disagreement usually mean about a friendship?", options: ["Very little — friendships that allow disagreement are usually the stronger ones", "That it is coming to an end", "That one person does not respect the other", "That you are not compatible"], answer: 0, explanation: "Being able to disagree safely is a sign of a healthy friendship, not a crack in one." }] },
    { title: "Choosing Good Friends", why: "The people you spend time with shape what feels normal to you.", lesson: "A good friendship has a recognisable shape: respect that goes both ways, honesty, encouragement, the ability to disagree without it becoming a crisis, and enough shared interest to have something to do. Judge it on repeated behaviour rather than a single bad day — everyone has those. But repeated patterns are worth noticing: someone who is only around when they need something, or who makes you smaller, is telling you something over time. Not everyone you meet needs to become a close friend, and that is a normal thing rather than a judgement on them.", keyIdea: "Judge friendships by repeated patterns, not by single incidents.", example: "A friend who is pleased when something goes well for you is showing you something more useful than one who is fun at parties.", actionPrompt: "Think about the people around you and write down the qualities you actually value in a friend.", actionHint: "Describe behaviour you have seen, not personality labels.", bonus: "Thank one person whose friendship has been good for you, and say specifically why.", quiz: [{ question: "A friend let you down badly once. What is the most reasonable response?", options: ["Look at whether it is part of a pattern before deciding anything", "End the friendship", "Assume it will never happen again", "Bring it up regularly from now on"], answer: 0, explanation: "Everyone has bad days. Patterns are informative; single incidents usually are not." }, { question: "Someone only contacts you when they need something, and this has happened many times. What does that tell you?", options: ["The pattern is worth taking seriously", "Nothing — people are busy", "They are a bad person", "You should confront them publicly"], answer: 0, explanation: "Repeated behaviour is real information, and it can be noticed without condemning anyone." }, { question: "Which is the strongest sign of a healthy friendship?", options: ["You can disagree without it becoming a crisis", "You never argue", "You agree about everything", "You spend all your time together"], answer: 0, explanation: "Safe disagreement is a sign of strength. Never arguing usually means something is being avoided." }, { question: "You get on well with someone but do not want a close friendship with them. Is that a problem?", options: ["No — not everyone you meet needs to become a close friend", "Yes, you should make more effort", "Yes, it means you are being unfriendly", "Only if they want to be closer"], answer: 0, explanation: "Friendly acquaintances are a normal and good part of life. Not every connection has to deepen." }, { question: "A friend makes you feel smaller whenever something goes well for you. What is worth doing?", options: ["Notice the pattern and consider how much time you give it", "Assume you are being oversensitive", "Stop telling them good news", "Confront them about their character"], answer: 0, explanation: "Noticing a pattern and adjusting is different from condemning someone. Hiding your news is not a fix." }, { question: "How should you evaluate whether a friendship is good for you?", options: ["By what repeatedly happens, over time", "By how much fun it is", "By how long you have known them", "By what other people say about them"], answer: 0, explanation: "Time and enjoyment are not the same as health. The pattern of behaviour is what tells you." }, { question: "Which of these is worth more in a friend?", options: ["Being genuinely pleased when things go well for you", "Being entertaining", "Being popular", "Always agreeing with you"], answer: 0, explanation: "Someone who is glad for you is rarer and more valuable than someone who is fun or agreeable." }, { question: "You realise a friendship has become one-sided. What is the strongest first step?", options: ["Say something honest about it and see what changes", "Withdraw quietly", "Match their effort exactly and keep score", "Complain to mutual friends"], answer: 0, explanation: "Naming it gives the friendship a chance to change. Scoring and withdrawing skip that chance." }] },
    { title: "Building Real Relationships", why: "Everything in this section only works when it is repeated over time with the same people.", lesson: "Strong relationships are not built in a conversation. They are built by many ordinary interactions in which you understood rather than assumed, listened rather than waited, kept what you said you would, told the truth kindly, respected a no, and came back after a disagreement. This day puts those together and aims them at one person. Choose someone real, do the whole sequence, and notice that none of the individual steps are difficult — the difficulty is only ever in doing them repeatedly rather than once.", keyIdea: "Relationships are built by repeating small reliable actions with the same person over time.", example: "One good conversation is pleasant. The same person, six conversations and one kept promise later, is a friendship.", actionPrompt: "Choose one person you want a stronger relationship with. Start a genuine conversation, ask something meaningful, listen, do one small kind thing afterwards, and follow through on something you said you would do.", actionHint: "Choose someone real and nearby, not the hardest possible case.", bonus: "Do the same sequence with the same person again next week, and notice what has changed.", quiz: [{ question: "You want to strengthen a relationship with someone specific. Where should you start?", options: ["One genuine conversation, then keep showing up", "One long, deep conversation", "Doing them a large favour", "Waiting for a natural opportunity"], answer: 0, explanation: "Depth comes from repetition. Grand gestures and waiting both skip the mechanism." }, { question: "You had a great conversation with someone last week and have not spoken since. What is the strongest move?", options: ["Follow up on something they told you", "Wait for them to get in touch", "Start a completely new topic", "Assume the moment has passed"], answer: 0, explanation: "Following up on something specific is what turns a good conversation into a relationship." }, { question: "Which combination actually builds a relationship over time?", options: ["Listening, keeping promises, and coming back after disagreements", "Being interesting, being available, and agreeing often", "Sharing everything early and staying in constant contact", "Never disagreeing and always being positive"], answer: 0, explanation: "The unglamorous three are what hold. The others create closeness with nothing underneath it." }, { question: "You did something kind for someone and they did not seem to notice. What is true?", options: ["It still counts — relationships accumulate quietly", "It was wasted", "You should mention it", "They do not value you"], answer: 0, explanation: "Most of what builds a relationship is not remarked on at the time." }, { question: "You and a close friend had a serious disagreement last month. What is the strongest thing to do now?", options: ["Reach out normally and let the relationship continue", "Wait for them to reach out first", "Bring the disagreement up again to settle it", "Keep the friendship at a distance from now on"], answer: 0, explanation: "Coming back after conflict is one of the strongest signals a relationship can carry." }, { question: "What is the hardest part of building relationships?", options: ["Doing the small things repeatedly rather than once", "Knowing what to say", "Meeting the right people", "Being interesting enough"], answer: 0, explanation: "None of the individual actions are difficult. Repetition is the entire difficulty." }, { question: "You are trying to strengthen several relationships at once and it feels like too much. What is more useful?", options: ["Choose one person and do it properly", "Spread your effort evenly across everyone", "Wait until you have more time", "Focus on whoever responds fastest"], answer: 0, explanation: "One relationship done properly teaches you more, and costs less, than several done thinly." }, { question: "Someone asks what you actually do differently after this section. What is the best answer?", options: ["Ask rather than assume, listen rather than wait, and do what you said you would", "Try to be a better person", "Be more social", "Care about people more"], answer: 0, explanation: "The useful answer is a set of actions. Intentions and attitudes do not change what happens." }] },
  ],
  [
    { title: "Sleep Is a Foundation", why: "Almost every other thing in this course gets harder when you are short of sleep, and easier when you are not.", lesson: "Sleep is not the reward you get after the productive day. It is the thing that decides whether tomorrow is productive at all: your patience, your concentration, your appetite, your ability to hold your tongue. Most people who want to sleep better focus on the moment of getting into bed, which is far too late. The two levers that actually work are a consistent wake time, which anchors everything else, and a wind-down that starts earlier than you think — including where your phone spends the night. Fajr, incidentally, is much easier to reach from a life that ends at a reasonable hour.", keyIdea: "A consistent wake time and an earlier wind-down beat anything you do at bedtime.", example: "You keep the same wake time even at weekends, and within two weeks you are falling asleep without deciding to.", actionPrompt: "Set a consistent wake time and begin winding down thirty minutes earlier than usual tonight.", actionHint: "Move the phone charger out of the bedroom. That single change does more than most sleep advice.", bonus: "Keep the same wake time for five days, including the weekend, and note what changes.", quiz: [{ question: "You want to fix your sleep. Which change does the most?", options: ["A consistent wake time, including weekends", "Going to bed earlier when you can", "Sleeping in at weekends to catch up", "Taking something to help you fall asleep"], answer: 0, explanation: "The wake time is the anchor. Everything else drifts around it." }, { question: "You are lying in bed unable to sleep and scrolling. What is the strongest move?", options: ["Put the phone in another room and get up if sleep does not come", "Keep scrolling until you feel tired", "Stay in bed and try harder to sleep", "Switch to something more relaxing on the phone"], answer: 0, explanation: "The phone in reach is the problem, and lying awake in bed for an hour teaches your body the wrong association." }, { question: "You had four hours of sleep and a full day ahead. What should you expect?", options: ["Worse patience, focus and judgement — so plan around it", "The same day with a bit more coffee", "No real difference if you are motivated", "A more productive day because of the urgency"], answer: 0, explanation: "Knowing which faculties are down lets you protect the decisions that matter." }, { question: "Which is the best-designed wind-down?", options: ["Screens away thirty minutes before, same order every night", "Whatever helps you relax that evening", "Going straight to bed when you feel tired", "A long routine you do when you have time"], answer: 0, explanation: "Early, consistent and short is what survives. Long routines get skipped on the nights they matter." }, { question: "You keep missing Fajr. Where is the real fix?", options: ["The previous evening", "The alarm", "Willpower in the morning", "Sleeping in the same clothes to save time"], answer: 0, explanation: "Fajr is decided the night before. Attacking the morning is attacking the symptom." }, { question: "A friend says they function fine on five hours. What is the accurate response?", options: ["Most people who believe that are measuring on impaired judgement", "They are probably right about themselves", "Everyone needs exactly eight hours", "They should try four and see"], answer: 0, explanation: "Reduced sleep degrades the faculty you would use to notice it, which is why the self-assessment is unreliable." }, { question: "You have one late night that cannot be avoided. What is the strongest recovery?", options: ["Keep the normal wake time and go to bed earlier the next night", "Sleep in as long as possible", "Nap for three hours in the afternoon", "Stay up later again to reset"], answer: 0, explanation: "Protecting the wake time keeps the anchor. Sleeping in moves it and costs the following night too." }, { question: "You have an important decision to make and you slept four hours. What is the strongest move?", options: ["Delay the decision until you have slept", "Make it now while it is fresh in your mind", "Ask someone else to decide it", "Make it and review it tomorrow"], answer: 0, explanation: "Judgement degrades first when sleep is short, and a delayed decision costs far less than a bad one." }] },
    { title: "Energy Is the Real Budget", why: "You do not have twenty-four usable hours; you have a few good ones, and where you spend them decides the day.", lesson: "Time management assumes every hour is worth the same, and no honest look at your own day supports that. There are hours when hard thinking is possible and hours when it simply is not, and they are fairly consistent from day to day. The useful move is to find your two or three best hours and stop spending them on email, messages and tidying — the tasks that feel productive and could have been done at four in the afternoon when you are useless anyway. Protect the good hours for the work that needs you at your sharpest. Everything else can have the rest.", keyIdea: "Find your two or three best hours and spend them on the work that actually needs you.", example: "You notice you think clearly from nine to eleven, so admin moves to the afternoon and the difficult work moves into the morning.", actionPrompt: "Identify your best two hours today and put your hardest task inside them.", actionHint: "You already know when they are. Look at when you last did something difficult well.", bonus: "Move one recurring low-value task out of your best hours permanently.", quiz: [{ question: "You think most clearly between nine and eleven. What should be happening then?", options: ["The hardest thing you have to do that day", "Clearing messages so the day is free", "Whatever is most urgent", "Planning the rest of the day"], answer: 0, explanation: "The hours that could do the hard work are being spent on work that any hour could have done." }, { question: "What is wrong with treating every hour as equivalent?", options: ["Your capacity varies predictably, so identical hours produce very different work", "Nothing, an hour is an hour", "It makes scheduling too complicated", "It works only for people with fixed jobs"], answer: 0, explanation: "Ignoring the variation is how the best hours get spent on the least demanding work." }, { question: "You have a demanding task and only a low-energy afternoon left. What is the strongest move?", options: ["Do the part of it that does not need your sharpest thinking", "Push through the hardest part anyway", "Postpone the whole thing", "Do something easier and feel productive"], answer: 0, explanation: "Most tasks contain both demanding and mechanical parts. Match the part to the hour you have." }, { question: "Which task genuinely belongs in a low-energy hour?", options: ["Replying to routine messages", "Writing something difficult", "Making an important decision", "Learning something new"], answer: 0, explanation: "Mechanical work is what those hours are for, and moving it there frees the good hours." }, { question: "You feel busy all day and finish nothing that mattered. What is most likely?", options: ["Your best hours went to low-value work", "You did not work long enough", "You need a better task list", "The tasks were too hard"], answer: 0, explanation: "Busyness usually means the capacity was spent, just not where it counted." }, { question: "Someone says they will do the hard thing once everything else is cleared. What is the accurate reply?", options: ["Everything else expands to fill the day, and the hard thing gets the worst hours", "That is a sensible order", "They should clear things faster", "The hard thing should be dropped"], answer: 0, explanation: "Clearing first is the most reliable way to guarantee the important work gets your leftovers." }, { question: "How would you find your own best hours?", options: ["Look at when you last did something difficult well", "Assume it is early morning", "Ask other people when theirs are", "Test every hour for a month"], answer: 0, explanation: "You already have the evidence. It does not need a study." }, { question: "What is the practical difference between managing time and managing energy?", options: ["One counts hours, the other matches work to capacity", "There is no difference", "Energy management means working less", "Time management is more disciplined"], answer: 0, explanation: "The same schedule can produce very different output depending on what sits where." }] },
    { title: "Food and Water, Honestly", why: "Most people do not need a diet; they need to notice what they are already doing.", lesson: "This is not about a plan, a restriction, or a list of forbidden foods. It is about accuracy. Most people underestimate what they eat between meals, drink far less water than they think, and then treat the resulting slump as a personality trait. Two changes carry most of the benefit: drink water before you reach for something else, and eat in a way that does not put you flat an hour later. Eating what is halal and eating with moderation is already the instruction; the practical version is simply not eating until you are heavy. Do not let this become another thing to feel bad about.", keyIdea: "Notice what you actually eat and drink. Water first, and stop before you are heavy.", example: "You realise the three o'clock crash follows the same lunch every time, and change one part of it.", actionPrompt: "Track honestly what you eat and drink today, and change one thing tomorrow.", actionHint: "Write it as you go. Reconstructing it in the evening loses exactly the things you want to see.", bonus: "Drink a glass of water before every meal for the rest of the week.", quiz: [{ question: "You crash at three o'clock every afternoon. What is the strongest first step?", options: ["Look at what you ate before it", "Have coffee at three", "Push through it", "Accept it as your natural rhythm"], answer: 0, explanation: "A crash that arrives at the same time daily has a cause upstream of it." }, { question: "Why record what you eat as you go rather than in the evening?", options: ["Reconstructing loses exactly the things you want to notice", "It is more accurate for calories", "It makes you eat less", "It is faster"], answer: 0, explanation: "The between-meal eating is the part that disappears from memory, and it is usually the finding." }, { question: "You feel tired and reach for something to eat. What does today suggest trying first?", options: ["Water", "A sugary snack for the quick lift", "Coffee", "A longer break"], answer: 0, explanation: "Thirst is regularly misread as hunger or fatigue, and the test costs nothing." }, { question: "Which change is most sustainable?", options: ["Stop eating before you feel heavy", "Cut out a whole food group", "Eat only at fixed times with no exceptions", "Follow a strict plan for a month"], answer: 0, explanation: "Moderation you can keep beats restriction you will abandon, and it is closer to the instruction anyway." }, { question: "You have eaten badly for three days. What is the useful response?", options: ["Eat normally at the next meal", "Skip meals to compensate", "Start a strict plan on Monday", "Decide the effort has failed"], answer: 0, explanation: "The next meal is the whole correction. Compensation and restarting both make the pattern worse." }, { question: "You skip breakfast and cannot concentrate by eleven. What is the useful conclusion?", options: ["The concentration problem has a cause you can change tomorrow", "You need more discipline", "You should drink more coffee", "Your concentration is naturally poor in mornings"], answer: 0, explanation: "A slump that tracks a specific input is a solvable problem rather than a fixed trait." }, { question: "Someone says they barely eat anything and cannot understand their energy levels. What is worth checking?", options: ["What they eat between meals, recorded as it happens", "Whether they are exercising enough", "Their sleep only", "Whether they should eat even less"], answer: 0, explanation: "Unrecorded eating is genuinely invisible, which is why the record rather than the estimate is the tool." }, { question: "How much water do most people drink relative to what they think?", options: ["Less", "About the same", "More", "It varies too much to say"], answer: 0, explanation: "The estimate runs high and the deficit shows up as tiredness that gets blamed on other things." }] },
    { title: "Move Every Day", why: "The point of movement here is not fitness; it is that a body that moves thinks better and sleeps better.", lesson: "You do not need a gym, a programme, or an hour. You need your body to move every day, at a level you would not describe as training. A brisk twenty-minute walk does more for your mood, your sleep and your concentration than a punishing session once a fortnight, because you will actually do it. If you want to train properly, train properly — but that is a separate ambition. What this day asks is the floor: daily, unglamorous, and small enough that a bad week does not remove it. Walking after Isha, or between Asr and Maghrib, costs almost nothing and fits an existing gap.", keyIdea: "Move every day at a level you will still do on a bad day. Daily beats intense.", example: "You walk for twenty minutes after Asr each day. It is not training, and it changes your evening completely.", actionPrompt: "Move deliberately for twenty minutes today, and pick the time you will repeat it.", actionHint: "Attach it to something fixed: after a prayer, after school, before dinner.", bonus: "Do it again tomorrow at the same time, and see whether the evening feels different.", quiz: [{ question: "You have twenty minutes and no equipment. What does today ask for?", options: ["A brisk walk", "A hard session to make it count", "Nothing, since twenty minutes is too short", "Stretching only"], answer: 0, explanation: "Daily and moderate is the target. The hard session is a different ambition." }, { question: "Which is more valuable for how you think and sleep?", options: ["Twenty minutes most days", "Ninety minutes once a fortnight", "An intense hour at the weekend", "Whatever you feel like doing"], answer: 0, explanation: "Regularity is what affects mood, sleep and concentration. Intensity in bursts mostly affects fitness." }, { question: "You missed three days. What is the strongest response?", options: ["Walk today", "Do a longer session to make up", "Restart properly next week", "Accept that the habit did not take"], answer: 0, explanation: "The return is the whole thing, and it should be the ordinary version rather than a compensating one." }, { question: "Where does daily movement fit best in a full day?", options: ["Attached to something already fixed", "Whenever a gap appears", "First thing, always", "Last thing, when everything is done"], answer: 0, explanation: "An existing fixed point removes the decision about when, which is what usually kills it." }, { question: "What is the honest relationship between this and training seriously?", options: ["This is the floor; training is a separate ambition on top of it", "They are the same thing", "Training makes this unnecessary", "You should not train until this is established"], answer: 0, explanation: "Setting the floor low and daily is what makes it survive. Ambition can sit on top of it." }, { question: "You feel too tired to move. What usually happens if you go anyway?", options: ["The tiredness often lifts once you have started", "It gets worse", "Nothing changes", "You should not go when tired"], answer: 0, explanation: "Fatigue from sitting and fatigue from exertion behave differently, and the first usually improves with movement." }, { question: "A friend says they will start when they can commit to five sessions a week. What is the accurate reply?", options: ["A daily twenty-minute walk starting today beats a plan that starts later", "That is a sensible commitment", "They should aim for six sessions", "They should wait until they have the time"], answer: 0, explanation: "The high threshold is exactly what has stopped them starting for months." }, { question: "Which measure tells you this is working?", options: ["You are still doing it in a month", "How far you walked", "How tired you were afterwards", "Whether anyone noticed"], answer: 0, explanation: "Durability is the measure for a floor habit. Distance and effort belong to a training goal." }] },
    { title: "Set Up the Space You Rest In", why: "You cannot recover properly in a room that is set up for stimulation.", lesson: "Earlier in the course you changed a space so that a good action became easier. This is the same principle aimed at the other end of the day: the place you sleep and recover. A bedroom that contains your work, your phone, your screen and your unfinished tasks is a room that keeps you alert, and no amount of discipline at midnight fixes a room that is arguing with you. Dark, quiet, cool, and free of the things that pull. This is small, physical, and one of the highest-return changes available — because it works every single night without needing you to decide anything.", keyIdea: "Set the room up for recovery, and it works every night without a decision.", example: "You move the charger to the hall and put the laundry chair out of sight. Nothing else changes and you fall asleep faster.", actionPrompt: "Change two things about where you sleep so that the room is set up for rest.", actionHint: "Darkness, quiet, temperature, and removing whatever pulls at your attention. Start with the phone.", bonus: "Keep the room that way for a week and see whether you fall asleep faster.", quiz: [{ question: "Your bedroom contains your desk, your phone and a pile of unfinished tasks. What is the effect?", options: ["The room keeps you alert when you need it to do the opposite", "No effect if you are tired enough", "It makes you more productive", "It only matters if the room is untidy"], answer: 0, explanation: "The room is set up for stimulation, and it is doing that job every night." }, { question: "Why is a physical change to the room stronger than a rule about bedtime?", options: ["It works every night without you deciding anything", "It is easier to remember", "Rules do not work at all", "It costs less"], answer: 0, explanation: "A rule requires a decision at the worst possible moment. A changed room does not." }, { question: "Which single change usually returns the most?", options: ["Moving the phone out of the room", "Buying better bedding", "Adding a lamp", "Rearranging the furniture"], answer: 0, explanation: "The phone is the strongest pull in the room and the easiest to remove." }, { question: "You cannot control the noise where you sleep. What is the strongest response?", options: ["Change what you can and mask what you cannot", "Accept that nothing will help", "Move rooms permanently", "Stay up until the noise stops"], answer: 0, explanation: "Partial control is still control, and the other factors are still available." }, { question: "How does this differ from the earlier lesson about your surroundings?", options: ["That one made a good action easier; this one makes recovery easier", "It is the same lesson", "This one is about tidiness", "That one was about work only"], answer: 0, explanation: "Same principle, opposite end of the day, and both work without ongoing effort." }, { question: "You change the room and sleep is no better after two nights. What now?", options: ["Give it a week before judging it", "Change it back", "Change everything else as well", "Conclude the room was not the problem"], answer: 0, explanation: "Sleep responds to a changed pattern over days, not immediately." }, { question: "Which is the strongest reason to keep work out of the bedroom?", options: ["The room stops being associated with stopping", "It looks untidy", "You will work less", "It is a common rule"], answer: 0, explanation: "The association is the mechanism, and it is built by repetition rather than intention." }, { question: "What makes this a high-return change?", options: ["It is small, physical, and repeats automatically every night", "It requires real discipline", "It is difficult to do", "It affects your whole day"], answer: 0, explanation: "One-off changes that keep paying without maintenance are the best value available." }] },
    { title: "Stack the Habits You Keep", why: "A habit that stands alone depends on you remembering; a habit attached to another one does not.", lesson: "You already know to set a habit small enough to survive a bad day. This is the next problem: keeping several of them running at once without turning your day into a checklist you resent. The answer is stacking. Attach each new habit to something that already happens without fail — after Fajr, after you put your bag down, after Maghrib — so that the existing action becomes the trigger. Then keep the total honest. Three small stacked habits that run for a year beat eight that run for nine days, and the point at which people fail is almost always the point at which they added the fourth.", keyIdea: "Attach each habit to a fixed existing action, and cap the total at three.", example: "After Fajr, half a page of Qur’an. After you put your bag down, twenty minutes of study. After Maghrib, the walk. Nothing needs remembering.", actionPrompt: "Attach your current habits to fixed existing actions, and cut the total to three.", actionHint: "Write them as after X, I do Y. If you cannot name X, the habit has no trigger yet.", bonus: "Run the same three for a week without adding a fourth.", quiz: [{ question: "You want a new habit to stick. What is the strongest way to schedule it?", options: ["Attach it to something that already happens without fail", "Set a reminder on your phone", "Do it whenever you have a free moment", "Do it at the same clock time each day"], answer: 0, explanation: "An existing action fires reliably. Reminders and clock times both depend on the day cooperating." }, { question: "You are running seven habits and keeping about three. What should you do?", options: ["Cut to three and run those properly", "Try harder to keep all seven", "Rotate which ones you do each day", "Add an eighth to build momentum"], answer: 0, explanation: "The failure point is almost always the number, and three that survive beat seven that do not." }, { question: "Which is a properly formed habit?", options: ["After Maghrib, I walk for twenty minutes", "I will walk more this week", "I walk when I have energy", "I aim to walk daily"], answer: 0, explanation: "Only the first names the trigger and the action, which is what makes it fire without remembering." }, { question: "You cannot think of an existing action to attach a habit to. What does that tell you?", options: ["It has no trigger yet, so it will depend on memory", "The habit is a bad idea", "You should do it first thing", "You should attach it to a reminder instead"], answer: 0, explanation: "No trigger means it runs on remembering, and remembering fails on the days that matter." }, { question: "Your stack breaks because one anchor changed — you stopped going somewhere. What now?", options: ["Re-anchor the habits to a new fixed action", "Drop the habits", "Keep trying to do them at the old time", "Wait until the old routine returns"], answer: 0, explanation: "The habits are fine; their trigger disappeared. Re-anchoring is a five-minute fix." }, { question: "How is this different from setting habits small?", options: ["Size decides whether it survives a bad day; the anchor decides whether it fires at all", "It is the same idea", "This one is about doing more", "Size no longer matters once stacked"], answer: 0, explanation: "They solve two different failure modes, and you need both." }, { question: "Which stack is best designed?", options: ["Three habits, each attached to a daily fixed point", "Six habits at set clock times", "Five habits done whenever possible", "One large habit done thoroughly"], answer: 0, explanation: "Three anchored habits is the shape that is still running in six months." }, { question: "You have kept three habits for a month and want to add one. What is the strongest move?", options: ["Add one, and watch whether the original three hold", "Add three more while momentum is high", "Do not add anything ever", "Replace one of the existing three"], answer: 0, explanation: "One at a time, with the existing stack as the test, is how the total grows without collapsing." }] },
    { title: "Screens Without the Drift", why: "The problem is rarely the screen you chose to open; it is the forty minutes after it that you did not choose.", lesson: "You already know to remove a distraction rather than resist it all day. This is the specific case, because screens are designed to be difficult here in a way a plate of biscuits is not. The apps are built to make the next thing arrive before you have decided to want it, so the useful question is not how much time you spend but how much of it you chose. Decide before you open: what am I here for, and what tells me I am finished? Then make the drift physically harder — notifications off, the app off the home screen, a timer that requires an actual decision to dismiss.", keyIdea: "Decide what you came for and what finished looks like, before you open it.", example: "You open it to reply to two messages, decide that is the whole visit, and close it — instead of surfacing thirty minutes later.", actionPrompt: "Before each screen session today, say what you came for and what finished looks like.", actionHint: "Notifications off and the app off your home screen. Both remove the unchosen opening.", bonus: "Count the sessions you opened without a reason at all.", quiz: [{ question: "You open an app to reply to one message. What does today ask you to decide first?", options: ["What you came for and what finished looks like", "How long you will allow yourself", "Whether you deserve the break", "What you will do afterwards"], answer: 0, explanation: "The exit condition is what prevents the drift. A time limit alone tends to be renegotiated." }, { question: "Which change most reduces the sessions you never chose to start?", options: ["Notifications off and the app off the home screen", "A daily time limit", "Deleting the app for a week", "Promising to check less often"], answer: 0, explanation: "Most unchosen openings are triggered by a notification or a habit of tapping the same spot." }, { question: "Why is a screen harder to manage than most other distractions?", options: ["The next thing arrives before you have decided to want it", "It is more enjoyable", "It is always available", "People need it for work"], answer: 0, explanation: "The design supplies the next impulse, which is why deciding the exit in advance matters more here." }, { question: "You set a thirty-minute limit and dismiss the warning every time. What is wrong?", options: ["The limit is not connected to a decision, so dismissing it is automatic", "Thirty minutes is too short", "You need more willpower", "Limits never work"], answer: 0, explanation: "A warning you can wave away becomes part of the drift. The exit condition has to be something you defined." }, { question: "What is the more useful measure of a screen session?", options: ["How much of it you chose", "How long it lasted", "What you watched", "Whether you enjoyed it"], answer: 0, explanation: "Twenty chosen minutes and twenty drifted minutes are not the same thing, and only one is a problem." }, { question: "You need the device for work, so you cannot remove it. What is the strongest move?", options: ["Remove the specific apps and alerts rather than the device", "Work without it", "Accept the distraction as unavoidable", "Rely on willpower during work"], answer: 0, explanation: "When the device is required, removal moves down a level to the particular sources." }, { question: "You have drifted for forty minutes and notice. What is the useful response?", options: ["Stop now and note what started it", "Finish the session since it is already lost", "Set a stricter rule for tomorrow", "Feel bad about the time"], answer: 0, explanation: "Stopping mid-drift is available at any moment, and the trigger is the information worth keeping." }, { question: "How does this connect to the earlier lesson on removing distractions?", options: ["Same principle, applied to the hardest case", "It contradicts it", "This one is about time limits instead", "That one was about work only"], answer: 0, explanation: "Removal still beats resistance; screens simply require it at the level of apps and alerts." }] },
    { title: "Recover Before You Break", why: "Rest taken deliberately is a fraction of the cost of rest taken by collapse.", lesson: "There are two ways to stop. One is planned, short and chosen — a real break, a proper day off, an early night before you need it. The other is involuntary: you get ill, or you burn out, or you lose a fortnight to being unable to face anything. The second is far more expensive and it is what happens when you treat the first as a luxury. Recovery is not the opposite of discipline; it is part of the same system, because a system that cannot absorb a hard week is a system that will break in one. Take the break before the evidence says you need it.", keyIdea: "Plan recovery before you need it. Collapse is the expensive version of the same thing.", example: "You take Sunday afternoon off deliberately, and the week after is fine. The alternative is the fortnight you lost last time.", actionPrompt: "Schedule one real break this week and take it before you feel you have earned it.", actionHint: "A real break is not a different screen. Decide what it actually is beforehand.", bonus: "Take an early night tonight, before there is a reason to.", quiz: [{ question: "You have worked hard for two weeks and feel fine. What does today suggest?", options: ["Take the planned break now, before it is needed", "Keep going while the momentum lasts", "Wait until you feel tired", "Take a break only if the work allows"], answer: 0, explanation: "Planned recovery is cheap. The involuntary kind arrives at the worst possible time and costs much more." }, { question: "Which is a real break?", options: ["Something genuinely different from the work, decided in advance", "Scrolling on your phone", "Doing lighter work", "Answering messages"], answer: 0, explanation: "A different screen is not recovery. Deciding beforehand is what stops the break dissolving." }, { question: "You lost a fortnight to burnout last time. What is the useful reading?", options: ["The rest was taken involuntarily instead of deliberately", "You are not resilient enough", "You should work less permanently", "It was unavoidable"], answer: 0, explanation: "The body takes the rest either way. The only variable is whether you chose when." }, { question: "Is recovery in tension with discipline?", options: ["No — a system that cannot absorb a hard week will break in one", "Yes, it is the opposite of discipline", "Only for people who are not committed", "Yes, but it is necessary anyway"], answer: 0, explanation: "Recovery is a component of a durable system, not a concession made against it." }, { question: "You are ill and were due to do your habits today. What is the strongest response?", options: ["Rest, and return to the smallest version tomorrow", "Push through as normal", "Abandon the habits for the week", "Do double when you recover"], answer: 0, explanation: "Illness is the case the minimum version exists for, and pushing through extends the illness." }, { question: "Which pattern is most likely to end in collapse?", options: ["Treating breaks as something you must earn", "Taking a scheduled break each week", "Stopping when a task is finished", "Sleeping consistently"], answer: 0, explanation: "The earned-break rule guarantees you only rest after the damage, which is the expensive order." }, { question: "What is the strongest argument for taking the break early?", options: ["It costs a few hours instead of a few weeks", "It feels better", "It makes you more disciplined", "Other people will respect it"], answer: 0, explanation: "The comparison is not break against no break. It is a small planned cost against a large unplanned one." }, { question: "How should a break be scheduled?", options: ["In advance, at a fixed point", "Whenever there is a gap", "After the current project ends", "When you notice you need one"], answer: 0, explanation: "A break with no fixed point is one that keeps being deferred until it is taken for you." }] },
    { title: "Steady Beats Heroic", why: "The pace you can hold for a year matters more than the pace you can hold for a week.", lesson: "Earlier you learned never to miss twice — the rule that protects a habit from one bad day. This is the larger version: choosing a load you can carry across months rather than one that looks impressive across a fortnight. The pattern to watch for is the sprint-and-crash: three enormous weeks, then a month of nothing, then guilt, then another enormous week. It produces less than a steady moderate pace and it feels far worse. Set the level at what you could still be doing in six months, and let the good weeks be a bonus rather than the standard you then fail to meet.", keyIdea: "Set the pace at what you could still hold in six months. Let good weeks be a bonus, not the baseline.", example: "You settle at forty minutes a day rather than three-hour sessions, and by month four you are far ahead of where the sprints ever got you.", actionPrompt: "Set a weekly load you could still carry in six months, and hold it this week.", actionHint: "If you would dread it in a bad week, it is set too high.", bonus: "Look back at your last sprint and count what the following month actually produced.", quiz: [{ question: "You have done three enormous weeks and then nothing for a month. What is the pattern?", options: ["A sprint and crash, which produces less than a steady pace", "Bad luck", "Evidence that you need more discipline", "A normal and effective rhythm"], answer: 0, explanation: "The crash is part of the sprint, and the total across both is usually lower than steady work." }, { question: "How should you set the level?", options: ["At what you could still be doing in six months", "At what you can manage this week", "At the most you have ever done", "At what other people are doing"], answer: 0, explanation: "The six-month test is the one that predicts whether the pace survives contact with a difficult month." }, { question: "You have a week where you can do far more than usual. What should you do?", options: ["Do more, and keep the baseline where it is", "Raise the baseline to match", "Stick rigidly to the baseline", "Take the extra capacity as a sign to sprint"], answer: 0, explanation: "Treating the exceptional week as the new standard is exactly how the crash gets built." }, { question: "How does this differ from never miss twice?", options: ["That protects a habit from one bad day; this sets the load across months", "It is the same rule", "This one is stricter", "That one applies only to small habits"], answer: 0, explanation: "One is about the gap; this is about the level. Both are needed for something that lasts." }, { question: "A friend is doing four-hour sessions and says you are not serious enough. What is the accurate reply?", options: ["The comparison worth making is what each of you is doing in six months", "They are right", "Four hours is always unsustainable", "Intensity does not matter at all"], answer: 0, explanation: "Intensity is not the measure; total work across time is, and that is decided by durability." }, { question: "You dread the week ahead when you look at the load. What does that indicate?", options: ["It is set too high", "You need more motivation", "It is set correctly and will build character", "You should do it in fewer sessions"], answer: 0, explanation: "Dread is a reliable signal about durability, and it arrives before the collapse does." }, { question: "Which produces more over six months?", options: ["Forty minutes daily", "Three hours twice a week when motivated", "A full day once a month", "Two intense weeks each quarter"], answer: 0, explanation: "The daily figure accumulates and survives interruptions. The others depend on conditions being right." }, { question: "What is the strongest reason to keep a good week from becoming the new baseline?", options: ["The baseline has to survive your worst week, not your best", "Good weeks are rare", "It would be too tiring", "Consistency means never varying"], answer: 0, explanation: "A baseline set by a good week fails the moment conditions return to normal." }] },
    { title: "Build Your Own Routine", why: "Ten days of separate advice is worth much less than one routine you actually follow.", lesson: "You have looked at sleep, energy, food and water, movement, the room you rest in, stacking habits, screens, recovery and pace. Held separately they are nine things to remember. The work now is to compress them into one written routine that fits your real life — the life with school or work in it, with the prayer times fixed in place, with the commitments you did not choose. Write it down. Keep it short enough to read in ten seconds. Then treat it as a draft, because the first version of anyone's routine is wrong and the second one, written after a week of evidence, is usually right.", keyIdea: "Write one short routine that fits your real week. Treat the first version as a draft.", example: "Yours ends up as six lines: wake time, Fajr and half a page, the walk after Asr, screens off at nine, and the same wake time on Saturday.", actionPrompt: "Write your routine as a short list, built around the prayer times and your fixed commitments.", actionHint: "Ten seconds to read. If it is longer than that, it is a plan rather than a routine.", bonus: "Follow it for a week, then rewrite it once using what actually happened.", quiz: [{ question: "You have written a routine with fourteen items. What is the problem?", options: ["It is a plan rather than a routine, and it will not survive a busy week", "Nothing, thorough is better", "It needs to be more detailed", "It should be organised by category"], answer: 0, explanation: "Short enough to read in ten seconds is the test. Length is what makes routines get abandoned." }, { question: "What should the routine be built around?", options: ["The prayer times and the commitments you did not choose", "The ideal version of your day", "What you would like to be doing", "What worked for someone else"], answer: 0, explanation: "Fixed points are the only reliable structure available. A routine that ignores them is fiction." }, { question: "Your first routine falls apart after four days. What is the correct response?", options: ["Rewrite it using what actually happened", "Try harder to follow it", "Abandon the idea of a routine", "Write a stricter version"], answer: 0, explanation: "The first draft is expected to be wrong. The evidence from four days is what makes the second one work." }, { question: "Which is a well-formed routine line?", options: ["After Asr, walk for twenty minutes", "Exercise regularly", "Be more consistent with health", "Try to sleep earlier"], answer: 0, explanation: "Only the first has a trigger, an action and a size, which is what makes it something you can follow." }, { question: "You have a week where the routine is impossible — travel, exams, illness. What now?", options: ["Keep the minimum versions and resume fully afterwards", "Abandon it for the week", "Force the full routine anyway", "Rewrite it entirely for that week"], answer: 0, explanation: "The minimum versions are what the disrupted week is for. Abandoning and forcing both cost more." }, { question: "What is the point of compressing ten days into one routine?", options: ["Nine things to remember becomes one thing to follow", "It proves you learned the material", "It saves time", "It makes the section feel complete"], answer: 0, explanation: "The compression is the deliverable. Separate advice does not survive contact with an ordinary week." }, { question: "Which part of the routine is most likely to be wrong in the first draft?", options: ["The timing of things, because you guessed at your real day", "The number of items", "The order", "The wording"], answer: 0, explanation: "Guessed timings are where drafts usually break, and a week of evidence corrects them quickly." }, { question: "How will you know the routine is working?", options: ["You are still following most of it in a month", "You followed it perfectly this week", "It covers all ten lessons", "It feels satisfying to read"], answer: 0, explanation: "Durability is the measure, and a month is long enough for a normal disruption to have tested it." }] },
  ],
  [
    { title: "Learn It by Doing It", why: "You cannot read your way to a skill; at some point the thing has to be attempted badly.", lesson: "There is a comfortable stage before any skill where you watch, read and plan, and it feels like progress because you are learning facts. It is not progress, because a skill is a thing your hands and judgement do, and neither of those improve from watching. The switch is simple and uncomfortable: start making the thing at the point where you still do not know how. You will produce something poor. That poor thing teaches you more in an hour than another week of tutorials, because it tells you specifically what you cannot do yet — which is information no video can give you.", keyIdea: "Attempt the thing before you feel qualified. The bad first attempt is the lesson.", example: "You have watched eleven hours of tutorials and built nothing. You build one small broken thing and learn more in an afternoon.", actionPrompt: "Take a skill you have only read about and make the smallest real thing with it today.", actionHint: "It should be small enough to finish today and real enough to be shown to someone.", bonus: "Write down the three things your bad first attempt revealed that you could not have learned by watching.", quiz: [{ question: "You have watched eleven hours of tutorials on something and built nothing. What is the strongest next step?", options: ["Build the smallest real version today", "Watch a more advanced series", "Take notes on what you have watched", "Find a better course"], answer: 0, explanation: "The gap is not knowledge. Another course produces more of exactly what you already have." }, { question: "Your first attempt is bad. What is the accurate reading?", options: ["It just told you specifically what you cannot do yet", "You started too early", "You need more theory first", "You are not suited to this"], answer: 0, explanation: "A specific list of your own gaps is the most valuable output available, and only building produces it." }, { question: "Why does watching feel like progress when it is not?", options: ["You are learning facts, and a skill is not made of facts", "It is not enjoyable enough", "The material is usually wrong", "You forget it too quickly"], answer: 0, explanation: "Facts accumulate visibly. Judgement and technique only move when you attempt the thing." }, { question: "How small should the first real attempt be?", options: ["Small enough to finish today", "Large enough to be impressive", "As large as your ambition for the skill", "Whatever the tutorial builds"], answer: 0, explanation: "Finished today means you get the feedback today. Anything longer delays the only useful part." }, { question: "Someone says they will start once they understand it properly. What is the accurate reply?", options: ["Understanding properly comes after the first attempt, not before", "That is a sensible order", "They should read one more book first", "They will never understand it properly"], answer: 0, explanation: "The sequence is inverted. Attempting is what generates the understanding they are waiting for." }, { question: "You get stuck halfway through the first attempt. What is the strongest move?", options: ["Look up that specific problem, then carry on", "Go back to the beginning of the course", "Abandon it and pick an easier skill", "Watch a full tutorial on the whole topic"], answer: 0, explanation: "A targeted lookup answers the actual gap. Returning to general material is how you end up back in the comfortable stage." }, { question: "Which produces more skill in a week?", options: ["Three bad attempts at the real thing", "Twenty hours of well-chosen tutorials", "A detailed plan for a large project", "Reading the definitive book"], answer: 0, explanation: "Attempts generate the feedback that turns information into ability." }, { question: "What is the honest role of tutorials once you have started building?", options: ["Answering the specific questions your attempts raise", "Providing the main learning", "Replacing the need to build", "Nothing, they become useless"], answer: 0, explanation: "They become far more useful once you have a real problem to bring to them." }] },
    { title: "Choose One Useful Skill", why: "A skill chosen deliberately and practised for a year beats five picked up and dropped.", lesson: "Most people never choose. They drift toward whatever is nearby, get a shallow layer of several things, and end up able to do none of them to a level anyone would pay for or rely on. Choosing means picking one, on purpose, with a reason. Two questions make the choice honest: does anyone actually need this done, and would you still be interested in it in a year when it stops being new? The second one matters because every skill has a boring middle. Write the choice down, because an unwritten choice is not a choice — it is a preference you will revise the moment something shinier appears.", keyIdea: "Pick one skill on purpose: something people need, that you would still want in a year.", example: "You stop half-learning three things and commit to one for six months. By month three you are past the stage where most people quit.", actionPrompt: "Choose one skill, write down why you chose it, and name what you will make with it first.", actionHint: "Test it against both questions: does anyone need it, and will you still want it when it gets boring?", bonus: "Tell someone what you chose, so it exists outside your own head.", quiz: [{ question: "You are half-learning three skills at once. What is the strongest move?", options: ["Choose one deliberately and put the others down for now", "Continue with all three", "Add a fourth to find what fits", "Alternate between them weekly"], answer: 0, explanation: "Shallow layers of several skills leave you unable to do any of them to a level that counts." }, { question: "Which question makes the choice honest?", options: ["Would you still want this in a year when it stops being new", "Which one is most popular", "Which one is easiest to start", "Which one impresses people most"], answer: 0, explanation: "Every skill has a boring middle, and the choice has to survive it." }, { question: "Why write the choice down?", options: ["An unwritten choice gets revised the moment something shinier appears", "It looks more serious", "So you can show other people", "It helps you remember what you picked"], answer: 0, explanation: "Writing converts a preference into a commitment you can be held to." }, { question: "What does does anyone need this done actually test?", options: ["Whether the skill connects to something outside your own interest", "Whether it will make money", "Whether it is difficult", "Whether it is respected"], answer: 0, explanation: "A skill nobody needs can still be worth learning, but knowing which kind you picked changes how you use it." }, { question: "You chose a skill and three months in you are bored. What is the accurate reading?", options: ["You have reached the boring middle, which everyone reaches", "You chose wrong", "You should switch to something more interesting", "You are not suited to it"], answer: 0, explanation: "The boring middle is where most people quit, which is exactly why the year question was asked at the start." }, { question: "You genuinely picked the wrong skill and know it after a month. What now?", options: ["Change deliberately, and write down the new reason", "Stick with it out of principle", "Go back to doing several at once", "Wait a year before deciding"], answer: 0, explanation: "A deliberate change is not the same as drifting. The written reason is what keeps it honest." }, { question: "Which is a well-formed choice?", options: ["Learn to build simple websites, because people around me need them and I still want it in a year", "Get better at computers", "Learn whatever is most in demand", "Try a few things and see what sticks"], answer: 0, explanation: "A real choice names the skill, the reason and the durability test." }, { question: "What should follow the choice immediately?", options: ["Naming the first thing you will make with it", "Buying the best course available", "Setting a long-term target", "Telling everyone about it"], answer: 0, explanation: "A named first artefact turns the choice into work that starts this week." }] },
    { title: "Break It Into Pieces", why: "A project you cannot start is almost always a project you have not broken down far enough.", lesson: "Large things are not built; small things are built and then joined. When something feels impossible to begin, the real problem is usually that it is still one undifferentiated lump in your head. Breaking it down means writing the parts until every single one is small enough that you could do it in a sitting and you know exactly what doing it looks like. That last test is the important one. If a piece still makes you hesitate, it is not a piece yet — it is two or three pieces wearing a coat, and it needs breaking again.", keyIdea: "Break it down until every piece is one sitting and you know exactly what to do.", example: "Build a website becomes: sketch the pages, write the text for the first one, make it appear in a browser, then the next page.", actionPrompt: "Take something you want to build and break it into pieces that are each one sitting long.", actionHint: "The test: if a piece still makes you hesitate, it is not a piece yet. Break it again.", bonus: "Do the first piece today, before you break the rest down any further.", quiz: [{ question: "A project feels impossible to start. What is usually the actual problem?", options: ["It has not been broken down far enough", "You lack motivation", "It is genuinely beyond your ability", "You do not have enough time"], answer: 0, explanation: "Undifferentiated lumps cannot be started. Pieces can." }, { question: "What is the test for whether a piece is small enough?", options: ["You could do it in one sitting and you know exactly what to do", "It takes under an hour", "It sounds simple", "You have done something similar before"], answer: 0, explanation: "Knowing exactly what to do is the operative half. Plenty of short tasks are still undefined." }, { question: "A piece on your list still makes you hesitate. What does that mean?", options: ["It is two or three pieces, and needs breaking again", "You should do it first to get it over with", "You need more information about the project", "It is the hardest part and requires motivation"], answer: 0, explanation: "Hesitation is a reliable signal of hidden structure inside a task." }, { question: "Which is properly broken down?", options: ["Write the text for the home page", "Build the website", "Sort out the design", "Get the site working"], answer: 0, explanation: "Only the first names a single action you could sit down and complete." }, { question: "You have broken it into forty pieces and feel overwhelmed by the list. What is the strongest response?", options: ["Do the first one today and stop looking at the rest", "Break them down further", "Reduce the scope of the project", "Reorganise the list by category"], answer: 0, explanation: "The list is a map, not a demand. One piece today is what turns it into progress." }, { question: "When should you break down the remaining pieces?", options: ["After you have done the first one and know more", "All at once, before starting", "Only when you reach each one", "Never — plan as you go"], answer: 0, explanation: "The first piece teaches you things that change how the rest should be split." }, { question: "What is the relationship between this and the earlier lesson on avoided tasks?", options: ["Same mechanism: an undefined task cannot be started", "They are unrelated", "This one is about large projects only", "That one was about fear"], answer: 0, explanation: "Both come down to definition. This applies it to something you want to do rather than something you dread." }, { question: "Someone says they will plan the whole thing properly before starting. What is the accurate reply?", options: ["The first piece will change the plan, so do it early", "That is the disciplined approach", "Planning is a waste of time", "They should plan for a fixed period then start"], answer: 0, explanation: "Plans made with no contact with the work are guesses, and the first piece is the cheapest way to test them." }] },
    { title: "Rebuild Something That Exists", why: "Copying a finished thing on purpose teaches you more than inventing a worse one from scratch.", lesson: "There is a stage where original ideas are the wrong goal. Take something that already works — a page, a tool, a dish, an essay, a piece of furniture — and rebuild it yourself, deliberately, as closely as you can. You will hit every decision the original maker had to make, and you will discover that the thing you thought was simple contains twenty choices you never noticed. This is not plagiarism; it is practice, and it is how most crafts have been taught for centuries. Rebuild it, keep it to yourself or credit it plainly, and take the technique into your own work afterwards.", keyIdea: "Rebuild something that already works. You will meet every decision its maker made.", example: "You rebuild a page you admire, and discover that the spacing you never noticed is doing most of the work.", actionPrompt: "Pick something small that already works well and rebuild it as closely as you can.", actionHint: "Choose something you could finish. The aim is the decisions inside it, not the size of it.", bonus: "List three choices the original maker made that you had never noticed before.", quiz: [{ question: "You want to improve quickly at something. What does today suggest?", options: ["Rebuild something that already works, as closely as you can", "Invent something original", "Study the theory behind it", "Find a mentor first"], answer: 0, explanation: "Copying deliberately surfaces every decision the maker made, which invention alone will not." }, { question: "Is this plagiarism?", options: ["No — it is practice, provided you do not pass it off as your own work", "Yes, always", "Only if the original is well known", "Only if you show it to anyone"], answer: 0, explanation: "Rebuilding to learn is how crafts have been taught for centuries. Presenting it as original would be the problem." }, { question: "You rebuild something and it turns out to be far harder than expected. What have you learned?", options: ["That the thing contained decisions you could not see from outside", "That you are not skilled enough yet", "That the original was badly made", "That you chose something too advanced"], answer: 0, explanation: "Invisible complexity is exactly what the exercise is designed to reveal." }, { question: "What should you take away from the rebuild?", options: ["The specific techniques, to use in your own work", "A finished piece you can show as yours", "Confidence that you can copy things", "A list of what the original did wrong"], answer: 0, explanation: "The techniques transfer. The artefact itself was never the point." }, { question: "Which is the best choice to rebuild?", options: ["Something small that works well and you could finish", "The most impressive thing you can find", "Something you think is badly made", "Something nobody has rebuilt before"], answer: 0, explanation: "Finishing is what delivers the lesson, and quality in the original is what makes the decisions worth meeting." }, { question: "When is this exercise the wrong approach?", options: ["When you have already built several things and need your own problems", "When you are a beginner", "When the skill is technical", "When you have limited time"], answer: 0, explanation: "It is a stage. Once you have real problems of your own, those teach more." }, { question: "You cannot work out how one part of the original was done. What is the strongest move?", options: ["Try three ways and compare them to the original", "Give up on that part", "Ask the original maker", "Skip it and finish the rest"], answer: 0, explanation: "Attempting and comparing is the exercise working exactly as intended." }, { question: "What does this teach that inventing from scratch does not?", options: ["The decisions inside work that is already good", "How to be creative", "How to finish things", "How to work quickly"], answer: 0, explanation: "Your own first attempts contain your own limited set of decisions. Someone else's good work contains better ones." }] },
    { title: "The Ugly First Version", why: "The purpose of the first version is not to be good; it is to exist so that it can be judged.", lesson: "A prototype is the cheapest possible thing that lets you find out whether the idea works. It is meant to be crude — drawn on paper, held together badly, missing most of what the finished thing would have. This is difficult for people who care about their work, because an ugly version feels like a statement about their ability. It is not. It is a question, asked in the cheapest available currency, and the answer arrives far sooner than it would if you spent three months making it properly first. Build the ugly one. Show it to someone. Then decide whether the real one is worth building.", keyIdea: "Build the cheapest version that answers the question, and let it be ugly.", example: "Instead of three months building the app, you draw the five screens on paper and show them to four people. Two of them are confused by the same screen.", actionPrompt: "Build the crudest possible version of your idea today and show it to one person.", actionHint: "Paper, cardboard, a rough sketch, a single broken page. Cheap is the requirement.", bonus: "Show it to a second person and see whether they get confused in the same place.", quiz: [{ question: "You have an idea for something useful. What should happen before you spend months building it?", options: ["Build the crudest version that answers the question, and show it to someone", "Plan it in full detail", "Learn the tools properly first", "Check nobody has done it already"], answer: 0, explanation: "The cheap version answers the question in days rather than months, and the answer often changes the plan." }, { question: "Your prototype looks bad and you are embarrassed to show it. What is the accurate reading?", options: ["It is a question, not a statement about your ability", "You should improve it before showing it", "You should only show it to close friends", "The embarrassment means it is not ready"], answer: 0, explanation: "Polishing before testing is how people spend three months answering a question that paper could have answered." }, { question: "Two people are confused by the same part of your prototype. What does that tell you?", options: ["That part needs to change before you build the real thing", "They did not look carefully", "You explained it badly", "Prototypes always confuse people"], answer: 0, explanation: "A repeated confusion is the single most valuable output of the exercise." }, { question: "Which is a well-chosen prototype for an app idea?", options: ["The five screens drawn on paper", "A working version of the main feature", "A detailed written specification", "A polished design of one screen"], answer: 0, explanation: "Paper answers the question at almost no cost. Anything built is already more expensive than it needs to be." }, { question: "Your prototype shows the idea does not work. What have you gained?", options: ["The months you would have spent building it", "Nothing, the effort was wasted", "Evidence that you should try harder", "A reason to give up on making things"], answer: 0, explanation: "A cheap negative answer is the highest-value result a prototype can produce." }, { question: "How much should the prototype be able to do?", options: ["Only enough to answer the one question you have", "Everything the finished thing would do", "Enough to be genuinely useful", "As much as you can manage in a week"], answer: 0, explanation: "Scope creep in a prototype removes the reason for building one." }, { question: "When is it right to stop prototyping and build properly?", options: ["When the question has been answered and the answer was yes", "After a fixed number of prototypes", "When the prototype looks good enough", "When you are tired of prototyping"], answer: 0, explanation: "The prototype exists to answer a question. Once answered, its job is finished." }, { question: "What is the relationship between this and the draft you allowed yourself earlier in the course?", options: ["Same principle: a rough version exists so it can be judged and improved", "They are unrelated", "This one applies only to physical objects", "A prototype must be more finished than a draft"], answer: 0, explanation: "Both defeat the same instinct, which is to hide the work until it is good." }] },
    { title: "Find the Actual Problem", why: "Most time lost to a problem is spent fixing things that were never the cause.", lesson: "When something breaks, the instinct is to start changing things, and it is expensive. The disciplined method is slower for ten minutes and much faster overall: describe exactly what is happening, work out what would have to be true for that to occur, and then test the cheapest of those possibilities first. Change one thing at a time, because two changes at once tell you nothing about which one mattered. And check the assumption you have not questioned — the thing you are certain about is where the problem usually is, precisely because you have not looked there.", keyIdea: "Describe it exactly, list what could cause it, test the cheapest one, change one thing at a time.", example: "You spend an hour rewriting the wrong section before checking whether the file was even being loaded. It was not.", actionPrompt: "Take something that is not working and find the actual cause before changing anything.", actionHint: "Write down what you are certain about. That list is where the problem usually is.", bonus: "Note how long the diagnosis took compared with the fix.", quiz: [{ question: "Something has broken and you do not know why. What is the strongest first move?", options: ["Describe exactly what is happening before changing anything", "Start trying likely fixes", "Undo your most recent change", "Ask someone who knows more"], answer: 0, explanation: "An accurate description narrows the possibilities more than an hour of trial and error will." }, { question: "You change three things and it works. What do you now know?", options: ["Almost nothing about which change mattered", "That all three were necessary", "That the problem is solved permanently", "That your approach was efficient"], answer: 0, explanation: "One change at a time is what turns a fix into knowledge you can reuse." }, { question: "Where is the problem most often found?", options: ["In the thing you are certain about and have not checked", "In the most complicated part", "In the newest part", "In the part you understand least"], answer: 0, explanation: "Certainty is exactly what stops you looking, which is why the assumption is such a common hiding place." }, { question: "Which possibility should you test first?", options: ["The cheapest one to test", "The most likely one", "The most serious one", "The one you can fix fastest"], answer: 0, explanation: "Cost of testing, not likelihood, is what makes the search efficient early on." }, { question: "You have been trying fixes for an hour with no progress. What is the strongest move?", options: ["Stop and describe the problem precisely, from the beginning", "Keep trying, you are probably close", "Rebuild the whole thing", "Take a break and come back tomorrow"], answer: 0, explanation: "An hour of unstructured attempts usually means the problem was never accurately stated." }, { question: "What does it mean when a fix works but you do not know why?", options: ["The problem may still be there and will return", "It is solved, so it does not matter", "You should document it as solved", "You got lucky and should move on"], answer: 0, explanation: "An unexplained fix is a problem waiting to recur in a form you will not recognise." }, { question: "Which description is diagnostically useful?", options: ["It fails only when the file is empty", "It does not work", "Something is wrong with the code", "It broke after I changed things"], answer: 0, explanation: "A description that names the condition has already halved the search." }, { question: "How does this apply outside technical work?", options: ["Any recurring problem has a cause worth isolating before acting", "It does not apply outside technical work", "Only to mechanical things", "Only to problems you caused yourself"], answer: 0, explanation: "The method is general: describe, hypothesise, test cheaply, change one thing." }] },
    { title: "Change One Thing, Then Test", why: "Things get good by being improved repeatedly, not by being got right at the start.", lesson: "Nobody makes a good version first. What separates work that gets good from work that stays mediocre is the loop: make it, show it, find the weakest part, change that one thing, look again. The discipline is in changing one thing at a time and actually looking afterwards, because the common failure is to rewrite everything at once and never know what helped. Iteration also has an end — at some point the changes stop improving it and start just changing it, and recognising that moment is part of the skill.", keyIdea: "Improve in small loops: weakest part, one change, look again.", example: "Your third version is better than your first, and you can name exactly which four changes did it.", actionPrompt: "Take something you have made and run one full loop: find the weakest part, change it, look again.", actionHint: "One change, then look. Two changes at once and you will not know which one worked.", bonus: "Run a second loop on the same thing and compare it with the original.", quiz: [{ question: "You have made something and it is mediocre. What is the strongest next step?", options: ["Find the single weakest part and change only that", "Rewrite the whole thing", "Start again with a better plan", "Ask for general feedback"], answer: 0, explanation: "One targeted change tells you what worked. A rewrite tells you nothing and costs far more." }, { question: "You changed five things and it is better. What do you know?", options: ["That the set of changes helped, but not which ones", "That all five were improvements", "That your judgement is good", "That you should change five more"], answer: 0, explanation: "Without isolation you cannot carry the lesson into the next thing you make." }, { question: "How do you know when to stop iterating?", options: ["When the changes stop improving it and start merely changing it", "After a fixed number of versions", "When you run out of time", "When someone says it is good"], answer: 0, explanation: "Recognising that point is part of the skill, and it prevents endless revision." }, { question: "What has to happen after each change?", options: ["You look at it again properly", "You make the next change", "You show it to someone new", "You record what you did"], answer: 0, explanation: "The looking is the part most often skipped, and without it the loop is not a loop." }, { question: "Which is the weakest part worth attacking first?", options: ["The one that most affects whether the thing works", "The one that is easiest to fix", "The one you like least", "The one someone criticised"], answer: 0, explanation: "Impact, not ease or preference, is what makes the loop efficient." }, { question: "Your second version is worse than your first. What now?", options: ["Go back, and keep the version that was better", "Keep going, it will improve", "Start from scratch", "Combine both versions"], answer: 0, explanation: "Iteration includes reverting. A worse version is information, not a commitment." }, { question: "Someone says their work will be good once they have finished planning it. What is the accurate reply?", options: ["It becomes good through loops after it exists, not before", "Planning is what makes work good", "They should plan less and hope", "Only talented people can skip planning"], answer: 0, explanation: "The quality is produced by revision against reality, which cannot begin until there is something to revise." }, { question: "How does iteration relate to the ugly first version?", options: ["The ugly version is what gives the loop something to work on", "They are opposites", "Iteration replaces prototyping", "Prototypes should not be iterated"], answer: 0, explanation: "Prototype and iteration are two halves of the same method: make something cheap, then improve it deliberately." }] },
    { title: "Ideas Come From Constraints", why: "A blank page produces nothing; a narrow brief produces more ideas than a wide one.", lesson: "Total freedom is the least creative condition there is, because there is nothing to push against. Give yourself a real constraint — one colour, five sentences, twenty minutes, materials you already have, no new tools — and ideas arrive almost immediately, because the constraint has removed the infinite options that were paralysing you. This is not a compromise you accept when resources are short. It is a technique you use on purpose. When you are stuck, the strongest move is usually to make the brief narrower rather than wider.", keyIdea: "When you are stuck, narrow the brief. Constraints generate ideas; freedom paralyses.", example: "Asked to write anything, you write nothing. Asked to write five sentences about one object in the room, you start immediately.", actionPrompt: "Take something you are stuck on and impose one hard constraint, then work inside it.", actionHint: "Real constraints: a time limit, a size limit, one material, no new tools, existing pieces only.", bonus: "Do the same task again with a different constraint and compare what came out.", quiz: [{ question: "You are stuck on a creative task with complete freedom. What is the strongest move?", options: ["Narrow the brief with a hard constraint", "Take a break until inspiration arrives", "Look at what other people have done", "Widen the brief to find more options"], answer: 0, explanation: "Freedom is the condition producing the block. Narrowing gives you something to push against." }, { question: "Which is a real constraint?", options: ["Twenty minutes, one colour, no new tools", "Make it good", "Do your best work", "Be more creative"], answer: 0, explanation: "A constraint has to be checkable. The others are only encouragement." }, { question: "Someone says constraints limit creativity. What is the accurate reply?", options: ["The blank page is the least creative condition there is", "They are correct", "Constraints only help beginners", "It depends on the person"], answer: 0, explanation: "Options without limits paralyse. Almost every craft tradition is built on deliberate restriction." }, { question: "You have a genuine shortage of time and materials. How should you treat it?", options: ["As a brief, not as a handicap", "As a reason to postpone the work", "As a compromise on quality", "As something to complain about"], answer: 0, explanation: "A shortage supplies the constraint for free. Treating it as a brief changes what you produce with it." }, { question: "You imposed a constraint and produced something worse. What now?", options: ["Try a different constraint and compare", "Remove all constraints", "Conclude the technique does not work", "Keep the same constraint and try harder"], answer: 0, explanation: "Constraints are tools with different effects. One that did not help simply points at trying another." }, { question: "When is this technique most useful?", options: ["When you are stuck and everything is possible", "When you have a tight deadline", "When you are working with other people", "When the task is technical"], answer: 0, explanation: "The paralysis of infinite options is the exact condition it addresses." }, { question: "Which brief will generate more ideas?", options: ["Five sentences about one object in this room", "Write anything you like", "Write something meaningful", "Write about your life"], answer: 0, explanation: "The narrowest brief is the one you can start on immediately." }, { question: "What should you do with the constraint once the ideas arrive?", options: ["Keep it while you work, or relax it deliberately", "Drop it immediately", "Add more constraints", "Ignore it from then on"], answer: 0, explanation: "The constraint shaped the idea. Dropping it without thought usually loses what made the idea work." }] },
    { title: "The Last Ten Percent", why: "The final tenth of a project takes a disproportionate share of the effort, and it is where most work dies.", lesson: "There is a point where a thing is nearly done, no longer interesting, and still not finished. The remaining work is tidying, checking, fixing the awkward edge, writing the boring part — none of it satisfying, all of it necessary, and the gap between nearly finished and actually finished is where an enormous amount of work quietly ends. The move is to name the last ten percent explicitly, as a list, and treat it as its own task rather than as an afterthought. Something finished and imperfect is worth far more than something excellent and abandoned.", keyIdea: "Name the last ten percent as its own list, and finish it. Nearly done is not done.", example: "The project has been ninety percent complete for three weeks. You write the seven remaining items down and it is finished in an evening.", actionPrompt: "Take something that is nearly finished, list exactly what remains, and complete it.", actionHint: "Write the remaining items out. Nearly done is usually four small things wearing a disguise.", bonus: "Show the finished thing to one person, which is what finished actually means.", quiz: [{ question: "Your project has been ninety percent done for three weeks. What is the strongest move?", options: ["Write down exactly what remains and do it as its own task", "Wait until you feel motivated to finish", "Start something new and come back", "Accept it as finished at ninety percent"], answer: 0, explanation: "Nearly done is usually a handful of small unnamed tasks. Naming them makes an evening's work out of three weeks." }, { question: "Why does the last tenth take a disproportionate share of the effort?", options: ["It is the unsatisfying work — tidying, checking, awkward edges", "It is the most technically difficult", "You are tired by then", "The scope grows at the end"], answer: 0, explanation: "The remaining work is dull rather than hard, which is a different and more dangerous problem." }, { question: "Which is worth more?", options: ["Something finished and imperfect", "Something excellent and abandoned", "Something perfect and unfinished", "Several things at ninety percent"], answer: 0, explanation: "Only finished work can be used, shown or judged. Unfinished excellence has no effect on anything." }, { question: "You are bored of a project that is nearly done. What does that indicate?", options: ["You have reached the last ten percent, which is normal", "You chose the wrong project", "You should stop and do something else", "The project was too long"], answer: 0, explanation: "Boredom at that specific point is a predictable stage, not a verdict on the work." }, { question: "What does finished actually mean here?", options: ["Someone else can see or use it", "You have stopped working on it", "It meets your standard", "You have run out of things to add"], answer: 0, explanation: "A definition that involves someone else is the only one that cannot be quietly renegotiated." }, { question: "You have four projects all at ninety percent. What is the strongest move?", options: ["Finish one completely before touching the others", "Work on all four in parallel", "Abandon three and start fresh", "Add a fifth to find one you can finish"], answer: 0, explanation: "One finished thing changes your evidence about yourself. Four near-misses do not." }, { question: "How should the remaining work be treated?", options: ["As its own task with its own list", "As an afterthought to fit in", "As optional polish", "As the beginning of the next version"], answer: 0, explanation: "Treating it as an afterthought is exactly how it never gets done." }, { question: "What is the relationship between this and pushing through the uncomfortable middle?", options: ["Same problem at a different point: unglamorous work that decides whether it exists", "They are unrelated", "This one is about quality", "The middle matters more"], answer: 0, explanation: "Both are stages where the work stops being interesting and finishing depends on recognising that." }] },
    { title: "Make Something Someone Uses", why: "The whole section comes down to this: something you built that another person actually uses.", lesson: "You have learned by doing, chosen a skill, broken work into pieces, rebuilt something good, built an ugly first version, diagnosed a real problem, iterated deliberately, used constraints and finished the last tenth. This is the assembly. Make one small thing and put it into someone's hands — a tool for your family, a page for a friend's business, a guide for people in your class, a repair someone needed. Small and used beats large and unseen. When it is being used, you will learn things about your own work that no amount of building alone would have told you.", keyIdea: "Build one small thing and put it in someone's hands. Used beats impressive.", example: "You build a one-page timetable tool for your class. Eleven people use it and four tell you what is wrong with it — which is a better education than the building was.", actionPrompt: "Make one small useful thing this week and give it to someone who will actually use it.", actionHint: "Solve a problem you have watched a real person have. That is what makes it get used.", bonus: "Ask the person what they would change, and run one iteration on it.", quiz: [{ question: "You have two weeks. You can study more, or build one small thing for someone. Which serves you better?", options: ["Build the thing and put it in their hands", "Study, so that what you build later is better", "Split the two weeks evenly", "Study now and build once you are ready"], answer: 0, explanation: "Use generates feedback that study cannot. The thing built badly teaches more than another fortnight of reading." }, { question: "How should you choose what to make?", options: ["Solve a problem you have watched a real person have", "Pick the most interesting idea you have", "Build whatever shows your skill best", "Ask what is most in demand generally"], answer: 0, explanation: "An observed problem is what makes the thing get used rather than admired and abandoned." }, { question: "Eleven people use it and four tell you what is wrong. How should you read that?", options: ["As the most valuable feedback you have had", "As a sign it was not good enough", "As criticism to defend against", "As reason to rebuild it entirely"], answer: 0, explanation: "Real use surfaces problems that building alone never reveals. Four reports is a good outcome." }, { question: "Which is worth more?", options: ["A small tool eleven people use", "A large project nobody has seen", "A polished piece for your portfolio", "A skill you have practised for months"], answer: 0, explanation: "Use is what generates the feedback loop. Everything unused is theory." }, { question: "The person you built it for stops using it after a week. What is the useful response?", options: ["Ask why, and treat the answer as the lesson", "Conclude the project failed", "Build them something else", "Assume they did not need it after all"], answer: 0, explanation: "Abandonment has a specific cause, and knowing it is worth more than the original build." }, { question: "How large should the first thing be?", options: ["Small enough to finish and hand over this week", "Large enough to be impressive", "As large as your skill allows", "Whatever the person asks for"], answer: 0, explanation: "Handed over this week means the feedback arrives this week. That is the whole point." }, { question: "Someone will test what you built, but only if you fix two things first. What is the strongest response?", options: ["Fix them and get it into their hands", "Ask them to test it as it is", "Rebuild it properly before showing anyone", "Find someone less demanding to test it"], answer: 0, explanation: "Two named fixes is a small price, and a real user is the scarce resource here." }, { question: "What is the honest measure of success here?", options: ["Somebody used it and told you something you did not know", "It was finished on time", "It looked good", "You enjoyed making it"], answer: 0, explanation: "The new information is the return. Everything else is available from building alone." }] },
  ],
  [
    { title: "Value Begins With a Need", why: "Useful work starts by noticing what would genuinely help someone.", lesson: "Creating value means reducing a real problem, making something clearer, saving time, improving an experience, or offering a skill people need. Begin with observation: who is struggling, and what would make the next step easier?", keyIdea: "Look for a real need before you design an answer.", example: "A simple checklist for a confusing school process may be more valuable than an impressive-looking idea nobody uses.", actionPrompt: "Identify one small problem a real person or group faces. Describe who it affects and why it matters.", actionHint: "Do not solve it yet; learn to see it clearly first.", bonus: "Ask one person about the problem instead of guessing.", quiz: [{ question: "You have an idea for something and are excited about it. What should you do first?", options: ["Find out whether anyone actually has the problem it solves", "Start building it while the excitement lasts", "Plan it out in full", "Check whether anyone else has built it"], answer: 0, explanation: "Value begins with a need. An idea nobody needs is a hobby, which is fine, but you should know which one you have." }, { question: "You built something useful and nobody wants it. What is the most likely explanation?", options: ["It solves a problem people do not actually have", "It was not built well enough", "You did not promote it enough", "People do not recognise quality"], answer: 0, explanation: "Usefulness is decided by the person with the problem, not by the person who built the thing." }, { question: "Which is the strongest signal that a need is real?", options: ["People are already doing something awkward to work around it", "People say it sounds like a good idea", "You would find it useful yourself", "Nobody has built it yet"], answer: 0, explanation: "An existing workaround is behaviour, and behaviour is far better evidence than an opinion." }, { question: "Someone tells you your idea sounds great. How much is that worth?", options: ["Very little — it costs them nothing to say", "It is strong validation", "It depends who they are", "It confirms the need exists"], answer: 0, explanation: "Encouragement is cheap. What people already do about the problem is the evidence." }, { question: "You can build something impressive or something people need. Which does this day point at?", options: ["The one people need", "The impressive one, because it shows your skill", "Whichever is faster", "Both equally"], answer: 0, explanation: "Value is measured at the other end. Impressiveness is measured at yours." }, { question: "What is the cheapest way to test whether a need is real?", options: ["Ask people what they currently do about it", "Build a working version and see", "Survey a large number of people", "Research the market thoroughly"], answer: 0, explanation: "Current behaviour is available today, for free, and it is more honest than a stated preference." }, { question: "You solve a problem for one person very well. Is that valuable?", options: ["Yes, and it is usually how larger value starts", "No, it is too small to matter", "Only if you can charge for it", "Only if others have the same problem"], answer: 0, explanation: "One person properly served is real value, and it is the most common starting point for more." }, { question: "You have built something genuinely useful and nobody has heard of it. What is the missing piece?", options: ["Being able to explain it to the people who need it", "A better version of the thing", "More time", "A larger audience"], answer: 0, explanation: "Useful work that cannot be conveyed stays unused, which is exactly what the next section addresses." }] },
    { title: "Use Your Whole Voice", why: "A flat voice makes good material sound like bad material.", lesson: "Your voice has four dials you can move on purpose: pitch (high to low), volume (quiet to loud), pace (slow to fast) and energy (calm to lively). Most people leave all four in one position and never notice. Moving them is not acting — it is the difference between a sentence people hear and a sentence they follow. Drop your pitch slightly for something serious. Slow down for something important. Lift your energy for something you actually care about.", keyIdea: "Pitch, volume, pace and energy are dials you can move deliberately, not fixed settings.", example: "“We need to talk about this” means something completely different said slowly and low than said quickly and bright.", actionPrompt: "Say one short sentence out loud three times, changing pitch, pace, volume and energy each time.", actionHint: "Use the same words every time. Only the delivery changes.", bonus: "Record all three versions and listen back. Pick which one you would want to hear.", quiz: [{ question: "You are saying something serious and want it to land. What is the most useful vocal adjustment?", options: ["Slow the pace and drop the pitch slightly", "Raise your pitch and speed up", "Increase volume as much as possible", "Say it exactly as you say everything else"], answer: 0, explanation: "Slower and lower reads as weight. Fast and high reads as excitement, which is a different signal." }, { question: "Someone tells you that you sound monotonous. What are they describing?", options: ["Your pitch, pace, volume and energy are staying in one position", "Your vocabulary is too simple", "You are speaking too quietly", "You are talking for too long"], answer: 0, explanation: "Monotony is a delivery problem: the dials are not moving, whatever the words are doing." }, { question: "You are explaining something you genuinely find exciting, but people look bored. What is most likely wrong?", options: ["Your energy is not showing in your voice", "The topic is boring", "You need more detail", "They are not interested in you"], answer: 0, explanation: "Interest that never reaches your voice does not reach the listener either." }, { question: "Which is the strongest way to practise vocal variety?", options: ["Say the same sentence several ways and notice how the meaning changes", "Read a long passage aloud in your normal voice", "Memorise a script word for word", "Learn more impressive words"], answer: 0, explanation: "Holding the words constant is what isolates delivery so you can actually hear it." }, { question: "You want one part of a sentence to stand out. What should you do?", options: ["Change something — slow down, go quieter, or pause before it", "Say the whole sentence louder", "Repeat the sentence twice", "Speed up to get to it faster"], answer: 0, explanation: "Emphasis is contrast. Changing everything equally emphasises nothing." }, { question: "What is the honest purpose of moving your voice around?", options: ["So people can follow which parts matter", "To sound like a professional speaker", "To seem more confident than you are", "To fill more time"], answer: 0, explanation: "Vocal variety is a signal system for the listener, not a performance for its own sake." }, { question: "You go quieter for one sentence in the middle of speaking. What usually happens?", options: ["People lean in and pay more attention to it", "People stop listening", "It sounds like you are unsure", "It has no effect at all"], answer: 0, explanation: "A deliberate drop in volume draws attention, which is why it works as emphasis." }, { question: "What is the difference between vocal variety and acting?", options: ["Variety serves what you actually mean; acting performs a feeling you do not have", "There is no difference", "Acting is always louder", "Variety is only for presentations"], answer: 0, explanation: "The test is whether the delivery matches what you genuinely mean. That is what keeps it honest." }] },
    { title: "Clarity and the Pause", why: "A pause gives people time to understand you; rushing takes it away.", lesson: "Clarity is mechanical and therefore fixable. Open your mouth slightly more than feels natural, finish the ends of words, and slow down. Then add the thing almost nobody does: pause. A pause after an important sentence lets it land. A pause instead of “erm” makes you sound considered rather than uncertain. Silence feels much longer to the person speaking than to the person listening — that gap is why pauses feel risky and sound calm.", keyIdea: "A pause after something important is what gives the listener room to receive it.", example: "Saying the point, then stopping for two seconds, does more than saying it three times.", actionPrompt: "Record yourself explaining something for thirty seconds. Find one place you rushed, mumbled, or needed a pause, and record it again better.", actionHint: "Listen for the ends of your words, not just the beginnings.", bonus: "Replace every “erm” with a silent pause for one whole conversation.", quiz: [{ question: "You notice you are speaking very quickly during a presentation. What is a useful adjustment?", options: ["Add deliberate pauses and slow your pace", "Speak even faster to finish sooner", "Stop speaking", "Memorise more words"], answer: 0, explanation: "Pauses and pace are the direct fix. Speed is the problem, so more speed cannot solve it." }, { question: "You are explaining an idea and notice the person looks confused. What should you do?", options: ["Slow down and explain the confusing part more simply", "Speak faster", "Speak louder", "Carry on and ignore it"], answer: 0, explanation: "Confusion means the explanation missed. Simplifying the specific part is the fix; volume and speed are not." }, { question: "You keep saying “erm” between sentences. What is the strongest replacement?", options: ["A short silent pause", "A longer “erm”", "Speaking faster so there is no gap", "Apologising for it"], answer: 0, explanation: "Silence does the same job without the cost. It also sounds considered rather than uncertain." }, { question: "A pause feels uncomfortably long while you are speaking. What is most likely true?", options: ["It sounds much shorter to everyone listening", "It genuinely is too long", "People think you have forgotten your point", "You should never pause"], answer: 0, explanation: "Speakers experience silence as far longer than listeners do. Trust the listener's clock, not yours." }, { question: "You are told you mumble. Which change helps most?", options: ["Open your mouth more and finish the ends of your words", "Use simpler vocabulary", "Speak more quietly so it sounds deliberate", "Speak only when asked"], answer: 0, explanation: "Mumbling is mostly unfinished word endings and a closed mouth. Both are mechanical and fixable." }, { question: "You have just made your most important point. What is the strongest next move?", options: ["Pause and let it land", "Immediately explain it again", "Move quickly to the next point", "Ask if that made sense"], answer: 0, explanation: "The pause is what gives the point room. Rushing on buries it under the next thing." }, { question: "Why record yourself speaking?", options: ["You hear rushing, mumbling and filler that are invisible from the inside", "To check how you look", "To memorise the wording", "To prove you are already good"], answer: 0, explanation: "Recording is the only cheap way to hear the habits you cannot notice while speaking." }, { question: "You are asked a question and want a moment to think. What is the strongest response?", options: ["Pause, then answer", "Start talking immediately and work it out aloud", "Say “erm” until the answer arrives", "Say you do not know"], answer: 0, explanation: "A visible pause before answering reads as thoughtful. Filling it reads as flustered." }] },
    { title: "Tell It Like a Story", why: "People remember a story and forget a summary, even when the summary is more accurate.", lesson: "A story has a beginning, a middle and an end, and that is nearly all there is to it. The beginning sets a situation. The middle introduces something that changed or went wrong. The end says what happened and why it mattered. Most people tell stories badly by starting with too much background and never reaching the point. Say who and where in one sentence, get to the interesting part quickly, and finish deliberately rather than trailing off into “so yeah, anyway”.", keyIdea: "Set the situation in one sentence, get to what changed, and finish on purpose.", example: "“I was late for the bus — and the driver waited for me. Turns out he recognised me from the mosque.” That is a complete story in three parts.", actionPrompt: "Tell someone something that happened to you today in sixty seconds, with a clear beginning, middle and end.", actionHint: "Decide your last line before you start.", bonus: "Tell the same story again using vocal variety and one pause before the ending.", quiz: [{ question: "You start telling a story and realise you are three sentences into background. What should you do?", options: ["Skip to the part where something changed", "Finish the background properly first", "Start again from the beginning", "Add more detail so it makes sense"], answer: 0, explanation: "Background is what loses people. The change is the story; everything before it is setup." }, { question: "You are about to tell someone what happened at school. What are the three parts you need?", options: ["The situation, what changed, and what it meant", "The introduction, the facts, and the conclusion", "The problem, the solution, and the advice", "The beginning, the details, and the moral"], answer: 0, explanation: "Situation, change, meaning. It is the change in the middle that makes it a story at all." }, { question: "Your stories often end with “so yeah, anyway…”. What is the fix?", options: ["Decide the last line before you start telling it", "Tell shorter stories", "Tell stories only to close friends", "Add a moral at the end"], answer: 0, explanation: "Trailing off happens when the ending was never chosen. Choosing it in advance solves it." }, { question: "You are telling a story and want to hold attention at the key moment. What is most useful?", options: ["Pause just before it, then slow down", "Speak faster to build excitement", "Raise your volume throughout", "Explain what is about to happen"], answer: 0, explanation: "A pause before the key moment creates anticipation. Announcing it removes it." }, { question: "You want to tell someone a quick story. Which opening is strongest?", options: ["One sentence saying who and where, then straight to what happened", "A full explanation of everyone involved", "A warning that it is a long story", "An apology that it might not be interesting"], answer: 0, explanation: "One sentence of setup is usually enough. The other three cost attention before you have earned it." }, { question: "You are explaining something factual and it sounds flat. What often helps most?", options: ["Turn it into something that happened to a person", "Add more facts", "Speak more loudly", "Use more technical terms"], answer: 0, explanation: "A concrete situation with a person in it is remembered where an abstract summary is not." }, { question: "What role do facial expression and gestures play in telling a story?", options: ["They carry part of the meaning, so a still face flattens it", "They are a distraction from the words", "They only matter on stage", "They should be planned in advance"], answer: 0, explanation: "Delivery is not only vocal. A still, blank face contradicts an interesting story." }, { question: "Someone interrupts your story with a question. What is the strongest response?", options: ["Answer briefly, then return to where you were", "Start the story from the beginning", "Ignore the question", "Abandon the story"], answer: 0, explanation: "A short answer and a return keeps both the question and the story intact." }] },
    { title: "The First Ten Seconds", why: "People form an impression before you have said anything of substance, and it decides how much attention you get.", lesson: "A first impression is made of four things arriving at once: how you enter, how you look, how you greet, and how you sound. None of them is about being impressive. Walk in without rushing, look at the person, say a clear greeting with your name, and let your face be warm rather than braced. That combination buys you attention. What you do with the attention is a separate question, and it is the one that actually matters. Presentation opens the door. Character and competence determine what happens after you walk through it.", keyIdea: "Presentation opens the door; character and competence decide what happens after you walk through it.", example: "Walking in unhurried, making eye contact and saying “Salaam, I'm Bilal” clearly does more in three seconds than a prepared opening line does in thirty.", actionPrompt: "Introduce yourself to someone, focusing on a clear greeting, comfortable posture, appropriate eye contact and clear speech.", actionHint: "Say your name slowly enough that they actually catch it.", bonus: "Practise walking into a room unhurried, as though you are expected there.", quiz: [{ question: "You are meeting someone for the first time. Which combination is most useful?", options: ["Look prepared, greet them clearly, and show genuine interest", "Ignore them and wait for them to do everything", "Try to impress them constantly", "Talk only about yourself"], answer: 0, explanation: "Prepared, clear and interested is the whole of a good first impression. The rest are either passive or self-centred." }, { question: "What does a good first impression actually get you?", options: ["Attention and goodwill, which you then have to justify", "A permanent judgement in your favour", "Proof that you are competent", "Nothing, since first impressions do not matter"], answer: 0, explanation: "It opens the door. Character and competence decide what happens after that." }, { question: "You mumble your name during an introduction. Why does it matter more than it seems?", options: ["They now cannot use your name, and are unlikely to ask twice", "It makes you look unintelligent", "Names are the most important part of any conversation", "It does not matter"], answer: 0, explanation: "An uncaught name quietly removes something the whole rest of the conversation would have used." }, { question: "You walk into a room rushed and flustered. What does it most likely communicate?", options: ["That you are not on top of the situation", "That you are busy and important", "Nothing at all", "That you are enthusiastic"], answer: 0, explanation: "Hurry reads as being behind. Unhurried reads as belonging, whatever the truth is." }, { question: "Which matters most in the first ten seconds?", options: ["Entering, looking, greeting and sounding — all at once", "What you say about yourself", "How impressive your clothes are", "How much you know about the topic"], answer: 0, explanation: "The first impression is a combination arriving together, not any single element." }, { question: "You are meeting someone older or more senior than you. What is the strongest approach?", options: ["Turn up prepared and on time, greet them clearly, and listen", "Mention your achievements early", "Say as little as possible", "Match their level of formality exactly"], answer: 0, explanation: "Preparation and attention signal respect. Impressing and hiding are both worse than listening." }, { question: "Your first impression went badly. What is the most useful response?", options: ["Accept it is recoverable through what you do next", "Assume the relationship is ruined", "Try to explain what went wrong", "Avoid them from now on"], answer: 0, explanation: "First impressions are not verdicts. Competence and consistency change them over time." }, { question: "What is the honest limit of good presentation?", options: ["It gets you a first meeting; it cannot get you a second", "It determines how far you will go", "It matters more than skill", "It has no effect on anything"], answer: 0, explanation: "Presentation opens a door. What happens next is decided by what you can actually do." }] },
    { title: "Turn Up Presentable", why: "Being clean, tidy and dressed for the occasion is a skill anyone can do, and it changes how seriously you are taken.", lesson: "This is not about how you look. It is about being clean, groomed, dressed for the situation you are actually in, and visibly prepared. Those are habits, not features — available to everybody regardless of anything else. Ask what this particular setting expects rather than what looks impressive in general: the answer is different for a job interview, a football session and a family gathering. Preparing properly says you take the occasion seriously, and it says the same thing to you as it does to everyone else.", keyIdea: "Clean, groomed, appropriate and prepared — four habits, not four features.", example: "Ironed clothes and arriving five minutes early get noticed. Nothing here is about how you look.", actionPrompt: "Prepare yourself properly for one specific situation today, and name one presentation habit you could improve.", actionHint: "Ask what this setting expects, not what looks impressive generally.", bonus: "Lay out what you need the night before, so being prepared does not depend on the morning going well.", quiz: [{ question: "You want to look presentable for an important event. What matters most?", options: ["Being clean, groomed, appropriately dressed, and prepared", "Looking exactly like other people", "Wearing the most expensive clothes you own", "Standing out as much as possible"], answer: 0, explanation: "Clean, groomed, appropriate, prepared. All four are habits, and all four are available to anyone." }, { question: "You have a job interview, a sports session and a family gathering. How should you dress?", options: ["Differently for each, according to what that setting expects", "The same smart outfit for all three", "As formally as possible every time", "However you feel like on the day"], answer: 0, explanation: "Appropriateness is situational. Reading the setting is the skill, not owning one impressive outfit." }, { question: "Which of these is genuinely within anyone's control?", options: ["Being clean, tidy, on time and prepared", "Being tall", "Having expensive clothes", "Having naturally clear skin"], answer: 0, explanation: "Presentation is a set of habits. That is exactly what makes it worth practising." }, { question: "A friend says none of this matters because appearance should not be judged. What is the strongest reply?", options: ["This is about hygiene, tidiness and fitting the occasion — not about how you look", "They are right, so ignore it", "Appearance is the most important thing", "They will never be taken seriously"], answer: 0, explanation: "The distinction is the whole point. Nobody is being asked to be attractive, only clean and appropriate." }, { question: "You arrive at something important looking unprepared. What does it communicate?", options: ["That you did not take the occasion seriously", "That you are relaxed and confident", "That you are humble", "Nothing at all"], answer: 0, explanation: "Preparation is read as a measure of how seriously you take the people and the occasion." }, { question: "What is the healthiest way to think about your own appearance?", options: ["Take care of what you control, and do not build your worth on it", "Compare yourself with whoever looks best", "Ignore it entirely", "Assume it decides how far you will get"], answer: 0, explanation: "Care without dependence. Effort is within reach; self-worth should not rest on how you look." }, { question: "You have five minutes before an important meeting. What is the most useful thing to check?", options: ["That you are tidy, and that you have what you need with you", "Whether your clothes are more expensive than theirs", "How you compare with everyone else there", "Nothing — it is too late to matter"], answer: 0, explanation: "Tidiness and preparation are both still fixable in five minutes. Comparison fixes nothing." }, { question: "Which habit does most for how prepared you look?", options: ["Laying things out the night before", "Buying better clothes", "Arriving late so people are already settled", "Checking your reflection frequently"], answer: 0, explanation: "Preparation that does not depend on the morning going well is the most reliable kind." }] },
    { title: "What Your Body Says", why: "Your posture and expression are read constantly, and they are usually read before your words.", lesson: "There is no single magic posture that makes someone confident. Body language works by communicating two things: openness and attention. Openness is uncrossed arms, facing the person, a face that is not braced. Attention is looking at whoever is speaking, turning towards them, putting the phone away. Closed and distracted signals are the ones that cost you, and most people who feel shy send them accidentally. You do not need a power stance. You need to look reachable and look like you are listening.", keyIdea: "Body language communicates two things worth getting right: openness and attention.", example: "Turning your body towards someone who starts speaking does more than any deliberate posture ever will.", actionPrompt: "Have a short conversation while consciously practising one body-language skill.", actionHint: "Pick one thing only — arms, or eye contact, or facing them. Not all three.", bonus: "Notice what your face is doing when you are not thinking about it.", quiz: [{ question: "You want to look approachable at a gathering. What should your body be doing?", options: ["Facing the room, arms uncrossed, head up", "Arms folded while you wait to be noticed", "Looking down at your phone", "Standing where nobody will see you"], answer: 0, explanation: "Approachability is mostly physical. Closed posture reads as “leave me alone” whatever you intend." }, { question: "Someone claims there is one confident posture everyone should use. What is more accurate?", options: ["Body language works by showing openness and attention, not by one correct stance", "They are right, and it should be practised daily", "Posture makes no difference", "Only eye contact matters"], answer: 0, explanation: "There is no magic stance. Openness and attention are the two things actually being communicated." }, { question: "How much eye contact is right in an ordinary conversation?", options: ["Comfortable — look at them while they speak, look away naturally at times", "Constant and unbroken", "As little as possible", "Only when you are talking"], answer: 0, explanation: "Comfortable beats both extremes. Staring is as uncomfortable as avoiding eyes entirely." }, { question: "You are listening to someone while glancing at your phone. What are you communicating?", options: ["That the phone ranks above them right now", "That you are relaxed", "Nothing, since you can hear them", "That you are good at multitasking"], answer: 0, explanation: "Divided attention is visible and reads as a ranking, whether or not you mean it." }, { question: "You feel nervous entering a room. What is the most useful physical adjustment?", options: ["Straighten up, unfold your arms, and slow your walk", "Move quickly to the edge of the room", "Cross your arms so you feel protected", "Look at the floor until you settle"], answer: 0, explanation: "Posture is the fastest change available, and it affects how you feel as well as how you look." }, { question: "Someone starts speaking to you while you are sitting side-on. What is the strongest move?", options: ["Turn your body towards them", "Turn only your head", "Stay as you are and listen", "Move away to give them space"], answer: 0, explanation: "Turning towards someone is one of the clearest available signals of attention." }, { question: "Your face is tense while listening. What effect does it have?", options: ["People read it as disapproval, even when you feel none", "It makes you look thoughtful", "It has no effect", "It makes you seem trustworthy"], answer: 0, explanation: "Faces are read constantly and misread generously. Neutral or warm is easier to talk to." }, { question: "You want to practise body language. What is the strongest approach?", options: ["Change one thing at a time in real conversations", "Practise several changes at once in front of a mirror", "Read about it thoroughly first", "Copy someone you find impressive"], answer: 0, explanation: "One change at a time is the only version you can actually keep track of while talking." }] },
    { title: "Confidence Is Built, Not Faked", why: "Waiting to feel confident before acting is a rule that guarantees you never start.", lesson: "Confidence is not a feeling you acquire and then use. It is the accumulated evidence that you can handle things, and evidence only comes from doing. That means the order is backwards from how it feels: you act while nervous, it goes acceptably, and confidence follows. This is not pretending — pretending is claiming to feel something you do not. Doing something while openly nervous is the opposite of pretending, and it is the only thing that actually works. Keeping small promises to yourself builds the same evidence quietly.", keyIdea: "Confidence is evidence you collected by acting, not a feeling you wait for.", example: "Someone who has asked ten questions in class is confident about asking the eleventh. Nothing else got them there.", actionPrompt: "Do one small social action that makes you slightly uncomfortable but is safe and appropriate.", actionHint: "Slightly uncomfortable. Not terrifying — that is a different exercise.", bonus: "Keep one small promise to yourself today that nobody else will know about.", quiz: [{ question: "You want to become more confident speaking to people. Which approach is strongest?", options: ["Take small opportunities to practise while accepting some nervousness", "Wait until you never feel nervous", "Avoid situations that make you nervous", "Act as though you are better than everyone"], answer: 0, explanation: "Confidence follows action. Waiting and avoiding both remove the only thing that builds it." }, { question: "A friend tells you to just fake confidence. What is the difference between confidence and pretending?", options: ["Confidence is acting while nervous; pretending is claiming a feeling you do not have", "There is no real difference", "Confidence means never showing nerves", "Pretending works just as well"], answer: 0, explanation: "Acting while openly nervous is the opposite of pretending, and it is what actually produces evidence." }, { question: "You made a visible mistake in front of others. What is the strongest response?", options: ["Acknowledge it briefly, correct it, and carry on", "Pretend it did not happen", "Apologise at length", "Leave the situation"], answer: 0, explanation: "Brief acknowledgement and continuation costs almost nothing. The other options make it larger." }, { question: "Someone clearly does not like you. What is the healthiest response?", options: ["Accept it — not everyone will, and that is normal", "Work hard to change their mind", "Decide something is wrong with you", "Dislike them back"], answer: 0, explanation: "Universal approval is not available to anyone. Needing it makes ordinary moments painful." }, { question: "You keep a small promise to yourself that nobody else knows about. What does that build?", options: ["Evidence that you do what you say, which is what self-respect rests on", "Nothing, since nobody else sees it", "A reputation with other people", "A reason to feel superior"], answer: 0, explanation: "Private promises kept are evidence too, and self-respect is built from exactly that." }, { question: "You feel nervous but do the difficult thing anyway. Which of these is genuine confidence?", options: ["Doing the difficult thing while still feeling nervous", "Feeling no nerves at all", "Believing you are better than others", "Never being wrong"], answer: 0, explanation: "Nerves and confidence coexist routinely. Superiority and infallibility are different things entirely." }, { question: "You have avoided a situation for months because it makes you nervous. What happens to the nervousness?", options: ["It usually grows, because avoidance never produces evidence", "It fades on its own with time", "It stays exactly the same", "It disappears once you feel ready"], answer: 0, explanation: "Avoidance protects the fear. Only doing the thing produces the evidence that shrinks it." }, { question: "What is the most useful size for a confidence-building action?", options: ["Slightly uncomfortable, and safe", "As frightening as possible", "Completely comfortable", "Whatever others are doing"], answer: 0, explanation: "Slightly uncomfortable is repeatable. Terrifying is a one-off, and comfortable teaches nothing." }] },
    { title: "Talking to People", why: "Most social difficulty is a small number of situations that can each be practised.", lesson: "Social confidence is not a personality type. It is a handful of specific moves: introducing yourself, starting a conversation, asking something you actually want the answer to, listening properly, and joining a group without interrupting it. Add two habits and most of the difficulty disappears — assume the least dramatic explanation when something feels awkward, and stop trying to be impressive. Trying to impress is what makes conversation exhausting. Being interested is easier and works better.", keyIdea: "Be interested rather than impressive; it is easier and it works better.", example: "“What made you get into that?” keeps a conversation going for ten minutes. “I know a lot about that too” usually ends it.", actionPrompt: "Start one genuine conversation with someone you do not normally talk to, focusing on listening rather than impressing them.", actionHint: "Aim to leave knowing something about them, not to have them know something about you.", bonus: "Join a conversation already in progress, which is the situation most people avoid entirely.", quiz: [{ question: "You want to join a conversation that is already happening. What is the strongest move?", options: ["Stand at the edge, listen for a moment, then add something relevant", "Interrupt with a new topic", "Wait to be formally invited in", "Stand nearby without speaking"], answer: 0, explanation: "Listening first and then contributing is how people join conversations without disrupting them." }, { question: "You ask someone a question and get a very short answer. What is the strongest next move?", options: ["Ask one more question about what they said", "Assume they do not want to talk and leave", "Fill the silence with a story about yourself", "Ask something completely unrelated"], answer: 0, explanation: "Most conversations need a second turn before they warm up. One short answer is not a verdict." }, { question: "You are worried about what everyone in the room thinks of you. What is most likely true?", options: ["They are mostly thinking about themselves", "They are all forming detailed opinions", "They have already decided about you", "You should try harder to impress them"], answer: 0, explanation: "Almost everyone is more concerned with their own impression than with assessing yours." }, { question: "Someone seems uninterested in talking to you. What is the strongest response?", options: ["Leave it politely and speak to someone else", "Try harder to win them over", "Assume you did something wrong", "Take it as proof you are bad at this"], answer: 0, explanation: "Disinterest is usually about their evening, not about you. Moving on politely costs nothing." }, { question: "What makes a question genuine rather than filler?", options: ["You actually want the answer, and it shows in how you listen", "It is a longer question", "It is about something serious", "It has been prepared in advance"], answer: 0, explanation: "Wanting the answer changes how you ask and how you listen. People can tell the difference." }, { question: "You are trying hard to seem impressive in a conversation. What is the likely effect?", options: ["It becomes exhausting for you and less enjoyable for them", "They will respect you more", "It is the fastest way to make friends", "It has no downside"], answer: 0, explanation: "Impressing is effortful and self-focused. Being interested is easier and works better." }, { question: "You said something that landed awkwardly. What now?", options: ["Clarify briefly and carry on — it is smaller than it feels", "Apologise repeatedly", "Leave the conversation", "Avoid that person afterwards"], answer: 0, explanation: "A brief clarification closes it. Everything else makes a small moment into a large one." }, { question: "What is the most useful goal for a conversation with someone new?", options: ["To leave knowing something real about them", "To have them find you interesting", "To talk for as long as possible", "To find out if they like you"], answer: 0, explanation: "Aiming to learn something makes the conversation easy. Aiming to be liked makes it work." }] },
    { title: "The Ninety-Second Test", why: "A skill you have never performed under mild pressure is a skill you cannot rely on.", lesson: "This is the practical test of everything in this stretch of the course. You will give a short presentation — sixty to ninety seconds, to at least one real person. Turn up presentable. Stand or sit with open posture. Speak clearly, at a useful volume and pace. Move your voice around rather than staying flat. Use at least one deliberate pause. Make it interesting rather than a list. Finish on a chosen line instead of trailing off. The goal is not a perfect performance. The goal is that it is noticeably better than it would have been ten days ago.", keyIdea: "The point is demonstrated improvement, not a flawless performance.", example: "Ninety seconds explaining something you built, delivered to one person who is actually listening, is a real test — a mirror is not.", actionPrompt: "Give a sixty to ninety second presentation, pitch or introduction to at least one real person.", actionHint: "Decide your first line and your last line in advance. Leave the middle loose.", bonus: "Record it, watch it once, and name the single thing you would change next time.", quiz: [{ question: "You have ninety seconds to explain an idea. What should you prepare most carefully?", options: ["The first line and the last line", "Every word, memorised", "A long list of details", "Nothing — it is better improvised"], answer: 0, explanation: "Fixed ends and a loose middle gives you a confident start and finish without a script to forget." }, { question: "Halfway through your presentation you lose your place. What is the strongest response?", options: ["Pause, find your next point, and continue", "Apologise and start again", "Speed up to cover the gap", "Stop and give up"], answer: 0, explanation: "A pause is barely noticeable. Apologising and restarting turns a small gap into the main event." }, { question: "You finish your presentation. What is the strongest ending?", options: ["The line you decided in advance, then stop", "“So yeah, that's about it”", "A summary of everything you just said", "An apology for going on too long"], answer: 0, explanation: "A chosen final line lands. Trailing off undoes the ninety seconds that came before it." }, { question: "What is the actual goal of this challenge?", options: ["To demonstrate improvement, not to perform perfectly", "To deliver it without any mistakes", "To impress the person listening", "To speak for the full ninety seconds"], answer: 0, explanation: "Improvement is the measurable thing. Perfection is neither required nor available." }, { question: "You are preparing to give it. Which of these matters least?", options: ["Using impressive vocabulary", "Speaking clearly at a useful pace", "Being presentable and prepared", "Using at least one deliberate pause"], answer: 0, explanation: "Delivery, preparation and pauses all do real work. Vocabulary is the one that mostly does not." }, { question: "Should you practise this in front of a mirror or a person?", options: ["A person — mild pressure is the thing being tested", "A mirror, so you can watch yourself", "Neither; think it through instead", "It makes no difference"], answer: 0, explanation: "A skill that has never been used under mild pressure is not yet reliable. A mirror removes the pressure." }, { question: "You notice you are rushing as you begin. What is the immediate fix?", options: ["Pause, breathe once, and start the next sentence slower", "Push on and finish quickly", "Apologise for being nervous", "Start again from the beginning"], answer: 0, explanation: "One pause resets the pace. Rushing to the end makes both the nerves and the speed worse." }, { question: "You have given it once and it went reasonably. What is the most useful next step?", options: ["Name one specific thing to change and do it again", "Decide the skill is finished", "Change everything for the next attempt", "Only do it again when you feel ready"], answer: 0, explanation: "One specific change per attempt is how a delivery skill actually improves." }] },
  ],
  [
    { title: "Responsibility Starts Where You Stand", why: "Leadership is not a position you are given; it starts with what you take charge of without being asked.", lesson: "People wait to be made responsible for something, and while they wait they are surrounded by things nobody has picked up. Leadership begins there — not with a title, a team or authority, but with the decision that something is now yours to see through. It costs you: if you take it on and it fails, that is visibly yours. That cost is the entry price, and it is why so few people pay it. Start with something small and real, where you can see the whole thing through to the end.", keyIdea: "Take charge of something before anyone assigns it to you, and see it through.", example: "Nobody has organised the equipment for the trip. You do it, badly the first time, and next time you are the person who does it.", actionPrompt: "Take charge of one thing today that nobody assigned to you, and carry it to completion.", actionHint: "Choose something small enough that you can see it all the way through, and tell the people affected that you have it.", bonus: "Do it a second time and write down what you would change about how you ran it.", quiz: [{ question: "Something needs organising and nobody has picked it up. What does leadership look like here?", options: ["Take it on and see it through", "Point out that nobody has done it", "Wait to be asked", "Ask who is responsible"], answer: 0, explanation: "The gap nobody has claimed is exactly where leadership starts, before any title is involved." }, { question: "You take something on and it goes badly. What is the honest reading?", options: ["That is the cost of taking it on, and it is the entry price", "You should not have volunteered", "It was someone else's fault for not helping", "You should avoid responsibility in future"], answer: 0, explanation: "Visible failure is the risk that stops most people. Paying it is what separates them." }, { question: "What should you do once you have taken something on?", options: ["Tell the people affected that you have it", "Get on with it quietly", "Wait until it is finished to say anything", "Ask permission first"], answer: 0, explanation: "People need to know who has it, or two of you do it and neither does it properly." }, { question: "How large should the first thing be?", options: ["Small enough to see all the way through", "Large enough to be noticed", "Whatever is most urgent", "Whatever nobody else wants"], answer: 0, explanation: "Completing something is the evidence. A large thing half-carried teaches nothing." }, { question: "Someone says they will lead when they are given a role. What is the accurate reply?", options: ["The role usually follows the behaviour, not the other way round", "That is reasonable", "They should ask for the role", "Leadership requires authority"], answer: 0, explanation: "People are given responsibility because they have already shown they take it." }, { question: "You take charge and someone resents that you did. What is the useful response?", options: ["Find out what you disrupted, and involve them next time", "Hand it back to them", "Continue and ignore it", "Explain that nobody else was doing it"], answer: 0, explanation: "Resentment usually points at a claim you could not see. That is worth knowing before the next one." }, { question: "Which is taking responsibility rather than commenting?", options: ["Organising the thing that keeps going wrong", "Raising it in a meeting", "Suggesting someone should sort it", "Asking who owns it"], answer: 0, explanation: "Only one of these changes the situation." }, { question: "How does this build on what you learned about owning outcomes?", options: ["It extends ownership to things nobody has assigned at all", "It replaces it", "It is a different skill", "It applies only in groups"], answer: 0, explanation: "Owning your outcome came first. Claiming an unowned one is the next step out." }] },
    { title: "Lead Yourself First", why: "Nobody follows a person whose own life is running on excuses.", lesson: "There is a plain test that comes before any question of leading other people: do you do what you said you would do, when you said you would do it, without being chased? If not, everything else in this section is theory. This is not about being flawless — it is about the gap between your word and your behaviour being small enough that people can plan around you. A person who is reliable in the ordinary things gets trusted with larger ones, and a person who is not stays where they are regardless of how capable they actually are.", keyIdea: "The gap between what you say and what you do is the whole of your authority.", example: "You said you would have it by Thursday. It is there on Thursday. Over a year that single pattern outweighs anything you could say about yourself.", actionPrompt: "Deliver one thing today exactly when you said you would, without being reminded.", actionHint: "If you will not make it, say so before the deadline, not after. That is part of keeping your word.", bonus: "Track for a week how many of your stated commitments landed on time.", quiz: [{ question: "You will not make a deadline you promised. When should you say so?", options: ["Before the deadline, as soon as you know", "After it passes, with an explanation", "Only if someone asks", "When you have a new date to offer"], answer: 0, explanation: "Early notice is part of keeping your word. Silence until it is missed is what damages trust." }, { question: "What is the plain test that comes before leading anyone else?", options: ["Whether you do what you said, when you said, without being chased", "Whether people like you", "Whether you are competent", "Whether you can speak well"], answer: 0, explanation: "Reliability in ordinary things is the foundation everything else is built on." }, { question: "You are highly capable but frequently late. What happens over time?", options: ["You stay where you are, because people cannot plan around you", "Your capability wins out", "People adjust their expectations", "It only matters for large commitments"], answer: 0, explanation: "Capability that cannot be relied on is a liability to plan around, not an asset." }, { question: "Is this about being flawless?", options: ["No — it is about the gap being small enough to plan around", "Yes, leaders cannot make mistakes", "Yes, in commitments to other people", "No, and there is nothing to work on"], answer: 0, explanation: "Perfection is not available. Predictability is." }, { question: "Someone chases you for something you promised. What does that tell you?", options: ["The chasing was a cost you imposed on them", "They are impatient", "You were nearly finished anyway", "It is a normal part of work"], answer: 0, explanation: "Being chased is evidence that keeping your word required their effort as well as yours." }, { question: "You have missed three commitments this month. What is the strongest response?", options: ["Make fewer commitments and keep them", "Try harder to keep the same number", "Explain the circumstances each time", "Stop making commitments"], answer: 0, explanation: "The volume is usually the problem. Fewer kept promises rebuilds more than many broken ones." }, { question: "How does this connect to the small promises you kept earlier in the course?", options: ["Same skill, now with other people depending on the outcome", "It is unrelated", "This one is easier", "That one was practice for nothing in particular"], answer: 0, explanation: "Keeping a promise to yourself built the capacity. This is where it becomes visible to others." }, { question: "What does your record of delivery actually communicate?", options: ["More than anything you could say about yourself", "Only your organisational ability", "Very little about character", "How busy you are"], answer: 0, explanation: "A year of landing on time is an argument nobody can make with words." }] },
    { title: "Decide on Principle", why: "A decision made from a rule you set in advance survives pressure; one made from mood does not.", lesson: "Most bad decisions are not made from bad reasoning. They are made from tiredness, from wanting the discomfort to stop, or from wanting a particular person to be pleased. The defence is deciding the principle before you are in the situation: what matters most here, what will I not do whatever the circumstances, what would I advise someone else in this position. Then, when the moment comes, you are applying a rule rather than negotiating with your own state. Decide, communicate it plainly, and be willing to change it if the facts change — but not because the pressure did.", keyIdea: "Set the principle in advance, then apply it. Change it for new facts, never for pressure.", example: "You decide beforehand that you will not agree to anything in the meeting itself. When the pressure comes, you say you will confirm tomorrow — and the decision is better.", actionPrompt: "Take a decision you are facing and write the principle it should be made on before you decide.", actionHint: "Ask what you would advise someone else in this position. It removes most of the mood.", bonus: "Say the principle out loud to whoever the decision affects, before you announce the decision.", quiz: [{ question: "You are being pressured to decide something now, in the room. What is the strongest move?", options: ["Say you will confirm tomorrow", "Decide now to show you are decisive", "Agree, then change it later if needed", "Refuse outright to end the pressure"], answer: 0, explanation: "Urgency is usually the pressure, not the situation. A day almost always improves the decision." }, { question: "What most often causes a bad decision?", options: ["Tiredness, or wanting the discomfort to stop", "Insufficient information", "Poor reasoning ability", "Bad advice"], answer: 0, explanation: "State, not logic, is the usual culprit — which is why the defence is a rule set in advance." }, { question: "When should you change a decision you made on principle?", options: ["When the facts change", "When people push back hard", "When it becomes uncomfortable", "When someone senior disagrees"], answer: 0, explanation: "New facts are a reason. Pressure is the thing the principle existed to withstand." }, { question: "Which question removes the most mood from a decision?", options: ["What would I advise someone else in this position", "What do I feel like doing", "What will upset the fewest people", "What did I do last time"], answer: 0, explanation: "The third-person view strips out fatigue and the wish to be liked." }, { question: "You made a decision and it turned out badly, but the reasoning was sound. How should you judge it?", options: ["As a good decision with a bad outcome", "As a bad decision", "As evidence your principles are wrong", "As bad luck with no lesson"], answer: 0, explanation: "Decisions and outcomes are separate. Judging by outcome alone teaches you to avoid risk rather than to reason." }, { question: "What should you do once the decision is made?", options: ["Communicate it plainly, along with the principle behind it", "Announce it without explanation", "Let people work it out", "Explain it only if challenged"], answer: 0, explanation: "The principle is what lets people predict the next decision, which is most of what leadership provides." }, { question: "You keep revisiting the same decision. What does that indicate?", options: ["The principle was never actually set", "You are being thorough", "The decision was wrong", "You need more information"], answer: 0, explanation: "Repeated reopening is the signature of a decision made on mood rather than on a rule." }, { question: "Which decision is best protected against pressure?", options: ["One where you named in advance what you would not do", "One made quickly and confidently", "One made with everyone's agreement", "One that can be reversed easily"], answer: 0, explanation: "A named limit is the part that holds when the room gets difficult." }] },
    { title: "Make Someone Else Better", why: "A large part of leadership is simply making the people around you more capable than they were.", lesson: "This is not encouragement and it is not doing their work for them. It is specific: teaching the thing you know, giving someone a real task rather than the safe scraps, telling them plainly what would make their work better, and putting their name to what they did in front of people who matter. It costs you something — time you could have spent on your own work, and sometimes credit. That is the point. A person who leaves everyone around them slightly more capable is doing something no amount of personal output can match.", keyIdea: "Teach it, hand over something real, say plainly what would improve it, and give the credit.", example: "You spend forty minutes teaching someone the thing you are fastest at, and lose an afternoon. Six months later there are two of you who can do it.", actionPrompt: "Make one person more capable today: teach them something, or give them a real task.", actionHint: "Give them something that actually matters. Safe scraps teach nothing and communicate what you think of them.", bonus: "Say their name in front of someone who matters, for something they did.", quiz: [{ question: "You are the only person who can do a particular task. What is the strongest move?", options: ["Teach someone else to do it", "Keep doing it, since you are fastest", "Document it in case you are away", "Do it and mention how hard it is"], answer: 0, explanation: "Being the only one is a bottleneck, and it is fragile. Teaching costs an afternoon and removes both problems." }, { question: "What kind of task should you hand to someone you want to develop?", options: ["One that actually matters", "One that is safe if they fail", "One you find boring", "One with no deadline"], answer: 0, explanation: "Safe scraps teach nothing and quietly tell the person what you think of them." }, { question: "Their work has a real problem in it. What is the strongest response?", options: ["Tell them plainly what would make it better", "Fix it yourself without mentioning it", "Say it is fine to keep them confident", "Mention it vaguely so they work it out"], answer: 0, explanation: "Specific correction is the useful thing. Silent fixing and vague hints both leave them where they were." }, { question: "Something they did went well and you were involved. Who should be named?", options: ["Them", "You, since you guided it", "Both, in equal measure", "Nobody, the work speaks for itself"], answer: 0, explanation: "Giving away credit costs you a little and buys something that cannot be bought directly." }, { question: "What is the real cost of developing someone?", options: ["Your time, and sometimes your credit", "Nothing, it is free", "Your position", "Their respect for you"], answer: 0, explanation: "The cost is what makes it a leadership act rather than a pleasant gesture." }, { question: "You taught someone and they now do it better than you. How should you read that?", options: ["As the intended outcome", "As a threat to your position", "As a sign you taught too much", "As luck"], answer: 0, explanation: "That is the whole aim. Treating it as a threat is how people quietly stop developing anyone." }, { question: "Which is developing someone rather than encouraging them?", options: ["Teaching them the specific thing you know how to do", "Telling them they are capable", "Praising their effort", "Believing in them"], answer: 0, explanation: "Encouragement is pleasant. Capability transfers only through the specific." }, { question: "How do you know this is working?", options: ["There are now more people who can do the thing", "People feel more positive", "You have more free time", "You are seen as helpful"], answer: 0, explanation: "Capability in the group is the measurable output, and it is the one that survives you leaving." }] },
    { title: "Say It So It Lands", why: "Most failures that get blamed on people are failures of communication that nobody noticed.", lesson: "When you are responsible for something involving others, being understood is your job, not theirs. Three things carry most of it: say what you actually mean rather than the softened version, be specific about who does what by when, and check that it landed instead of assuming. That last one takes ten seconds and prevents most of the problems that get called carelessness later. Softening is the common failure — a message so gentle that the person leaves genuinely unaware anything needs to change, and is then blamed for not changing it.", keyIdea: "Say the real thing, name who does what by when, and check it landed.", example: "You say the deck needs to be shorter, they nod, and nothing changes. You say it needs to be six slides by Thursday and it is.", actionPrompt: "Give one instruction or piece of feedback today that names who, what and by when — then check it landed.", actionHint: "Ask them to say back what they are going to do. Ten seconds, and it catches most of the misunderstandings.", bonus: "Take something you softened last week and say the real version of it.", quiz: [{ question: "You told someone their work needs to be shorter and nothing changed. What went wrong?", options: ["It was not specific enough to act on", "They ignored you", "They are not capable", "You should have said it more firmly"], answer: 0, explanation: "Shorter is an opinion. Six slides by Thursday is an instruction." }, { question: "Whose job is it to be understood?", options: ["The person giving the message", "The person receiving it", "Both equally", "Whoever has more time"], answer: 0, explanation: "If you are responsible for the outcome, being understood is part of that responsibility." }, { question: "What is the cheapest way to check a message landed?", options: ["Ask them to say back what they are going to do", "Ask whether they understood", "Send it in writing as well", "Repeat it a second time"], answer: 0, explanation: "Did you understand gets a yes almost every time. Saying it back reveals the gap." }, { question: "Why is softening a message a common failure?", options: ["The person leaves genuinely unaware anything needs to change", "It makes you seem weak", "It takes longer", "It is dishonest"], answer: 0, explanation: "The softened version often removes the actual content, and then the person is blamed for not acting on it." }, { question: "Which instruction is properly formed?", options: ["Can you send me the six-slide version by Thursday lunchtime", "Can you tighten this up a bit", "This needs work", "Have a think about the length"], answer: 0, explanation: "Who, what and by when. The others all require the person to guess." }, { question: "Something went wrong and you are about to call it carelessness. What should you check first?", options: ["Whether the instruction was actually specific", "Whether they were paying attention", "Whether they have done it before", "Whether they were busy"], answer: 0, explanation: "A large share of what gets called carelessness is a message that was never clear enough to follow." }, { question: "You need to give difficult feedback. What is the strongest approach?", options: ["Say the real thing plainly, and say what would fix it", "Soften it so it is easier to hear", "Mention it in passing", "Wait for a better moment"], answer: 0, explanation: "Plain and constructive is kinder than gentle and useless, because it can actually be acted on." }, { question: "What does being clear cost the person receiving it?", options: ["Less than being left to guess", "More discomfort than it is worth", "Their confidence", "Their goodwill"], answer: 0, explanation: "Ambiguity is the more expensive gift. People generally prefer knowing." }] },
    { title: "When the Mistake Was Your Team’s", why: "Owning a mistake made by someone you are responsible for is a different skill from owning your own.", lesson: "You already know how to handle a mistake of your own: name it, repair it, change one thing. This is harder. Someone you are responsible for got it wrong, it is visible, and there are two easy exits — name them publicly, or take the blame yourself and let it quietly become resentment. Both are worse than the honest version, which is: carry it outward, deal with it inward. In front of others you own the outcome without naming who. In private you address it directly with the person, including what will change. Blame in public buys you one afternoon and costs you the team.", keyIdea: "Carry it outward, deal with it inward. Own the outcome publicly, address it privately.", example: "Asked what went wrong, you say the outcome was yours and what you are changing. Afterwards you have a direct conversation with the person, and nobody outside ever hears their name.", actionPrompt: "Take something that went wrong in a group you are part of and own the outcome without naming anyone.", actionHint: "Outward: what went wrong and what changes. Inward: direct, specific, and not in front of anyone.", bonus: "Have the private conversation the same day, not a week later when it has grown.", quiz: [{ question: "Someone you are responsible for made a visible mistake. What do you say publicly?", options: ["That the outcome was yours, and what is changing", "Who made the mistake and what they did", "Nothing until you are asked", "That it was outside anyone's control"], answer: 0, explanation: "Carrying it outward is the job. Naming the person buys one afternoon and costs the group." }, { question: "What should happen privately?", options: ["A direct, specific conversation with the person, including what changes", "Nothing, since you took the blame", "A general reminder to everyone", "A note for their record"], answer: 0, explanation: "Taking the blame publicly and never addressing it privately is how resentment forms and the mistake recurs." }, { question: "You take the blame publicly and say nothing to the person. What is the likely result?", options: ["It happens again, and you resent them", "They will realise and improve", "The team respects you more", "Nothing, the matter is closed"], answer: 0, explanation: "Silent absorption is not generosity. It leaves the cause untouched and the feeling unresolved." }, { question: "How is this different from handling your own mistake?", options: ["You have to separate what is said publicly from what is said privately", "It is the same process", "It requires no repair", "It should be handled entirely in public"], answer: 0, explanation: "The two-channel structure is what makes this a distinct skill." }, { question: "When should the private conversation happen?", options: ["The same day", "After a week, once things have calmed", "At the next scheduled review", "Only if it happens again"], answer: 0, explanation: "Delay lets it grow and lets the specifics fade. Same day is direct and smaller." }, { question: "Someone asks you directly who was responsible. What is the strongest answer?", options: ["That you are responsible for the outcome, and it is being addressed", "Name the person, since they asked", "Refuse to answer", "Say you do not know"], answer: 0, explanation: "You can be honest that it is being handled without handing over a name." }, { question: "What does naming someone publicly actually cost?", options: ["The willingness of everyone else to take a risk", "Only that person's feelings", "Nothing if it is true", "Your relationship with that one person"], answer: 0, explanation: "Everyone watching learns what happens when something goes wrong, and adjusts how much they attempt." }, { question: "The mistake was genuinely serious and repeated. What changes?", options: ["The private conversation gets more direct, not more public", "It becomes appropriate to name them", "You should escalate publicly", "You should stop covering for them entirely"], answer: 0, explanation: "Seriousness raises the directness of the private handling. It does not convert it into a public matter." }] },
    { title: "Hand It Over Properly", why: "Doing everything yourself is not dedication; it is a bottleneck with a good reputation.", lesson: "There are two ways to hand work over badly. One is to dump it: no context, no standard, no deadline, and then irritation when it comes back wrong. The other is to hover: hand it over and then check every hour, which is slower than doing it yourself and communicates that you never really let go. Doing it properly takes five minutes at the start — the outcome you need, the standard it has to meet, when it is needed, what they can decide themselves, and when to come back to you. Then leave it alone until that point.", keyIdea: "Give the outcome, the standard, the deadline and the decision boundary. Then leave it alone.", example: "You spend five minutes explaining what done looks like and what they can decide without asking. It comes back right, and you did not touch it.", actionPrompt: "Hand one piece of work over properly today, with the outcome, standard, deadline and decision boundary.", actionHint: "Say what they can decide without you. That one line prevents most of the coming back.", bonus: "Do not check on it before the point you agreed.", quiz: [{ question: "You hand something over and then check on it every hour. What is the effect?", options: ["It is slower than doing it yourself and tells them you never let go", "It ensures quality", "It shows you are engaged", "It helps them learn"], answer: 0, explanation: "Hovering removes the benefit of delegating and damages the relationship at the same time." }, { question: "What are the four things to give when handing work over?", options: ["The outcome, the standard, the deadline, and what they can decide alone", "The task and the deadline", "The instructions and your phone number", "The task, and freedom to do it their way"], answer: 0, explanation: "The decision boundary is the one most often left out, and it causes most of the coming back." }, { question: "It comes back and it is wrong. What should you check first?", options: ["Whether you actually said what done looked like", "Whether they were paying attention", "Whether they are capable of the task", "Whether they had enough time"], answer: 0, explanation: "Most wrong outcomes trace back to an unstated standard rather than to the person." }, { question: "What does doing everything yourself actually make you?", options: ["A bottleneck", "Dedicated", "Reliable", "The safest option"], answer: 0, explanation: "The work stops when you do, which is a structural problem regardless of how well you do it." }, { question: "When should you next look at the work?", options: ["At the point you both agreed", "Whenever you feel like checking", "Only when it is finished", "Every day at the same time"], answer: 0, explanation: "An agreed checkpoint gives them room and gives you a defined moment to correct course." }, { question: "You are worried they will not do it as well as you. What is the honest response?", options: ["Accept a somewhat different result, and be specific about the standard that matters", "Do it yourself", "Hand over only the easy parts", "Check it constantly"], answer: 0, explanation: "It will be done differently. Naming which parts of the standard are non-negotiable is the workable middle." }, { question: "Which is dumping rather than delegating?", options: ["Sending the task with no context or standard", "Explaining what done looks like", "Agreeing a checkpoint", "Saying what they can decide alone"], answer: 0, explanation: "Dumping is fast for you and expensive for everyone, and the irritation afterwards is unearned." }, { question: "What is the long-term return on delegating properly?", options: ["More people who can do the work without you", "More free time immediately", "A reputation for being easy to work with", "Less responsibility"], answer: 0, explanation: "Capability spreads, which is the only way anything continues when you are not there." }] },
    { title: "Be Fair When It Costs You", why: "Fairness that costs you nothing tells nobody anything about you.", lesson: "Everybody is fair when fairness is convenient. The moment that actually reveals a person is when the honest call goes against their own interest: admitting the other side was right, giving up an advantage you were handed by mistake, applying the same rule to a friend that you applied to someone you do not like. This is where amanah becomes concrete rather than a word. People are watching more closely than you think, and one visible instance of costly fairness does more for how you are trusted than years of talking about integrity.", keyIdea: "The honest call that goes against you is the one that shows who you are.", example: "The marks came back and you were given more than you earned. You say so, lose the marks, and something more valuable is established.", actionPrompt: "Make one fair call today that costs you something.", actionHint: "Watch for the moment you notice an advantage you were not entitled to. That is the test arriving.", bonus: "Apply the same standard to someone you like as you would to someone you do not.", quiz: [{ question: "You were given more credit than you earned and nobody has noticed. What is the strongest move?", options: ["Say so, and give it back", "Keep quiet, since it was not your mistake", "Mention it only if someone asks", "Keep it and be generous elsewhere"], answer: 0, explanation: "The unnoticed advantage is exactly where costly fairness is tested." }, { question: "A friend and someone you dislike break the same rule. What does fairness require?", options: ["The same response to both", "Leniency for the friend", "Strictness with both to prove impartiality", "Avoiding the issue entirely"], answer: 0, explanation: "Consistency across people you feel differently about is the whole substance of the principle." }, { question: "Why does fairness that costs you nothing reveal so little?", options: ["Everybody manages it when it is convenient", "It is still valuable", "It is usually insincere", "It happens too rarely to observe"], answer: 0, explanation: "Only the costly instances distinguish anyone, which is why they carry so much weight." }, { question: "The other side of an argument turns out to be right. What is the strongest response?", options: ["Say so plainly", "Concede quietly without acknowledging it", "Find a partial point you were right about", "Move the conversation on"], answer: 0, explanation: "Saying it plainly costs a moment and settles something about you that arguing never could." }, { question: "You make a costly fair call and nobody notices. What is the accurate reading?", options: ["It still counts, and people notice more than you think", "It was wasted", "You should mention it", "It only matters if it is seen"], answer: 0, explanation: "Conduct when unobserved is the actual thing. And in practice, these are noticed far more often than people expect." }, { question: "What is amanah in practical terms here?", options: ["Handling what you were trusted with as though the owner were watching", "A feeling of responsibility", "Following the rules carefully", "Being honest when asked directly"], answer: 0, explanation: "It is a standard of handling, and it applies most when nobody is checking." }, { question: "You benefit from an unfair system you did not create. What does this day suggest?", options: ["Name it where you can, and do not use the advantage silently", "It is not your responsibility", "You should refuse all benefit from it", "You should feel guilty about it"], answer: 0, explanation: "You did not create it and you do have choices inside it. Silence and self-punishment are both easier than those choices." }, { question: "How much does one visible instance of costly fairness affect trust?", options: ["More than years of talking about integrity", "Very little", "Only among people directly involved", "It depends how large the cost was"], answer: 0, explanation: "A single demonstrated instance carries evidential weight that no amount of stated values does." }] },
    { title: "Solve It With the Person", why: "A disagreement handled well leaves the relationship stronger than it was before it started.", lesson: "When something goes wrong between two people, the instinct is to establish who was at fault. That produces a winner, a loser, and a slightly worse relationship. The alternative is to put the problem in front of both of you rather than between you: what actually happened, what each of you needed, and what you will do differently. Go to the person directly rather than around them, do it early while it is small, and separate the problem from the person completely. The aim is not to win the exchange. It is that the thing works next time and you can still work together.", keyIdea: "Put the problem in front of both of you, not between you. Go direct, go early.", example: "Instead of establishing whose fault the missed handover was, you both look at where it broke and change the point it broke at.", actionPrompt: "Take one unresolved friction with someone and go to them directly to solve it together.", actionHint: "Open with what happened and what you need, not with what they did wrong.", bonus: "Agree one specific change, so the conversation produces something rather than just clearing the air.", quiz: [{ question: "Something went wrong between you and a colleague. What is the strongest opening?", options: ["What happened, and what you each needed", "Whose fault it was", "How it made you feel", "What they should have done"], answer: 0, explanation: "Starting with fault produces a winner and a loser. Starting with the mechanism produces a fix." }, { question: "You have a problem with someone. Who should you speak to first?", options: ["Them, directly", "Someone else, to check you are being reasonable", "Their manager", "A mutual friend"], answer: 0, explanation: "Going around a person before going to them almost always makes the problem larger." }, { question: "When is the best time to raise a friction?", options: ["Early, while it is still small", "Once you are certain it is a pattern", "When you are calm enough to be sure", "At a scheduled review"], answer: 0, explanation: "Small and early is a conversation. Large and late is a confrontation." }, { question: "What should the conversation produce?", options: ["One specific change", "A clearer understanding of each other", "An apology", "Agreement about what happened"], answer: 0, explanation: "Understanding without a change tends to leave you having the same conversation again." }, { question: "The conversation is drifting into who was at fault. What is the strongest move?", options: ["Redirect to what you both do differently next time", "Establish the facts first", "Concede to end it", "Postpone the conversation"], answer: 0, explanation: "Fault is rarely resolvable and rarely useful. The forward question is the one that has an answer." }, { question: "They react defensively as soon as you raise it. What does that usually indicate?", options: ["The opening was about them rather than the problem", "They are unreasonable", "The problem is worse than you thought", "You should not have raised it"], answer: 0, explanation: "Defensiveness is usually a response to being the subject rather than the situation being the subject." }, { question: "What does a well-handled disagreement leave behind?", options: ["A stronger relationship than before it started", "A resolution and some awkwardness", "A record of who was right", "An agreement to avoid the topic"], answer: 0, explanation: "Handled properly, it is evidence to both of you that problems can be raised safely." }, { question: "You are genuinely in the right and they are not. Does that change the approach?", options: ["No — being right and being effective are different things", "Yes, you should establish that first", "Yes, you should be firmer", "Yes, they should apologise before anything else"], answer: 0, explanation: "Being right is not the difficulty. Getting the thing to work next time still requires the same conversation." }] },
    { title: "Your Example Speaks", why: "People copy what you do under pressure, not what you say when things are calm.", lesson: "Everything in this section reduces to one thing: what you actually do is the standard, whatever you announce. The people around you are reading how you behave when you are tired, when you are wrong, when the honest option is expensive, and when nobody is watching. That is what they will copy, and they will copy it more accurately than any instruction you give. It is an uncomfortable amount of influence and you have it whether or not you wanted it. The practical response is simple: pick the thing you most want to be true of the people around you, and be that thing consistently.", keyIdea: "You set the standard by what you do under pressure. Choose one thing and be it consistently.", example: "You never talk about punctuality. You are simply always there, and within a term the people around you are too.", actionPrompt: "Name the one behaviour you most want in the people around you, and demonstrate it consistently today.", actionHint: "Choose something visible and repeatable, and expect it to take months rather than days.", bonus: "Ask someone you trust which of your behaviours they think you are actually modelling.", quiz: [{ question: "You tell people to be on time and you are frequently late. What standard is set?", options: ["The one you demonstrate", "The one you stated", "A mixture of both", "None, until you enforce it"], answer: 0, explanation: "Behaviour under pressure is read as the real standard, and it is copied far more accurately than instructions." }, { question: "When are people most closely reading your behaviour?", options: ["When you are tired, wrong, or the honest option is expensive", "When you are giving instructions", "In formal settings", "When you are performing well"], answer: 0, explanation: "Difficult moments carry the information, because that is when a standard is either real or not." }, { question: "Which is the strongest way to raise the standard around you?", options: ["Choose one behaviour and be it consistently", "Explain the standard clearly and often", "Correct people when they fall short", "Set out written expectations"], answer: 0, explanation: "Consistency in one visible thing changes behaviour faster than explanation or correction." }, { question: "How long should you expect this to take?", options: ["Months", "Days", "A single clear conversation", "It happens immediately"], answer: 0, explanation: "Modelling works through repetition, and the timescale is one of the reasons people give up on it." }, { question: "You are having a bad day and behave poorly. What is the strongest response?", options: ["Acknowledge it plainly, which also models something", "Hope nobody noticed", "Explain the circumstances", "Be extra good tomorrow"], answer: 0, explanation: "How you handle your own lapse is itself modelling, and often the more useful lesson." }, { question: "Do you have this influence only if you have a formal role?", options: ["No — you have it whether or not you wanted it", "Yes, it requires authority", "Only with people junior to you", "Only in groups you lead"], answer: 0, explanation: "Anyone consistently present is being read. The influence is not optional." }, { question: "Which behaviour is worth choosing to model?", options: ["Something visible and repeatable", "Something impressive", "Something you already do naturally", "Something nobody else does"], answer: 0, explanation: "Visible and repeatable is what gets copied. Impressive but rare does not transmit." }, { question: "How does this close the leadership section?", options: ["Everything before it is only real if it shows in your behaviour", "It is a separate final topic", "It replaces the earlier lessons", "It applies only to experienced leaders"], answer: 0, explanation: "Responsibility, decisions, developing people, fairness — all of them are transmitted by demonstration or not at all." }] },
  ],
  [
    { title: "Define a Good Life", why: "If you never define what a good life looks like for you, you will spend years chasing someone else's version of it.", lesson: "Most people never write this down, and so they run on a definition absorbed from whoever was nearby — family, friends, whatever their feed rewards. It is worth being deliberate, because the definition decides what you say yes to for the next decade. Ask what you want to be true in five years about your Deen, your character, the people close to you, your health, your work and what you contribute. Be honest rather than impressive: the version you would write if nobody were reading is the only one that will actually guide a decision.", keyIdea: "Write what a good life means to you, honestly, before it gets decided for you by default.", example: "You realise the thing you have been working toward is something you absorbed rather than chose, and one line of writing changes what you do next year.", actionPrompt: "Write down what a good life looks like for you, across Deen, character, people, health and work.", actionHint: "Write the version you would write if nobody were going to read it. The impressive version is useless.", bonus: "Read it back in a week and cross out anything that was written for an audience.", quiz: [{ question: "You have never written down what a good life means to you. What happens by default?", options: ["You run on a definition absorbed from whoever was nearby", "Nothing, most people manage fine", "You work it out gradually through experience", "You follow your instincts, which is honest"], answer: 0, explanation: "The absorbed definition still operates. The only question is whether you ever looked at it." }, { question: "Which version of the definition is worth writing?", options: ["The one you would write if nobody were reading", "The one that would impress people you respect", "The one that sounds achievable", "The one your family would approve of"], answer: 0, explanation: "A definition written for an audience cannot guide a decision made in private." }, { question: "What does the definition actually decide?", options: ["What you say yes to over the next decade", "How happy you feel", "Whether you achieve your goals", "How others see you"], answer: 0, explanation: "It functions as a filter on opportunities, which is where its practical force lies." }, { question: "You read yours back and half of it was written to sound good. What now?", options: ["Cross that half out", "Keep it and work toward it", "Rewrite it entirely", "Show it to someone for their view"], answer: 0, explanation: "The audience-facing half will not survive a real decision, so removing it makes the rest usable." }, { question: "Someone says defining this is limiting. What is the accurate reply?", options: ["The undefined version is more limiting, because it was chosen by other people", "They are right", "Definitions should be revised, not avoided", "It depends on the person"], answer: 0, explanation: "The choice is not between a definition and freedom. It is between a chosen definition and an inherited one." }, { question: "How specific should it be?", options: ["Specific enough to rule things out", "As broad as possible to stay open", "A single sentence", "A detailed plan for each area"], answer: 0, explanation: "If it rules nothing out, it is not doing any work." }, { question: "Your definition changes significantly in two years. What does that mean?", options: ["It should be revisited, which is normal", "You wrote it badly", "You are inconsistent", "You should have waited to write it"], answer: 0, explanation: "A definition is a working document. Waiting until you are certain means never writing one." }, { question: "Which area do people most often leave out?", options: ["The people close to them", "Their work", "Their health", "Their ambitions"], answer: 0, explanation: "Career and achievement tend to be written first and relationships last, which is usually the reverse of what matters later." }] },
    { title: "Set a Goal That Means Something", why: "A goal that is not connected to your definition of a good life is just something you copied.", lesson: "There is a difference between a target and a goal that means something. A target is a number you adopted because it sounded like progress. A meaningful goal comes from the definition you wrote yesterday, has a specific outcome you could hold up and point at, and has a date. The date is what turns intention into something that can be missed, which is uncomfortable and necessary. Set one, at a size where a year of ordinary effort would reach it — not a fantasy, and not something you could do next week.", keyIdea: "One goal, from your own definition, with a specific outcome and a date.", example: "Get better at Arabic becomes: read a page of tafsir without a dictionary by Ramadan, which is checkable and dated.", actionPrompt: "Set one meaningful goal with a specific outcome and a date, drawn from what you wrote yesterday.", actionHint: "Ask which line of your definition it serves. If it serves none, it is a target you copied.", bonus: "Write the first three steps under it and put a date on the first one.", quiz: [{ question: "Which is a meaningful goal rather than a copied target?", options: ["Read a page of tafsir without a dictionary by Ramadan", "Get better at Arabic", "Read more religious books this year", "Be more knowledgeable"], answer: 0, explanation: "A specific outcome with a date is checkable. The others cannot be missed, so they cannot be met either." }, { question: "What is the test for whether a goal means something to you?", options: ["Which line of your own definition it serves", "Whether it is difficult", "Whether other people respect it", "Whether you can achieve it"], answer: 0, explanation: "A goal that serves nothing in your definition was adopted from somewhere else." }, { question: "Why does the goal need a date?", options: ["Without one there is no moment at which it was missed", "It creates useful pressure", "It makes planning easier", "It shows commitment"], answer: 0, explanation: "Undated goals do not fail; they just quietly persist, which is why they never resolve." }, { question: "How ambitious should it be?", options: ["Reachable by a year of ordinary effort", "As ambitious as possible", "Achievable within a month", "Whatever you can commit to today"], answer: 0, explanation: "Fantasy goals and trivial ones both fail to change what you do this week." }, { question: "You set a goal and realise it serves none of your definition. What now?", options: ["Drop it, or find which line it actually serves", "Keep it, since you committed", "Add it to your definition", "Pursue it anyway and see"], answer: 0, explanation: "This is the check working. Dropping a copied target early is cheap." }, { question: "How many meaningful goals should you set at once?", options: ["One", "One for each area of your definition", "Three to five", "As many as you can track"], answer: 0, explanation: "One receives real attention. A set of them mostly generates a feeling of having planned." }, { question: "What should go immediately under the goal?", options: ["The first three steps, with a date on the first", "A detailed plan for the whole year", "A list of resources you need", "A statement of why it matters"], answer: 0, explanation: "A dated first step is what makes the goal start this week rather than next quarter." }, { question: "You are halfway to the date and clearly behind. What is the strongest response?", options: ["Adjust the goal or the plan deliberately, and say which", "Push harder and hope", "Abandon it", "Extend the date quietly"], answer: 0, explanation: "A deliberate adjustment keeps the goal honest. A quiet extension removes the only thing making it real." }] },
    { title: "Ten Years, Roughly", why: "You cannot plan ten years, but you can pick a direction, and a direction changes what you do this month.", lesson: "Long-term planning fails because people try to specify it. What works is much rougher: a description of the kind of person you would like to be in ten years and the kind of life around them — the Deen, the character, the people, the work. Not a schedule, not milestones, just a direction with enough shape to tell you whether a decision this year points toward it or away. Most people wildly overestimate a year and badly underestimate ten, which is why the ten-year view makes ordinary consistent effort look far more powerful than it feels day to day.", keyIdea: "Pick a rough ten-year direction, not a plan. It only has to make this year's decisions clearer.", example: "You cannot plan the decade, but knowing you want to be someone who teaches makes this year's choice between two jobs obvious.", actionPrompt: "Write a rough description of where you want to be in ten years, and check one current decision against it.", actionHint: "A direction, not a schedule. It only needs to be specific enough to rule a decision in or out.", bonus: "Identify one thing you are doing now that clearly does not point that way.", quiz: [{ question: "Why do detailed ten-year plans usually fail?", options: ["They specify what cannot be known, so they are abandoned early", "People lack discipline", "Ten years is too long to care about", "Circumstances always change"], answer: 0, explanation: "The failure is in the precision. A rough direction survives what a schedule cannot." }, { question: "What does the ten-year view actually need to do?", options: ["Make this year's decisions clearer", "Predict where you will be", "Set milestones for each year", "Motivate you daily"], answer: 0, explanation: "Its whole practical function is filtering the decisions in front of you now." }, { question: "Most people get which of these wrong?", options: ["They overestimate one year and underestimate ten", "They overestimate both", "They underestimate both", "They estimate one year well and ten badly upward"], answer: 0, explanation: "The asymmetry is why steady effort looks unimpressive weekly and enormous across a decade." }, { question: "You are choosing between two options and neither obviously points your way. What helps?", options: ["Ask which one keeps the direction open", "Choose the one with the better short-term outcome", "Choose the harder one", "Delay the decision"], answer: 0, explanation: "When neither advances the direction, preserving optionality toward it is the next best filter." }, { question: "How specific should the ten-year description be?", options: ["Specific enough to rule a decision in or out", "As detailed as possible", "A single word", "Broken into yearly targets"], answer: 0, explanation: "It is a filter. Anything that cannot filter is decoration." }, { question: "Your direction changes after three years. What does that mean?", options: ["It did its job for three years and now gets revised", "You wasted three years", "You should not have written one", "You were not committed enough"], answer: 0, explanation: "A direction that guided three years of decisions was useful, whether or not it stayed the same." }, { question: "What is the strongest thing to do immediately after writing it?", options: ["Find one thing you are currently doing that does not point that way", "Make a plan for each year", "Tell people about it", "Set goals for all ten years"], answer: 0, explanation: "The direction only becomes real when it removes something from your current life." }, { question: "How does this relate to the goal you set yesterday?", options: ["The goal should be a step in this direction", "They are independent", "The direction replaces the goal", "The goal should be larger than the direction"], answer: 0, explanation: "The chain runs definition, direction, goal, first step — and a goal outside the direction is a distraction." }] },
    { title: "Say No to Keep the Yes", why: "Every commitment you take on is taken from something you already said mattered.", lesson: "By this point in the course you have a definition, a direction and a goal. The threat to all three is not laziness; it is the accumulation of reasonable-sounding commitments, each fine on its own, that collectively leave nothing for what you actually chose. Protecting the choice means saying no to things that are genuinely good, which is much harder than refusing things that are obviously bad. Two habits carry it: decide in advance how much of your week is already spoken for, and answer with a clear no rather than a maybe that costs you the thing twice.", keyIdea: "Protecting your yes means declining good things. Decide the limit before you are asked.", example: "You want to say yes to all four. You have room for one, so you say so plainly, and the one you chose actually gets done.", actionPrompt: "Decline one reasonable request today, clearly, to protect something you already committed to.", actionHint: "No explanation needed. A short no now is kinder than a maybe that becomes a no later.", bonus: "Write down what your week is already committed to, so the next request meets a number rather than a mood.", quiz: [{ question: "Four good opportunities arrive and you have room for one. What is the strongest response?", options: ["Say yes to one and a clear no to the others", "Say yes to all and manage somehow", "Say maybe to keep options open", "Take the most impressive one and ignore the rest"], answer: 0, explanation: "A clear no now costs less than a maybe that becomes a no later, and lets the chosen one actually get done." }, { question: "What is the real threat to a goal you have set?", options: ["Accumulated reasonable commitments", "Laziness", "Lack of ability", "Bad luck"], answer: 0, explanation: "Each one is defensible on its own, which is exactly why the total goes unnoticed until nothing is left." }, { question: "Why is saying no to good things harder than refusing bad ones?", options: ["There is no obvious reason to decline, so it feels ungenerous", "It is not harder", "Good things are rarer", "You have to explain yourself"], answer: 0, explanation: "The absence of a bad reason is what makes the refusal feel unjustified, and why the limit has to be set in advance." }, { question: "What makes a no easier to give?", options: ["Knowing in advance how much of your week is already committed", "Having a good excuse", "Being asked at a good time", "Practising what to say"], answer: 0, explanation: "A number decides it. Without one, every request is judged on how you feel that day." }, { question: "Someone asks and you say maybe. What have you done?", options: ["Committed to deciding twice and probably disappointing them later", "Kept your options open sensibly", "Bought yourself useful time", "Been appropriately polite"], answer: 0, explanation: "A maybe holds the space without the commitment, which is the worst of both." }, { question: "How much explanation does a no require?", options: ["Very little — a clear short answer is more respectful", "A full account of your reasons", "Enough that they do not take it personally", "An alternative you can offer instead"], answer: 0, explanation: "Long justifications invite negotiation and imply the decision is open." }, { question: "You said yes to everything this term and finished nothing you chose. What is the lesson?", options: ["The yes to your own goal was spent on other people's", "You need to work faster", "You should choose easier goals", "You need better time management"], answer: 0, explanation: "It is an allocation problem, not a productivity one." }, { question: "What is the relationship between this and the promise-keeping you learned earlier?", options: ["Fewer commitments kept beats many made", "They are unrelated", "This one is about other people only", "That one was about small things"], answer: 0, explanation: "The same principle applied outward: your capacity is what makes a promise credible." }] },
    { title: "Keep Learning After the Course", why: "The value of a hundred days is decided by what happens on day one hundred and one.", lesson: "Courses end and people revert, because the structure was external — someone else set the day, the lesson and the check. What replaces it has to be yours, and it should be modest: something you are learning, some way of practising it, and someone who will tell you the truth about your work. That is the whole apparatus. The largest risk now is not that you will forget the material. It is that you will stop being someone who is in the middle of learning something, and that state is far harder to re-enter than it is to maintain.", keyIdea: "Set up what replaces the course: something to learn, a way to practise, someone honest about your work.", example: "The day after the course ends you already know what you are working on next, so there is no gap to fall into.", actionPrompt: "Decide now what you are learning next and how you will practise it once the course ends.", actionHint: "Name the thing, the weekly practice, and the person who will be honest about the result.", bonus: "Arrange the first practice session before the course finishes.", quiz: [{ question: "The course ends in a week. What is the strongest thing to have ready?", options: ["The next thing you are learning and how you will practise it", "A review of everything you covered", "A break before starting anything new", "A record of what you completed"], answer: 0, explanation: "The gap after a structure ends is where people revert. Having the next thing ready removes the gap." }, { question: "Why do people revert after finishing a course?", options: ["The structure was external and nothing replaced it", "They did not learn the material", "They lack motivation", "The material was not useful"], answer: 0, explanation: "Someone else was setting the day, the lesson and the check. That role has to be filled by something." }, { question: "What are the three parts of the replacement?", options: ["Something to learn, a way to practise, someone honest about your work", "A plan, a schedule and a deadline", "A book, a course and a certificate", "A goal, a target and a reward"], answer: 0, explanation: "The honest reader is the part most often left out, and it is what stops you drifting into comfortable practice." }, { question: "What is the largest actual risk after day one hundred?", options: ["You stop being someone in the middle of learning something", "You forget the material", "You lose your habits", "You lose interest in improvement"], answer: 0, explanation: "The state is harder to re-enter than to maintain, which is why the handover matters more than revision." }, { question: "How ambitious should the next thing be?", options: ["Modest enough to still be running in three months", "As large as your ambition", "Small enough to finish quickly", "Whatever is most in demand"], answer: 0, explanation: "The same durability test that governed everything else in the course applies here too." }, { question: "Who should be the person who tells you the truth about your work?", options: ["Someone whose judgement you trust and who will be honest", "Someone who is always encouraging", "Someone more skilled than you in every way", "Anyone willing to look"], answer: 0, explanation: "Honesty is the requirement. Encouragement alone leaves you exactly where you are." }, { question: "When should the first practice session be arranged?", options: ["Before the course finishes", "In the week after it finishes", "Once you have had a break", "When you feel ready"], answer: 0, explanation: "Arranging it while the structure still exists is what carries you across the gap." }, { question: "Three months after finishing, someone asks what you are working on and you have no answer. What went wrong?", options: ["Nothing replaced the structure when it ended", "The course was too short", "You did not learn the material well enough", "You lost interest, which is natural"], answer: 0, explanation: "The gap is structural. Naming the next thing before the ending is what prevents it." }] },
    { title: "Work Worth Doing", why: "Work occupies most of your waking life, so what it is for is not a small question.", lesson: "Two failures are common. The first is treating work as only a way to get money, which makes forty years feel like something to be endured. The second is treating it as the whole meaning of your life, which quietly makes your worth conditional on your output and leaves nothing when the output stops. The honest middle is that work is a place where you are useful to people, where your character shows, and where what you earn should be earned cleanly. It does not have to be your passion. It does have to be something you can do without compromising who you are.", keyIdea: "Work is where you are useful and where your character shows. It need not be your passion.", example: "The job is unremarkable and you do it properly, treat people well in it, and earn cleanly. That is not a compromise; it is most of the answer.", actionPrompt: "Write down what your work is for, beyond the money, and one thing you would not compromise in it.", actionHint: "Two lines: who it is useful to, and what you will not do to keep it.", bonus: "Name one thing you could do this month to make your work more useful to the people it serves.", quiz: [{ question: "Someone treats their job purely as a way to get money. What is the likely cost?", options: ["Forty years of their life become something to endure", "Nothing, it is a practical view", "They will earn less", "They will be less competent"], answer: 0, explanation: "Time spent is the cost. It is a very large fraction of a life to write off as endurance." }, { question: "Someone treats their work as the entire meaning of their life. What is the risk?", options: ["Their worth becomes conditional on output", "They will burn out from long hours", "They will neglect other things", "Nothing, dedication is good"], answer: 0, explanation: "The output eventually changes, and a worth built on it changes with it." }, { question: "Does work have to be your passion?", options: ["No — usefulness, character and clean earning are the substance", "Yes, otherwise it is wasted time", "Yes, if you want to be good at it", "Only if you are ambitious"], answer: 0, explanation: "The passion requirement makes ordinary decent work look like failure, which is both false and discouraging." }, { question: "You are offered more money for work that requires you to be dishonest. What does this day say?", options: ["How you earn is part of what the work is for", "Take it and be honest elsewhere", "It depends how dishonest", "Money is a legitimate primary consideration"], answer: 0, explanation: "Clean earning is not an optional extra on top of the work; it is part of what makes it worth doing." }, { question: "Your work is unremarkable and you do it well and treat people properly. How should you read that?", options: ["That is most of the answer, not a compromise", "You should aim higher", "It is acceptable for now", "You are settling"], answer: 0, explanation: "Doing ordinary work properly and treating people well is a substantial answer to the question." }, { question: "What is the most useful question to ask about your work?", options: ["Who is it useful to", "How much does it pay", "How does it look to others", "How much do I enjoy it"], answer: 0, explanation: "Usefulness to someone is what makes the hours mean something beyond the transaction." }, { question: "You cannot change your job right now. What is still available?", options: ["Making it more useful to the people it serves", "Nothing until you can leave", "Reducing your effort until you can", "Finding meaning outside work only"], answer: 0, explanation: "The character and usefulness of how you work are available immediately and independently of the role." }, { question: "What is the one line worth writing down today?", options: ["What you will not do to keep the work", "How much you want to earn", "Where you want to be in five years", "What you enjoy most about it"], answer: 0, explanation: "A named limit is what protects you in the moment when it is tested, which is rarely a moment with time to think." }] },
    { title: "Keep People Over Years", why: "Friendships do not usually end in an argument; they end because nobody made the effort.", lesson: "You learned earlier how to build relationships. This is the harder and less discussed part: keeping them across years when there is no shared classroom, workplace or street to do the work for you. Proximity does almost all of the maintenance when you are young, and then it disappears, and the friendships that survive are the ones somebody deliberately maintained. It is unglamorous — a message for no reason, remembering something they told you, being the one who arranges it again after the last three attempts fell through. Somebody has to be that person. It may as well be you.", keyIdea: "Once proximity goes, relationships survive only on deliberate effort. Be the one who makes it.", example: "You are the one who arranges it every time, and it is slightly unfair, and you still have those friends in ten years.", actionPrompt: "Contact one person today that you have not spoken to in months, for no reason at all.", actionHint: "No occasion needed. Remembering something specific they told you does most of the work.", bonus: "Arrange something with someone whose last three attempts to meet fell through.", quiz: [{ question: "A close friendship has gone quiet over two years with no argument. What usually happened?", options: ["Proximity ended and nobody replaced it with effort", "One of you lost interest", "You grew apart naturally", "Something was said that was not resolved"], answer: 0, explanation: "Most fading is structural rather than emotional, and it is reversible by one person deciding to act." }, { question: "You always seem to be the one arranging things. What is the accurate reading?", options: ["Somebody has to be, and the friendships survive because you are", "You are being taken advantage of", "They do not value the friendship", "You should stop and see what happens"], answer: 0, explanation: "The effort is genuinely uneven and it is also what keeps the relationship in existence." }, { question: "What makes a message for no reason effective?", options: ["Referring to something specific they told you", "Its length", "Choosing the right moment", "Asking how they are"], answer: 0, explanation: "Specific recall is evidence that you were listening, which is what the message actually communicates." }, { question: "You have not spoken in two years and feel awkward reaching out. What is the strongest move?", options: ["Reach out anyway, without addressing the gap at length", "Wait for a natural occasion", "Apologise for the silence first", "Leave it, since too much time has passed"], answer: 0, explanation: "The awkwardness is almost entirely on your side, and a long apology makes the gap the subject." }, { question: "Three attempts to meet have fallen through. What now?", options: ["Arrange a fourth", "Take the hint", "Ask why they keep cancelling", "Wait for them to arrange it"], answer: 0, explanation: "Cancellations are usually about their circumstances. The fourth attempt is what distinguishes maintained friendships." }, { question: "What changes about friendship after school or university?", options: ["The structure that maintained it disappears", "People become less interested", "There is less to talk about", "Friendships matter less"], answer: 0, explanation: "The shared setting was doing the work invisibly, and nothing replaces it automatically." }, { question: "How does this differ from the earlier lesson on building relationships?", options: ["That was starting them; this is keeping them without a shared setting", "It is the same skill", "This one is about family only", "Building is harder"], answer: 0, explanation: "Starting and maintaining fail for different reasons and need different habits." }, { question: "Which is the better investment of an hour?", options: ["Contacting three people you have not spoken to in months", "Meeting someone new", "Posting something that reaches many people", "Reading about relationships"], answer: 0, explanation: "Existing relationships have years of accumulated value and are lost cheaply through neglect." }] },
    { title: "Make a Personal Code", why: "A code decided in advance is what you use in the moment when there is no time to think.", lesson: "The decisions that define a person are rarely made calmly. They arrive tired, in public, with someone waiting for an answer. A personal code is a small set of lines you have decided beforehand — things you will always do and things you will not do under any circumstances — so that in the moment you are recalling a decision rather than making one. Keep it short enough to remember without looking: five or six lines. Make them specific enough to be broken, because a code you could never fail is not a code, it is a mood.", keyIdea: "Five or six specific lines, decided in advance, so the moment is recall rather than decision.", example: "One of yours is that you do not agree to things in the room. It has saved you from three commitments you would have regretted.", actionPrompt: "Write your personal code: five or six specific lines you will hold to.", actionHint: "Specific enough to be broken. If you could never fail it, it is not a rule.", bonus: "Read it back in a month and change any line that has never once been tested.", quiz: [{ question: "When are the decisions that define you usually made?", options: ["Tired, in public, with someone waiting", "After careful reflection", "In moments of crisis only", "When you have time to weigh things"], answer: 0, explanation: "That is precisely why the deciding has to happen in advance." }, { question: "How long should a personal code be?", options: ["Five or six lines you can remember without looking", "As comprehensive as possible", "One guiding principle", "A page for each area of life"], answer: 0, explanation: "You have to be able to recall it under pressure, which caps the length hard." }, { question: "Which is a usable line in a code?", options: ["I do not agree to anything in the room", "I will always be a good person", "I will try to be honest", "I value integrity"], answer: 0, explanation: "Only the first is specific enough to be applied and specific enough to be broken." }, { question: "A line in your code has never once been tested. What does that suggest?", options: ["It may be a preference rather than a rule", "It is working well", "You should keep it as a reminder", "You should make it stricter"], answer: 0, explanation: "An untested line is usually one that costs nothing, which means it is not doing the work of a code." }, { question: "You broke one of your lines. What is the strongest response?", options: ["Repair what you can, and look at what made it easy to break", "Remove the line", "Rewrite the code entirely", "Treat the code as unrealistic"], answer: 0, explanation: "The break is information about conditions. Removing the line solves the discomfort rather than the problem." }, { question: "What is the practical function of the code in a difficult moment?", options: ["You recall a decision rather than making one", "It reminds you of your values", "It gives you something to say", "It makes you feel more confident"], answer: 0, explanation: "Recall is fast and pressure-resistant. Deciding under pressure is neither." }, { question: "Should the code change over time?", options: ["Yes, deliberately, when you have evidence", "No, that would defeat the purpose", "Only after major life events", "It should be rewritten yearly"], answer: 0, explanation: "Deliberate revision on evidence is different from quietly relaxing a line that became inconvenient." }, { question: "Which line is most valuable in a code?", options: ["The one that will cost you something when it is tested", "The one that is easiest to keep", "The one that sounds most impressive", "The one that covers the most situations"], answer: 0, explanation: "The costly line is the reason the code exists. The rest is largely decoration." }] },
    { title: "The Person You Are Becoming", why: "You are not deciding what to do next; you are deciding who you are turning into, one ordinary day at a time.", lesson: "Every habit in these hundred days was a vote. Not a dramatic one — nobody becomes anything in a single afternoon — but repeated across months, the small decisions accumulate into a person with particular capacities and particular limits. That is the honest frame for everything you have built. The question is not what will you achieve, because achievements are partly outside your control. It is who are you turning into, which is almost entirely inside it. Look at what your ordinary week is currently producing, and ask whether it is producing someone you would want to be.", keyIdea: "Your ordinary week is producing a person. Check whether it is the one you want.", example: "You do not decide to become patient. You handle forty small things without snapping and, a year later, you are someone who does not snap.", actionPrompt: "Look at your ordinary week and write down who it is currently producing.", actionHint: "Judge the week, not the intentions. What repeats is what is forming.", bonus: "Change one repeating thing in the week so it points at the person you named.", quiz: [{ question: "What actually turns you into a particular kind of person?", options: ["What repeats in your ordinary week", "The decisions you make at key moments", "What you intend to become", "Your natural character"], answer: 0, explanation: "Accumulation across ordinary days is the mechanism. Key moments mostly reveal what was already built." }, { question: "Which question is more useful?", options: ["Who am I turning into", "What will I achieve", "What do I want", "What am I capable of"], answer: 0, explanation: "Achievements are partly outside your control. What you are becoming is almost entirely inside it." }, { question: "You want to become more patient. What does that actually require?", options: ["Handling many small things without snapping, over months", "Deciding to be patient", "A significant test that proves it", "Understanding why you lose patience"], answer: 0, explanation: "Nobody becomes patient in an afternoon. The forty small instances are the whole process." }, { question: "Your week is producing someone you would not want to be. What is the strongest response?", options: ["Change one repeating thing in it", "Change your intentions", "Set a larger goal", "Wait for circumstances to change"], answer: 0, explanation: "The week is the machine. Adjusting one repeating input is how its output changes." }, { question: "How should you judge your progress here?", options: ["By what repeats, not by what you intend", "By how much you have improved", "By comparison with others", "By how you feel about yourself"], answer: 0, explanation: "Intentions are unreliable evidence. Repetition is visible and honest." }, { question: "Someone says they will become disciplined once they have a reason to be. What is the accurate reply?", options: ["The reason does not build the capacity; the ordinary days do", "That is reasonable", "They should find a reason first", "Discipline cannot be built deliberately"], answer: 0, explanation: "The capacity has to exist before the moment that requires it, and it is built when nothing is at stake." }, { question: "Someone says they will change once something significant happens to them. What is the accurate reply?", options: ["The change is made by ordinary weeks, not by events", "They should wait for the right moment", "Significant events do change people", "They need a stronger reason first"], answer: 0, explanation: "Events reveal what was already built. They do not do the building." }, { question: "Which change would most affect who you are becoming?", options: ["One thing that happens every week", "One large decision this year", "A new goal", "A better understanding of yourself"], answer: 0, explanation: "Frequency is the multiplier. A weekly change compounds in a way a single decision does not." }] },
    { title: "Your Real Work Begins", why: "The hundred days were not the achievement; they were the preparation for what you do now.", lesson: "You have covered starting, attention, habits, responsibility and discipline; salah, Qur’an, dhikr and dua, sabr, shukr, tawakkul, the nafs, tawbah and akhlaq; understanding people, listening, trust and boundaries; sleep, energy and pace; building, prototyping and finishing; voice, presence and confidence; responsibility, decisions, developing people and fairness; and what a good life means to you. None of that was the point. The point is the person walking away from it and what they do on an ordinary Tuesday in four months. So answer two questions honestly, write them somewhere you will see them, and then go and do the first one. That is all that is left.", keyIdea: "Decide who you are going to be, and what you are doing next. Then go and do it.", example: "You close the course, and on the following Tuesday — with no lesson, no streak and nobody watching — you do the thing anyway. That is the whole result.", actionPrompt: "Answer both questions in writing: what kind of person am I going to be, and what am I doing next?", actionHint: "Specific and dated for the second one. It should start this week, not at some future point.", bonus: "Do the first step of it today, before the course is closed.", quiz: [{ question: "What was the actual point of the hundred days?", options: ["The person walking away from them", "Completing all one hundred lessons", "Learning the material", "Building a streak"], answer: 0, explanation: "Completion, material and streak were all instruments. The person is the output." }, { question: "What is the honest test of whether the course worked?", options: ["What you do on an ordinary Tuesday in four months", "Whether you finished all hundred days", "How much you can remember", "How you feel at the end"], answer: 0, explanation: "No lesson, no streak, nobody watching — that is the condition the whole course was preparing you for." }, { question: "You are asked what you are doing next and give a general answer. What is missing?", options: ["Something specific, dated, that starts this week", "Enthusiasm", "A longer-term vision", "A reason"], answer: 0, explanation: "General answers do not start. A dated first step this week is what turns the ending into a beginning." }, { question: "Six weeks after the course you have drifted. What is the strongest response?", options: ["Return to the smallest version today", "Redo the hundred days", "Accept that it did not stick", "Wait for a natural restart point"], answer: 0, explanation: "Returning without drama is the single most practised skill in the entire course. This is where it is used." }, { question: "Which of the hundred days matters most from here?", options: ["Whichever one addresses what you are weakest at now", "Day 1, because starting matters", "The Deen section", "Day 100"], answer: 0, explanation: "The course becomes a reference. What you return to should be decided by your actual weak point." }, { question: "What should the second question produce?", options: ["A first step you can take today", "A plan for the year", "A statement of intent", "A list of goals"], answer: 0, explanation: "Everything else in the course pointed at action. It would be strange to end on a paragraph." }, { question: "Someone asks whether they should start the hundred days again. What is the accurate reply?", options: ["The material is there to return to; the point now is to use it", "Yes, repetition would help", "No, they should move on entirely", "Only if they did not finish properly"], answer: 0, explanation: "Repeating the structure is comfortable. Applying it without the structure is the actual next stage." }, { question: "What is the last thing this course asks of you?", options: ["Decide who you are going to be, and do the first thing today", "Review everything you have learned", "Set goals for the year ahead", "Reflect on how far you have come"], answer: 0, explanation: "It ends where it started: a decision turned into one small action, done now." }] },
  ],
];

/* ---------------------------------------------------------------------------
 * Quiz depth
 *
 * Three questions can be passed on recognition alone. Every lesson keeps the
 * questions written for it and is topped up to a target length that grows with
 * the island: ten on Firstlight Cove, fifteen at the Summit, so the check gets
 * more demanding as the material does.
 *
 * Generated questions are built from the lesson's own words. Their distractors
 * are the matching lines from *other* lessons, which makes every wrong option
 * genuinely wrong yet plausible enough to require real discrimination. All
 * selection and shuffling is seeded from the day number, so a learner returning
 * to a day sees exactly the quiz they saw before.
 * ------------------------------------------------------------------------ */

/** Ten questions on island one, rising evenly to fifteen on island ten. */
export const questionCountForPhase = (phaseId: number) => 10 + Math.round(((phaseId - 1) * 5) / 9);

/**
 * How many of a day's questions come back from earlier days. Day one has
 * nothing behind it; after that the share grows with the course.
 */
export const reviewSlotsFor = (day: number, phaseId: number) =>
  day === 1 ? 0 : Math.min(7, Math.max(2, questionCountForPhase(phaseId) - 8));

/** The full length of a day's check, static questions plus review. */
export const totalQuestionsForDay = (day: number) => {
  const lesson = getLesson(day);
  return lesson.quiz.length + reviewSlotsFor(day, lesson.phase.id);
};

/** Understanding is shown at roughly seven in ten, whatever the quiz length. */
export const passMark = (questionCount: number) => Math.ceil(questionCount * 0.7);

/** Small deterministic PRNG, so a given day always builds the same quiz. */
const seeded = (seed: number) => {
  let state = ((seed + 1) * 2654435761) >>> 0;
  return () => {
    state = (state * 1664525 + 1013904223) >>> 0;
    return state / 4294967296;
  };
};

const shuffled = <T>(items: T[], random: () => number) => {
  const copy = [...items];
  for (let index = copy.length - 1; index > 0; index--) {
    const swap = Math.floor(random() * (index + 1));
    [copy[index], copy[swap]] = [copy[swap], copy[index]];
  }
  return copy;
};

type GeneratedField = "keyIdea" | "why" | "example" | "actionPrompt" | "bonus";

const fieldPrompts: { field: GeneratedField; question: (lesson: Lesson) => string; explain: (lesson: Lesson) => string }[] = [
  { field: "keyIdea", question: (lesson) => `Day ${lesson.day}, “${lesson.title}” — which idea is at its heart?`, explain: (lesson) => `The lesson turns on this: ${lesson.keyIdea}` },
  { field: "why", question: (lesson) => `Why does “${lesson.title}” matter?`, explain: (lesson) => lesson.why },
  { field: "example", question: (lesson) => `Which example shows “${lesson.title}” at work?`, explain: (lesson) => lesson.example },
  { field: "actionPrompt", question: (lesson) => `What does “${lesson.title}” actually ask you to do?`, explain: (lesson) => `The day is complete once you have done this: ${lesson.actionPrompt}` },
  { field: "bonus", question: (lesson) => `Which optional challenge belongs to “${lesson.title}”?`, explain: (lesson) => `The bonus is optional, and it is this: ${lesson.bonus}` },
];

/** Two questions are authored into every lesson: they are about the method,
 *  not the day, so they must not count as island-specific material. */
const AUTHORED_METHOD_QUESTIONS = new Set([
  "What should happen after you understand a useful idea?",
  "How should you respond if you miss a step?",
]);

/** Authored prompts that say "this lesson" cannot travel into a mixed check. */
const nameTheLesson = (question: string, lesson: Lesson) =>
  question
    .replace("Which answer best captures today’s lesson?", `Day ${lesson.day}, “${lesson.title}” — which answer best captures it?`)
    .replace("What is the purpose of Day 1?", `What is the purpose of Day 1, “${lesson.title}”?`);

/** Questions about the course's own method, rotated so days do not repeat. */
const methodBank: QuizQuestion[] = [
  { question: "What has to happen before a day can be completed?", options: ["A short check of understanding, then a named real action", "A long reflection", "A perfect score", "Reading the lesson twice"], answer: 0, explanation: "Understanding is checked first, and the day completes only when you name a real action." },
  { question: "What makes an action worth recording?", options: ["It is specific enough that you would know whether you did it", "It sounds impressive", "It covers every part of your life", "It can be finished instantly"], answer: 0, explanation: "A specific action can be carried out and checked. A vague intention cannot." },
  { question: "What do the practice marks in this course measure?", options: ["Activity, not your worth or your faith", "How disciplined a person you are", "Whether you deserve reward", "How you compare with other learners"], answer: 0, explanation: "Progress markers describe activity. They are not a measure of worth, character or faith." },
  { question: "You return after several missed days. What does the route ask?", options: ["Take the current step honestly", "Start the whole course again", "Complete every missed day first", "Wait until you feel ready"], answer: 0, explanation: "The route asks for a return, not a performance or a penalty." },
  { question: "What is the role of the reflection you write?", options: ["It helps carry the learning forward, but is not proof on its own", "It is the main proof of learning", "It replaces the action", "It is only for the final test"], answer: 0, explanation: "Reflection supports the learning. Understanding and action are what the day requires." },
  { question: "How does this course treat an idea from outside Islam?", options: ["It can be considered carefully, but is never presented as identical to Islam", "It is rejected without thought", "It is treated as equal to revelation", "It is used only for decoration"], answer: 0, explanation: "Useful ideas are considered thoughtfully, and no outside framework is presented as identical to Islam." },
  { question: "What does the One Percent Philosophy actually claim?", options: ["A small improvement becomes powerful when understood, applied and returned to", "Small effort guarantees fast results", "One percent daily growth compounds automatically", "Only large changes are worth making"], answer: 0, explanation: "The strength of a small improvement comes from understanding, application and return." },
  { question: "What is the honest response to a day you finished badly?", options: ["Notice what happened, and choose the next useful step", "Decide the effort has failed", "Double tomorrow's work to compensate", "Avoid recording it"], answer: 0, explanation: "A poor day is information to act on, not a verdict to carry." },
  { question: "Why does each island have its own landscape and landmark?", options: ["A distinct place gives the phase's lessons somewhere to be remembered", "It makes the course look like a game", "It rewards faster learners", "It hides the lessons behind decoration"], answer: 0, explanation: "The islands are memory environments: one place, one landmark, one cue per ten days." },
  { question: "What does self-discipline mean in this course?", options: ["Doing what matters when it is time to do it, and returning after a slip", "Never resting", "Ignoring how you feel", "Working until exhaustion"], answer: 0, explanation: "Mature discipline is doing the right next thing at the right time, with honest recovery." },
  { question: "A lesson conflicts with what you already believe. What is useful first?", options: ["Understand it accurately before accepting or rejecting it", "Reject it immediately", "Accept it without testing", "Skip the day"], answer: 0, explanation: "Understanding an idea properly comes before judging it." },
  { question: "What is the purpose of the bonus challenge?", options: ["An optional harder application for a day you have capacity", "A requirement for completion", "A way to skip ahead", "A test of willpower"], answer: 0, explanation: "The bonus is optional. Completing the day never depends on it." },
  { question: "How should the hundred days end?", options: ["With a method you keep using, not a finished person", "With every habit permanently fixed", "With a final score", "With nothing left to learn"], answer: 0, explanation: "The course builds a way of working that continues after Day 100." },
  { question: "What makes a knowledge check useful?", options: ["Being asked to retrieve an idea shows whether you hold it", "It proves you read carefully", "It makes the lesson feel harder", "It records a score for later"], answer: 0, explanation: "Retrieving an idea is a far better test of understanding than re-reading it." },
];

/**
 * Build one day's check.
 *
 * The composition matters more than the length. A check made only of questions
 * about the day just read tests nothing but short-term memory, so every day
 * after the first also asks about earlier days — spaced review is what turns a
 * lesson into something retained. Method questions are capped at two, because a
 * check should mostly be about the course's content, not its rules.
 */
const buildQuiz = (lesson: Lesson, everyLesson: Lesson[]): QuizQuestion[] => {
  const target = questionCountForPhase(lesson.phase.id) - reviewSlotsFor(lesson.day, lesson.phase.id);
  const random = seeded(lesson.day);

  // Authored questions list their correct option first. Shuffle every question's
  // options so position is never a tell — seeded, so it stays put between visits.
  const reorder = (question: QuizQuestion): QuizQuestion => {
    const options = shuffled(question.options, random);
    return { ...question, options, answer: options.indexOf(question.options[question.answer]) };
  };

  const authored: QuizQuestion[] = [];
  const method: QuizQuestion[] = [];
  for (const question of lesson.quiz) {
    const shaped: QuizQuestion = {
      ...reorder(question),
      question: nameTheLesson(question.question, lesson),
      scope: AUTHORED_METHOD_QUESTIONS.has(question.question) ? "method" : "lesson",
    };
    (shaped.scope === "method" ? method : authored).push(shaped);
  }

  const questions: QuizQuestion[] = [...authored];
  const seen = new Set(questions.map((question) => question.question));

  // Questions drawn from this lesson's own wording.
  for (const prompt of shuffled(fieldPrompts, random)) {
    const promptText = prompt.question(lesson);
    if (seen.has(promptText)) continue;
    const correct = lesson[prompt.field];
    const pool = everyLesson.filter((other) => other.day !== lesson.day).map((other) => other[prompt.field]).filter((value) => value !== correct);
    const distractors = shuffled(pool, random).slice(0, 3);
    if (distractors.length < 3) continue;
    const options = shuffled([correct, ...distractors], random);
    questions.push({ question: promptText, options, answer: options.indexOf(correct), explanation: prompt.explain(lesson), scope: "lesson" });
    seen.add(promptText);
  }

  // Two method questions, then the bank if a day is still short (day one has
  // nothing to review yet, so it leans on the bank instead).
  for (const question of method) {
    if (questions.length >= target || seen.has(question.question)) continue;
    questions.push(question);
    seen.add(question.question);
  }
  const offset = (lesson.day * 5) % methodBank.length;
  for (let step = 0; step < methodBank.length && questions.length < target; step++) {
    const question = methodBank[(offset + step) % methodBank.length];
    if (seen.has(question.question)) continue;
    const options = shuffled(question.options, random);
    questions.push({ ...question, options, answer: options.indexOf(question.options[question.answer]), scope: "method" });
    seen.add(question.question);
  }

  return questions.slice(0, target);
};

const baseLessons: Lesson[] = topics.flatMap((phaseTopics, phaseIndex) =>
  phaseTopics.map((topic, topicIndex) => ({
    ...topic,
    day: phaseIndex * 10 + topicIndex + 1,
    phase: phases[phaseIndex],
  })),
);

export const lessons: Lesson[] = baseLessons.map((lesson) => ({ ...lesson, quiz: buildQuiz(lesson, baseLessons) }));

export const getLesson = (day: number) => lessons.find((lesson) => lesson.day === day) ?? lessons[0];

/** The ten lessons of one island, in route order. */
export const lessonsForPhase = (phaseId: number) => lessons.filter((lesson) => lesson.phase.id === phaseId);

/**
 * The recheck sitting at the end of an island: eight questions sampled across
 * its ten days, so passing needs the whole stretch rather than the last lesson.
 */
export const RECHECK_LENGTH = 8;

export const buildRecheck = (phaseId: number): QuizQuestion[] => {
  const random = seeded(1000 + phaseId);
  const island = lessonsForPhase(phaseId);
  const picked: QuizQuestion[] = [];
  const seen = new Set<string>();
  // Take one question from each day first, so every lesson is represented.
  for (const lesson of shuffled(island, random)) {
    if (picked.length >= RECHECK_LENGTH) break;
    const candidates = lesson.quiz.filter((question) => question.scope === "lesson" && !seen.has(question.question));
    if (!candidates.length) continue;
    const question = candidates[Math.floor(random() * candidates.length)];
    picked.push(question);
    seen.add(question.question);
  }
  return picked;
};

/* ---------------------------------------------------------------------------
 * Adaptive review
 *
 * Review is only worth the questions it spends. Rather than sampling earlier
 * days at random, a day is chosen by how shaky it looks: material the learner
 * has missed comes back soonest and most often, material they have answered
 * correctly several times drops back, and a day that has not been seen for a
 * long time rises again on its own. This is the part that turns a hundred
 * separate lessons into something retained.
 * ------------------------------------------------------------------------ */

/** What the journal remembers about one earlier day's material. */
export type RecallRecord = { seen: number; missed: number; lastReviewedDay?: number };

/**
 * Lower is stronger. A day that has never been reviewed sits mid-table so it
 * gets picked up; every miss pushes it sharply to the front of the queue.
 */
export const recallWeight = (day: number, currentDay: number, record: RecallRecord | undefined) => {
  const gap = Math.max(0, currentDay - (record?.lastReviewedDay ?? day));
  const misses = record?.missed ?? 0;
  const hits = Math.max(0, (record?.seen ?? 0) - misses);
  // Strength falls withcorrect answer and rises steeply with each miss.
  const strength = hits - misses * 3;
  return strength * 10 - gap;
};

/**
 * Pick review questions for a day. Days are ranked weakest first, each
 * contributes at most one question, and selection stays deterministic for a
 * given journal so returning to a day shows the same check.
 */
export const selectReview = (
  day: number,
  count: number,
  recall: Record<number, RecallRecord>,
  completedDays: number[],
): QuizQuestion[] => {
  if (count <= 0) return [];
  const behind = completedDays.filter((earlier) => earlier < day).sort((a, b) => a - b);
  if (!behind.length) return [];
  const random = seeded(day * 31);

  const ranked = behind
    .map((earlier) => ({ day: earlier, weight: recallWeight(earlier, day, recall[earlier]) }))
    .sort((a, b) => a.weight - b.weight || b.day - a.day);

  const picked: QuizQuestion[] = [];
  const seen = new Set<string>();
  for (const entry of ranked) {
    if (picked.length >= count) break;
    const pool = getLesson(entry.day).quiz.filter((question) => question.scope === "lesson" && !seen.has(question.question));
    if (!pool.length) continue;
    const question = pool[Math.floor(random() * pool.length)];
    picked.push({ ...question, scope: "review", fromDay: entry.day });
    seen.add(question.question);
  }
  return picked;
};

/* ---------------------------------------------------------------------------
 * The Summit quest
 *
 * The course does not end on a longer quiz. It ends on two trials taken in
 * order: one that asks whether the hundred days are still in reach, and one
 * that asks whether they changed how a decision gets made. Recall is sampled
 * across every island; judgment is hand-written, one scenario per island.
 * ------------------------------------------------------------------------ */

export const FINAL_RECALL_LENGTH = 15;

/** Fifteen questions spread evenly across all ten islands. */
export const buildFinalRecall = (): QuizQuestion[] => {
  const random = seeded(9001);
  const picked: QuizQuestion[] = [];
  const seen = new Set<string>();
  // Walk the islands in a shuffled order, repeatedly, so every island is
  // represented before any island contributes a second question.
  for (let pass = 0; pass < 2 && picked.length < FINAL_RECALL_LENGTH; pass++) {
    for (const phase of shuffled(phases, random)) {
      if (picked.length >= FINAL_RECALL_LENGTH) break;
      const pool = lessonsForPhase(phase.id).flatMap((lesson) => lesson.quiz).filter((question) => question.scope === "lesson" && !seen.has(question.question));
      if (!pool.length) continue;
      const question = pool[Math.floor(random() * pool.length)];
      picked.push(question);
      seen.add(question.question);
    }
  }
  return picked;
};

/** One judgment scenario per island, in route order. */
export const finalScenarios: (QuizQuestion & { cue: string })[] = [
  { cue: "Firstlight Cove", question: "You miss several planned actions in a difficult week. What best reflects the course method?", options: ["Restart the entire course from Day 1", "Treat the miss as information, return to the current waypoint, and choose one honest next action", "Add more tasks to compensate", "Wait until motivation returns"], answer: 1, explanation: "A gap is information, not a verdict. The route asks for a return and one honest step — not a restart, a penalty, or a wait." },
  { cue: "Lantern Gardens", question: "A choice looks productive but slowly harms your character and responsibilities. What should guide your decision?", options: ["What gives the fastest visible result", "What other people will praise", "Clear intention, sound character, and what you can responsibly sustain", "The most difficult option"], answer: 2, explanation: "Intention and character come before visible output. Work that quietly costs you your responsibilities is not productive." },
  { cue: "Training Ridge", question: "You only act when you feel motivated. What is the next useful experiment?", options: ["Build one small repeatable cue that lowers the barrier to beginning", "Wait for a stronger feeling", "Make a larger promise", "Stop setting goals"], answer: 0, explanation: "Motivation is welcome but unreliable. A system makes the right action easier to begin on an ordinary day." },
  { cue: "Sakina Point", question: "You have let a daily practice slip for over a week, and starting again feels pointless. What does Sakina Point ask you to do first?", options: ["Wait until the start of a new month so you can begin properly", "Return to it at the very next opportunity, without settling the whole week first", "Decide you are not someone who keeps things up", "Do a large amount at once to make up the gap"], answer: 1, explanation: "Returning is the practice. A gap is information rather than a verdict, and the next opportunity is always the right one to take." },
  { cue: "Bridgehaven", question: "A relationship feels distant after a misunderstanding. What is the strongest next step?", options: ["Win the argument in your head", "Make one respectful attempt to listen, clarify, or repair", "Avoid them indefinitely", "Ask someone else to take sides"], answer: 1, explanation: "Repair is an action, not a feeling. One respectful attempt to listen does more than any amount of private rehearsal." },
  { cue: "Wildwood Valley", question: "Your energy is low and you have been forcing more output. What is the mature response?", options: ["Ignore your body because discipline means never resting", "Identify one recovery practice that protects tomorrow's useful effort", "Quit every commitment", "Buy a new productivity system"], answer: 1, explanation: "Discipline includes protecting the energy the work depends on. Recovery is part of sustainable effort, not a retreat from it." },
  { cue: "Maker’s Quay", question: "You want to become more skilled. Which action creates the most useful evidence?", options: ["Consume more advice without practising", "Make a small real thing, review it, and improve the next version", "Wait until you feel talented", "Copy someone else's work exactly"], answer: 1, explanation: "Skill shows up in made things. A small finished attempt teaches more than any amount of collected advice." },
  { cue: "Value Harbour", question: "You receive money or opportunity through your work. What should remain central?", options: ["Creating useful value responsibly and managing what you earn with care", "Showing people how successful you are", "Taking the fastest option regardless of impact", "Avoiding all decisions about money"], answer: 0, explanation: "Value creation and responsible stewardship stay central. Display and speed are not the measure." },
  { cue: "Common Ground", question: "You are asked to lead a group task. What does the Common Ground perspective emphasise?", options: ["Doing everything yourself to stay in control", "Using the role to gain status", "Making responsibility clearer, listening well, and helping the group move", "Waiting for someone else to decide"], answer: 2, explanation: "Leadership here is service: clarify responsibility, listen properly, and help the group move." },
  { cue: "The Summit", question: "After 100 days, what does the Summit actually ask of you?", options: ["Prove you are now perfect", "Keep using the method with humility when life changes", "Collect a final score and stop reflecting", "Repeat only your favourite lessons"], answer: 1, explanation: "The course is a foundation for continuing, not a finish line. The method matters more than the score." },
];

/** The two trials, in the order they must be taken. */
export const finalTrials = [
  { id: 0, name: "Trial of Recall", blurb: "Fifteen questions drawn from across all ten islands. It asks whether the hundred days are still within reach.", length: FINAL_RECALL_LENGTH },
  { id: 1, name: "Trial of Judgment", blurb: "Ten situations with no lesson in front of you, one from each island. It asks whether the course changed how you decide.", length: finalScenarios.length },
] as const;

export const buildTrial = (trial: number): QuizQuestion[] =>
  trial === 0 ? buildFinalRecall() : finalScenarios.map(({ cue: _cue, ...question }) => question);

export { phases };
